INSERT INTO public.achievement VALUES (1, 2, 162, '中国科学院深圳先进技术研究院', '仿生灵巧手系统', 9, '围绕具身智能系统对复杂操作任务的需求，基于高性能电机本体、电力电子技术、嵌入式系统、计算机技术、智能控制算法等软硬件系统，开发多自由度仿生灵巧手系统，实现对人手结构和功能的模仿。仿生灵巧手系统具有与人手类似的灵活度，具备替代人手完成复杂任务的潜力。通过搭配高精度传感器、高性能电机系统、耐腐机壳等硬件系统，仿生灵巧手可以在耐高低温和腐蚀、位置和触觉控制精度，以及力量等方面具备超越人手的优势。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "微型小电感电机驱动控制\n多传感器融合\n高集成机电系统开发"}, {"title": "技术成熟度", "content": "完成实验室院里验证"}, {"title": "项目支持", "content": "国家重点研发计划项目\n广东省自然科学基金青年提升项目\n深圳市科技重大专项"}, {"title": "可应用领域", "content": "工业自动化、具身智能、消费类等"}]', 'negotiable', NULL, NULL, '孙天夫', NULL, '13828858818', 'tf.sun@siat.ac.cn', NULL, 'published', NULL, 2, 28, '2026-09-11 11:31:31.267051+08', '2026-06-18 10:14:16+08', '2026-09-18 08:33:41.853976+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
