INSERT INTO public.achievement VALUES (25, 2, 162, '中国科学院深圳先进技术研究院', '水下触觉传感器和其制备方法', 13, '专利号：ZL202011433572.0', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有水下压力传感器在封装和水压调节方面存在困难，导致传感器体积增大、柔性降低和测量准确性降低，且现有的离电式传感器尚未应用于水下环境。"}, {"title": "技术功效与成熟度", "content": "水下触觉传感器通过新型传感单元设计，无需封装的传感结构，可以实现水下机器人在深海环境下的精细控制。技术当前完成实验室样机制备。"}, {"title": "应用场景及市场规模", "content": "水下光线极差、视野模糊等问题给水下机器人任务执行带来挑战，诸如电子元器件漏水、短路问题；水下封装带来的整体器件尺寸增加问题；水下高静水压挑战问题等。针对海洋传感器市场，特别是水下无人潜航器、微型化水下滑翔机等具备较大优势。"}, {"title": "技术手段", "content": "采用柔性电路板与弹性体层结合，形成叉指电极，并通过弹性体凸起形成通道以便环境流体进入和排出，构成反离电式触觉传感器，避免封装工艺处理，保持轻薄和柔性特点，并通过通道与外界相通以平衡水压差。"}]', 'negotiable', NULL, NULL, '程玙团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 19:26:47+08', '2025-12-09 19:26:47+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (807, 1, NULL, '深圳大学', '二维氧化物气凝胶', NULL, '针对传统隔热材料"热导率高、耐温性不足、脆性大"的行业痛点，团队采用新型合成技术，简便制得高强度、高韧性、耐超高温的二维氧化物气凝胶。该材料在各个温度段均具有最低的热导率，可耐极高温（2000°C仍保持稳定），且具备高强高韧的力学性能，在极端环境热防护领域具有显著技术优势。
全温段最低热导率，兼具优异力学性能
耐温等级突破至2000℃
原料与合成路线全新，低成本，易放大
航空航天：飞行器热防护系统、发动机隔热罩
建筑领域：建筑防火隔热
新能源汽车：电池组热失控防护、电机隔热
