INSERT INTO public.achievement VALUES (176, 2, 162, '中国科学院深圳先进技术研究院', '双温区热响应智能玻璃及其建筑节能应用', 14, '围绕低碳生产及应用需求，结合多功能性和材料本征的热学相变性能，研发出具有双温区独立可控的热响应智能窗户。该窗户兼具确保白天采光、正午遮光及夜晚隐私保护功能，可根据所在地气候与维度调整热响应温区，从而有效降低建筑能耗，满足现代建筑节能需求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "零能耗：通过外部气温智能调控环境光强度和温度\n具双重热响应点，确保白天采光、正午遮光及夜晚隐私保护\n高灵活性：可根据当地气候和纬度，独立调整热响应临界点"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "高层建筑、住宅和办公场所等玻璃幕墙；车站、机场、会议中心等大面积玻璃建筑；智能温室、节能型农业大棚。"}]', 'negotiable', NULL, NULL, '丁宝福', NULL, '18818538834', 'bf.ding@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:52:57+08', '2025-04-15 10:52:57+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (181, 2, 162, '中国科学院深圳先进技术研究院', '自研国产边缘智能AI实时处理模组', 9, '随着人工智能（AI）和物联网（IoT）的快速发展，数据量呈指数级增长。传统的云计算架构因数据传输延迟、带宽压力和隐私问题，逐渐暴露出局限性。边缘智能计算应运而生，将计算能力下沉到靠近数据源的边缘设备，结合AI技术实现实时分析和处理，成为智能化的重要方向。本项目基于国自然、广东省重点研发等项目的前期积累，依托团队在计算机系统架构与实时系统的核心技术，自研基于国产芯片的AI实时处理模组，针对不同的传感器（摄像头、红外、雷达等）进行定制。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "实时性：大于50FPS；\n灵活性：不同AI模型部署\n低功耗：功耗低于15W"}, {"title": "技术成熟度", "content": "原理样机得到验证，可直接部署在不同实际环境中。"}, {"title": "项目支持", "content": "国家自然科学青年基金\n广东省重点领域研发计划“新一代人工智能”\n工信部新一代信息通信产业集群项目"}, {"title": "可应用领域", "content": "工业制造、智能交通、安防、农业与环境、能源等"}]', 'negotiable', NULL, NULL, '陈超', NULL, '16657040738', 'chao.chen@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:33:49+08', '2025-04-15 10:33:49+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (183, 2, 162, '中国科学院深圳先进技术研究院', 'AIA-IDs：智慧数据管理系统', 9, '以智能体平台为底座，融合多模态大模型、图像/视频生成模型，针对文件数据管理与应用开发的数据管理系统。可以针对不同类别与模态数据，实现跨模态数据检索；围绕图文数据实现多模态数据问答；针对不同的垂直场景，实现图文写作；自动实现文本驱动的图像/视频生成与编辑。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "文件解析与索引：通过视觉模型对文件进行精准布局解析（如文本、图像、表格、公式等）并进行存储与索引，打破不同类型和模态之间的数据壁垒；\n多模态检索：支持多模态输入并对齐，能够对不同模态的数据进行精准匹配与关联；\n多人协同图文写作：基于多模态大模型，支持多人协同完成图文融合写作；\n可控通用图像编辑：利用智能体实现不同任务算法的自动调度，实现通用图像编辑"}, {"title": "技术成熟度", "content": "已经完成系统原型开发，可快速针对不同应用场景进行部署，针对不同行业与场景，通过数据投喂可快速完成垂直行业优化。"}, {"title": "可应用领域", "content": "在广告、档案、政务、金融、医疗等广泛具有大量数据管理与应用的行业都有应用。"}]', 'negotiable', NULL, NULL, '陈世峰', NULL, NULL, 'shifeng.chen@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:30:04+08', '2025-04-15 10:30:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (208, 2, 162, '中国科学院深圳先进技术研究院', '一种合成原儿茶酸的重组酵母菌株及其构建方法与应用', 16, '原儿茶酸，又名 3，4-二羟基苯甲酸，主要应用于医药合成、有机中间体合成、染料合成和化学试剂等领域，并且是多种医药产品如埃罗替尼（抗肿瘤药）、藜芦定（钠通道失活门抑制剂）、盐酸麦皮凡林(呼吸系统药物)、胡黄连苷 II（治疗乙型肝炎药）、盐酸伊托必利（新型促胃肠动力药）、益迷兴（麻醉药）等的核心原料。同时，原儿茶酸本身也具有抗菌作用，还具有祛痰、平喘作用，临床用于治疗慢性气管炎。另外，原儿茶酸也可作为饲料添加剂被大范围使用。本项目通过构建新型酿酒酵母工程菌，实现了以葡萄糖为原料生产原儿茶酸，该法绿色、环保、可持续，并且与化学法相比，具有经济竞争力，有很好的产业应用前景。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "利用先进代谢工程与合成生物学技术，通过从头理性设计和系统优化构建了生产原儿茶酸的酵母工程菌，以葡萄糖无机盐培养基生产原儿茶酸，目前在 1L 发酵罐水平，通过分批补料的方式，通过100小时左右发酵，原儿茶酸产量可达到 80g/L左右，原儿茶酸对葡萄糖的转化率在50%左右，相比化学合成法生产成本更低，且具有环境友好型，技术先进的特点。"}, {"title": "技术成熟度", "content": "在实验室内实现原儿茶酸的公斤级制备，目前已进入中试发酵测试阶段。"}, {"title": "可应用领域", "content": "原儿茶酸可用于医药合成、有机中间体合成、染料合成和化学试剂等领域，也可作为饲料添加剂被大范围使用。\n以高产原儿茶酸的工程菌为基础，拓宽下游产物谱，可实现己二酸和香兰素等多种高附加值衍生化合物的高效、绿色合成。"}]', 'negotiable', NULL, NULL, '于涛', NULL, NULL, 'tao.yu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:14:30+08', '2025-04-14 17:14:30+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (864, 1, NULL, '深圳大学', '成果完成人', NULL, 'Introduction of the Inventor of the Achievement
朱映映，博士，教授，博士生导师，深圳孔雀计划人才
2004年于武汉大学获得博士学位，现任深圳大学计算机与软件学院媒体所常务副所长，担任广东省发改委战略专家、中国计算机学会多媒体技术专委会委员、广东省/深圳市科技计划与高企认定专家等。
主要研究领域及研究方向：人工智能、计算机视觉、智能遥感解译等。以第一/通讯作者发表多篇学术论文，包括在 CCF A 类顶会/中科院一区 TOP 期刊发表30余篇代表性论文；相关成果已经获得 8 项中国/美国发明专利授权。作为项目负责人主持国家自然科学基金项目，广东省自然科学基金项目，深圳市科技创新基础研究学科布局项目及基础研究面上项目等多项国家级、省市级科研项目。
邮箱：
zhuyy@szu.edu.cn
个人主页：https://csse.szu.edu.cn/pages/user/index?id=593
个人照片', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft', NULL, 1, 0, NULL, '2026-09-18 10:27:59.144231+08', '2026-09-18 10:27:59.144231+08', NULL, 1, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, 232);
INSERT INTO public.achievement VALUES (865, 1, NULL, '深圳大学', '（图片/视频 1920*1080）
成果简介（包括但不限于:项目背景、解决的核心问题、核心技术、研发及商业化情况等，字数800字以内）：
成果照片（样机、产品)
纤维辐射制冷涂层
自清洁涂层表面', NULL, '零碳排放辐射制冷涂层技术
Zero-emission radiative cooling coating technology
被动日间辐射制冷（PDRC）技术作为一种零能耗的建筑热管理策略，可通过降低建筑表面对太阳辐射的吸收，并利用大气窗口向外太空高效辐射自身热量，实现日照条件下的被动降温，在建筑节能降碳和缓解城市热岛效应方面具有重要应用潜力。PDRC技术从实验室向实际规模化应用跨越两个关键瓶颈在于：一是高太阳反射率通常依赖多孔结构材料，但其往往难以同时满足建筑应用所需的基材附着力、机械强度和长期耐候性；二是现有高性能PDRC材料多依赖复杂工艺或高成本原料，难以实现原位、可拓展和低成本的大面积制备。黄龙标团队创新性引入溶液吹纺技术，以高速风场替代静电纺丝高压电场，采用易成纤高分子作为纤维核心、高耐候树脂作为包覆外壳，首次在建筑表面原位构筑核壳结构纤维型辐射制冷涂层，开创了纤维结构PDRC涂层的新范式。该技术通过三维纤维骨架和多尺度空气/固体界面协同增强太阳光散射，同时依托耐候树脂外壳赋予涂层优异的基材附着、机械完整性和环境耐久性，有效解决了传统多孔涂层“高反射但脆弱”、静电纺丝纤维膜材料“难以原位制备且缺乏独立附着力”等应用缺陷。目前，团队已完成配方设计、原位喷涂工艺优化、户外耐候性测试及建筑模拟应用研发，形成了技术成熟的辐射制冷涂料产品，并即将在中建三局深圳超级总部项目开展工程化应用，有望推动辐射制冷技术大规模服务于建筑节能降碳和低碳城市建设。
安全节能环保：节能技术
首次通过溶液吹纺技术制备出纤维结构辐射制冷涂层，摆脱了纤维型材料对静电纺丝工艺的依赖，实现了高光学性能和有优秀应用性能辐射制冷涂层大规模制备。
建筑节能（降低~30%建筑制冷能耗）
户外储能柜、电力设施降温
粮仓、化工仓库降温
2026，设立深圳xxx有限公司
技术创新点
所属战略性新兴产业（20+8）
市场前景及应用领域
产业化公司或平台', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft', NULL, 1, 0, NULL, '2026-09-18 10:27:59.151739+08', '2026-09-18 10:27:59.151739+08', NULL, 1, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, 233);
INSERT INTO public.achievement VALUES (866, 1, NULL, '深圳大学', '成果完成人', NULL, 'Introduction of the Inventor of the Achievement
黄龙彪，博士, 教授，博士生导师。
本科毕业于西安交通大学，2014年获得香港城市大学博士学位，曾在西北工业大学理学院担任副教授，2017年起担任深圳大学副教授、教授。
主要研究领域是光电传感与能源器件和绿色能源技术领域，研究方向是辐射制冷材料与柔性传感器。已发表80余篇学术论文，包括发表在 Advanced Materials、Advanced Energy Materials、Advanced Functional Materials, Nano Energy、Small等杂志的一作或通讯论文。相关成果在申专利xxx余项。作为负责人承担目前主持多项国家自然科学基金、广东省自然科学基金、深圳市科技创新委科研项目。
联系方式： 26906861
联系邮箱： huanglb@szu.edu.cn
个人网站：https://cpoe.szu.edu.cn/szxq.jsp?urltype=tp.TpTeacherDetail&wbtreeid=1111&id=1779754308499607554&dm=huanglongbiao_1&language=0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'draft', NULL, 1, 0, NULL, '2026-09-18 10:27:59.160696+08', '2026-09-18 10:27:59.160696+08', NULL, 1, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, 234);
INSERT INTO public.achievement VALUES (99, 2, 162, '中国科学院深圳先进技术研究院', '非人灵长类动物抑郁症模型', 15, '基于自主研发的非人灵长类（猕猴）神经精神疾病的行为学检测技术，结合视频分析、机器学习及光电传感技术等，优化实验检测技术，精准捕捉疾病相关行为，数据采集灵敏度高、客观性强、并且增加了数据维度，可用于潜在治疗药物筛选及其他诊疗方法有效性检测。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "行为学、生理生化、影像多维度评估；\n数据更准确、客观；\n可以收集更多维度的精确数据；\n配套自动化数据分析和处理软件，\n一键出图，后台数据存储，方便后期数据深度挖掘分析；"}, {"title": "技术成熟度", "content": "已经建立标准技术流程，采集抑郁、奖赏缺失、睡眠、体重、焦虑等行为学、血液、毛发、脑脊液、脑组织、脑影像，脑电生理等技术指标。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省基础与应用基础研究项目\n深圳市药物成瘾重点实验室项目\n深港脑科学创新研究院项目"}, {"title": "可应用领域", "content": "针对抑郁症等疾病的各种药效检测，诊疗新技术检测，认知功能检测。"}]', 'negotiable', NULL, NULL, '孟志强', NULL, '18824235390', 'zq.meng@siat.ac.cn', NULL, 'published', NULL, 1, 1, '2025-09-15 10:24:58+08', '2025-09-15 10:24:58+08', '2026-09-17 14:53:26.201803+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (193, 2, 162, '中国科学院深圳先进技术研究院', '高性能多通道神经肌肉电生理信号采集系统', 9, '神经肌肉电生理信息可用于了解人体神经肌肉系统的工作机制及功能状态，探索神经肌肉系统疾病及功能障碍的有效治疗及康复方法，解码运动意图、建立人机交互接口。开发了高性能多通道神经肌肉电生理信号采集系统，可实现肌电、神经电、脑电信号的高质量测量，适应实验室数据采集、运动可穿戴等不同应用场景，适配多种类型电极。
Neuromuscular electrophysiological data help us understand the underlying mechanisms and functional states of the human neuromuscular system. They also support the development of treatments and rehabilitation methods for neuromuscular disorders, enable motor intent decoding, and facilitate human–machine interaction. We have developed a high-performance, multi-channel acquisition system for neuromuscular electrophysiological signals. It enables reliable recording of electromyography (EMG), electroneurography (ENG), and electroencephalography (EEG). The system can be used in different applications, including laboratory data acquisition and wearable motion monitoring, and is compatible with a wide range of electrodes.', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点Key Technical Innovations", "content": "适应多场景：台式、便携式、无线系统\n通道数可选：16、32、64、128通道\n接口种类丰富：支持高密度阵列电极、柔性电极及独立电极\n高质量信号：数据有效位数24位，共模抑制比大于90dB，采样频率最高32kHz\nMulti-Scenario Adaptability: desktop, portable, and wireless configurations\nConfigurable Channels: 16/32/64/128 channels\nVersatile Electrode Interfaces: compatible with high-density array electrodes, flexible electrodes, and individual electrodes\nHigh Signal Quality: 24-bit resolution, >90 dB CMRR, sampling rate up to 32 kHz"}, {"title": "技术成熟度Technology Readiness Level", "content": "小批量生产、小范围应用，并入选2024中国科学院自主研制科学仪器。\nThe system has achieved small-batch production and pilot-scale application, and was selected for the 2024 Scientific Instruments Independently Developed by the Chinese Academy of Sciences. \nScan the QR code below for detailed information."}, {"title": "项目支持Funding", "content": "国家自然科学基金委-国家重大科研仪器项目（834万，2020.01.01-2024.12.31）\nNSFC National Major Scientific Research Instrument Development Project(Funding:RMB 8.34 million, Jan. 1, 2020 – Dec. 31, 2024)"}, {"title": "可应用领域Applications", "content": "肌电、神经电、脑电等电生理信号采集神经肌肉系统相关疾病评估与诊断研究运动功能康复效果评估、人机交互\nAcquisition of electrophysiological signals, including EMG, ENG, and EEG, for the assessment and diagnosis of neuromuscular system-related disorders, evaluation of motor function rehabilitation outcomes, and human–machine interaction."}]', 'negotiable', NULL, NULL, '李光林', NULL, '13923890192', 'gl.li@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 09:59:25+08', '2025-04-15 09:59:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (210, 2, 162, '中国科学院深圳先进技术研究院', '活细胞定向进化系统TADR2.0使能噬菌体疗法与功能蛋白开发', 16, '生命的复杂性导致合成生物技术对于生命的理性设计能力有限，因此需要非理性手段的补充才能实现对生命的设计和改造。定向进化技术是最重要的非理性手段。易啸课题组开发了活细胞定向进化技术TADR，解决了传统定向进化技术的建库瓶颈问题。最新的2.0版本提高了系统的稳定性、突变率并将兼容底盘从细菌扩展到了真核细胞，大大提高了该技术的实用性。应用TADR2.0，易啸课题组已经成功实现在大肠杆菌中快速进化噬菌体裂解新宿菌株，突变子最快12小时即被发现；同时，还大大提高了灵敏度等生物传感器的关键性能。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "TADR2.0是目前唯一人工设计的活细胞定向进化技术，相较其他基于改造自然系统的技术，TADR2.0不受自然进化历史造成的限制，因而具有效率和通用性更高的特点。"}, {"title": "技术成熟度", "content": "经过耗时6年、迭代两个版本，TADR2.0在大肠杆菌中已经成熟，实现了快速进化噬菌体感染新宿主和优化生物传感器性能。该技术在酵母中已经完成原理验证。"}, {"title": "项目支持", "content": "中国科学院百人计划"}, {"title": "可应用领域", "content": "噬菌体疗法、蛋白质工程"}]', 'negotiable', NULL, NULL, '易啸', NULL, '18676393001', 'xiao.yi@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:11:11+08', '2025-04-14 17:11:11+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (191, 2, 162, '中国科学院深圳先进技术研究院', '穿戴式跌倒精准预警防护全程干预系统', 9, '针对让老人“如何少跌倒、跌下少受伤、倒后及时救助”等难题，率先提出老龄安全的“三重干预”精准防跌倒理论与技术，创新实现了“跌前主动预警、跌中自动防护、跌后远程监护”的精准防跌倒解决方案。成功开发了我国首个达到医疗器械注册标准的防跌倒产品，成立了国内首个多学科联合防跌倒门诊，牵头制定并发布了国内首个跌倒风险综合评估的团体标准，2021年成果入选国家“十三五”科技创新成就展，2022年“两会”期间被CCTV《中国养老》专题采访报道。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "①发明了跌前主动预警方法与设备，实现老人危险动作实时监测预警，减少跌倒发生；\n②发明了跌中自动防护技术与装备，实现跌倒瞬间老人髋臀部位自动防护，减轻跌倒损伤；\n③发明了全程精准跌倒干预系统，实现跌倒分级联动精准干预，降低防跌倒成本。"}, {"title": "技术成熟度", "content": "历经10余年持续研发，已完成8代实验室样机系统的迭代更新，并在临床开展应用示范。"}, {"title": "项目支持", "content": "国家重点研发计划\n国家自然科学基金\n中科院、广东省、深圳市项目"}, {"title": "可应用领域", "content": "医疗机构、康复机构、养老机构、健康养老社区和智能居家等。"}]', 'negotiable', NULL, NULL, '赵国如', NULL, '13088800549', 'guoru.zhao@hotmail.com', NULL, 'published', NULL, 1, 0, '2025-04-15 10:07:25+08', '2025-04-15 10:07:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (205, 2, 162, '中国科学院深圳先进技术研究院', '自平衡下肢外骨骼机器人', 9, '面向人民生命健康，帮助四肢瘫患者重新站立行走，实现了无拐自平衡下肢外骨骼机器人系统研发及技术应用。提出了多旋转中心高相容机构设计方法，揭示了人类运动肌肉-韧带的柔顺机理，国内首次实现了搭载多体型穿戴者的自平衡稳定行走；结合人机耦合系统的行走稳定约束条件提出了混合柔顺控制框架，国际首次实现了无需预知地形信息下自平衡外骨骼载人在非结构化地形稳定行走，可极大缓解家庭、医院、社会的看护压力，相关技术应用获得了2023年广东省技术发明一等奖。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "人机高相容：12自由度串并混联，低轴线偏差关节设计，适配155-180cm穿戴者；\n行走高鲁棒：无需个性化调参，国内首次实现搭载多人（0-77kg）自平衡行走；\n地形高适应：无需预知地形信息，国际首次实现自平衡外骨骼载人在5种非结构化地形稳定行走。"}, {"title": "技术成熟度", "content": "7级\n真实环境下的系统演示"}, {"title": "项目支持", "content": "国家自然科学基金\n国家重点研发计划\n广东省自然科学基金\n深圳市基础研究重点项目"}, {"title": "可应用领域", "content": "偏瘫、截瘫、四肢瘫患者\n医疗康复，功能重建\n行走辅助，日常护理\n医院、治疗中心、养老院等"}]', 'negotiable', NULL, NULL, '吴新宇', NULL, NULL, 'xy.wu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:27:53+08', '2025-04-14 17:27:53+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (214, 2, 162, '中国科学院深圳先进技术研究院', 'UV固化有机硅离型剂', 14, '离型剂是一种涂覆在固体基材上，用于减少将粘性物质（如压敏胶，食物，沥青）从基材上剥离的阻力的材料，同时可以起到保护胶层和防粘的作用。离型剂主要分为热固化和UV固化两种。其中，UV固化有机硅离型剂绿色环保，具有无溶剂、固化速度快、生产能耗低等特点。目前团队已经从功能性UV固化硅油的合成与改性出发，经配方体系的设计筛选、优化材料在应用过程中的性能，成功过实现了UV固化离型剂的产品开发。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "①丙烯酸酯含量和粘度可调节范围广 ②性能达到国际先进水平\n③工艺简单、批次稳定性高"}, {"title": "技术成熟度", "content": "完成热固化离型剂的开发、光固化硅油合成、UV固化离型剂配方开发，实现中试产品验证"}, {"title": "可应用领域", "content": "该产品可用于模切制程、标签、胶带及卫生用品的制造与加工"}]', 'negotiable', NULL, NULL, '何睿', NULL, NULL, 'rui.he1@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:33:17+08', '2025-04-14 17:33:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (209, 2, 162, '中国科学院深圳先进技术研究院', '浮萍蛋白开发利用及产业化', 16, '因土地稀缺而大豆需求量大，急需开发不占耕地且高产高蛋白的大豆替什品。浮萍是漂浮在水面的小型植物，生物量大且蛋白含量高于大豆，适宜条件下，一亩水田浮萍于重可达5吨/年,是大豆亩产的10倍以上。本项目以高蛋白、高光合效的浮萍为目标对象，从高通量筛选平台开发。遗传资源发掘与基因控掘、基于合成生物学“LDBT”循环迭代的精准设计育种、全生产周期自适应智能管控模型构建等核心关键技术，大幅度提高其生物质产率、蛋白含量及光合效率，构建低成本、工厂化蛋白生产技术体系集成与应用示范。为增扩蛋白产量、解决蛋白资源短缺提供科技支撑和解决方案，对农业可持续发展和实施“大农业观”、“大食物观”具有重要意义。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "以高蛋白、高光合效的浮萍为目标对象，增扩蛋白产量、解决饲用蛋白资源短缺问题。"}, {"title": "技术成熟度", "content": "已建立国内首个浮萍突变体库、浮萍高效遗传转化体系和基因编辑平台、浮萍开花诱导技术，已研发微生物菌肥促进浮萍增产，已研发浮萍合成生物学底盘技术"}, {"title": "项目支持", "content": "中科院先导专项C\n深圳市基础研究专项"}, {"title": "可应用领域", "content": "饲用蛋白、高蛋白食品和保健品、高附加值生物制品，包括美妆类蛋白、重组人血清白蛋白、动物疫苗、工业类酶等"}]', 'negotiable', NULL, NULL, '杨贞标', NULL, '13168740559', 'zb.yang1@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:13:02+08', '2025-04-14 17:13:02+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (96, 2, 162, '中国科学院深圳先进技术研究院', '耐腐蚀绝缘材料', 14, '耐腐蚀绝缘材料是在金属导体表面形成具有电气绝缘作用的且有一定机械强度及耐热、耐化学品特性的涂层或薄膜，其广泛用于变压器、线圈、电机、电路板、以及算力服务器等领域。然而，常规绝缘涂层材料存在有机溶剂等环保问题，且组分不优导致成本较高等问题。针对产业的实际需求，研发出具有成本优势的高性能耐腐蚀绝缘材料，无需有机溶剂等复杂化学试剂，相关产品及性能达到标准要求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低成本且无溶剂：无溶剂，降低成本；\n耐腐蚀与高绝缘：耐腐蚀，绝缘性优；\n可涂覆与可成膜：溶液状，形态可调；\n固化好且工艺快；固化快，工艺简单。"}, {"title": "技术成熟度", "content": "已完成模拟环境验证，正在下游应用端验证。"}, {"title": "项目支持", "content": "企业委托"}, {"title": "可应用领域", "content": "能源、电子、电机、AI服务器等"}]', 'negotiable', NULL, NULL, '高明', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 14:58:57+08', '2025-10-29 14:58:57+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (212, 2, 162, '中国科学院深圳先进技术研究院', '光模块用导热凝胶', 14, '随着人工智能、大数据、物联网、云计算等新兴技术的快速发展，光模块作为光通信系统中的核心设备，其重要性日益凸显。光模块不仅广泛应用于电信市场（基站）和数据中心，还在汽车电子、医疗等领域展现出巨大的潜力。随着数据流量的指数增长，组件集成度和功耗越来越高，热设计和热管理成为光模块最为关键的问题。通过有机硅纯化研究、导热粉体改性研究、导热凝胶小试、导热凝胶中试和导热凝胶在光模块验证，满足800G及以上光模块对导热凝胶高导热、优异力学性、和可靠性等需求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "在高温高湿及其它苛刻环境下，固化后不会开裂和滑移；\n高的力学延展性和韧性\n 挥发性物质含量低；\n低粘度（≤300 Pa.s），支持高效率的自动点胶工艺；\n高热导率（12W/m.K） ，有助于光模块的热设计实现。"}, {"title": "技术成熟度", "content": "产品研发阶段完成，已进入企业验证阶段。"}, {"title": "可应用领域", "content": "光通信模块散热\nPCB系统组件的热管理\n数据中心的热管理"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:07:39+08', '2025-04-14 17:07:39+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (219, 2, 162, '中国科学院深圳先进技术研究院', '企业“云脑”：多智能体协作系统', 14, 'MARS系统通过整合多智能体协作机制、大语言模型的智能能力以及机器人平台的操作优势，实现了从材料设计、合成到性能优化的全流程自动化，为加速材料创新提供了突破性的解决方案。依托MARS构建的“企业云脑”致力于打造 “人工智能数据中心”+ “人工智能专家系统”，为企业研发、生产、管理提供AI赋能的综合服务，助力企业加速向数字化、网络化、智能化生产体系转型升级。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "“人工智能数据中心”：构建材料数据库及全链条工艺性能数据库\n“人工智能专家系统”：实现定制化本地部署的大模型系统，为研发生产管理提供全流程智能化支持，加速技术创新和工艺优化。"}, {"title": "技术成熟度", "content": "MARS系统搭建完成，并经实验环境验证可行\n材料大模型已开发，并持续进行优化\n正在开发“云脑”软件的用户界面（UI）"}, {"title": "项目支持", "content": "科技部重点研发计划\n深圳市中小试基地\n先进院自主部署重点项目"}, {"title": "可应用领域", "content": "加速各种新材料的发现和开发，可用于新能源、电子信息、生命健康、航空航天等领域。"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '13971313505', 'xf.yu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 16:54:00+08', '2025-04-14 16:54:00+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (8, 2, 162, '中国科学院深圳先进技术研究院', 'Multi-instrument Synergy Natural Lumen Pulmonary Interventional Robot', 13, 'For natural-orifice diagnostic and therapeutic applications such as minimally invasive biopsy of pulmonary nodules, a three-stage biopsy approach integrating a robot, a variable-stiffness sheath, and a biopsy tool was proposed. A diagnostic and therapeutic robotic system enabling coordinated manipulation of multiple interventional instruments was developed, effectively improving the flexibility, precision, and safety of biopsy tool manipulation within the narrow airway space. By integrating the robotic system with force feedback strategies and surgical large-model technologies, the system enables robot-assisted intelligent surgery in complex operating-room scenarios.', NULL, '02_lab', NULL, NULL, '[{"title": "Technical Innovations", "content": "A high-precision robotic prototype system for diagnosis and treatment of small pulmonary nodules, with axial feeding accuracy better than 1 mm.\nRotational accuracy better than 2°.\nA high-performance pulmonary interventional sheath with adjustable Young’s modulus and a diameter of 2.4 mm.\nCompatible with conventional catheters and other biopsy tools."}, {"title": "Technology Readiness", "content": "The laboratory proof-of-concept prototype components have been validated in animal experimental settings."}, {"title": "Project Support Optional", "content": "Joint Funds of the National Natural Science Foundation of China.\nNational Key R&D Program of China, BT&IT project."}, {"title": "Application Fields", "content": "Robot-assisted precise localization and puncture biopsy of small pulmonary nodules through natural orifices."}]', 'negotiable', NULL, NULL, 'Lei Wang, Ph.D. supervisor', NULL, NULL, 'Wang.lei@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2026-05-18 19:22:39+08', '2026-05-18 19:22:39+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (98, 2, 162, '中国科学院深圳先进技术研究院', '超薄锂基复合负极及其高能量锂金属电池应用', 14, '锂金属是下一代高能量密度锂电池负极侧的终极选择，且其应用形态必为超薄箔材。目前尚无<20 微米超薄锂箔的大面积、高效率制备路径（轧制、电沉积、气相蒸镀等）。发明人原创基于纳米浸润效应的超薄锂制备新途径，成功实现800 nm~100 μm超薄/极薄（数量级低于现有产品）锂基负极的大面积、均匀、高效快捷、低成本（数量级低于现有产品）制备，产品形态、产品成分多种多样、支持定制。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "超薄属性：低至 800 nm；\n厚度/容量大范围可调：800 nm~100 μm（数量级领先）；\n低成本：数量级低于现有辊压产品；\n产品形态多样：双面锂层、连续膜层、间歇式膜层、分条式膜层、点阵式膜层；\n产品成分多样：纯锂、锂合金、且支持定制改性。"}, {"title": "技术成熟度", "content": "经过中小试产线调试与验证，且可快速迭代"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省基础与应用基础研究基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "新能源汽车、智能电子、电动飞机与低空经济、电化学储能等能源应用。"}]', 'negotiable', NULL, NULL, '吴唯', NULL, NULL, 'w.wu1@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 14:51:31+08', '2025-10-29 14:51:31+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (110, 2, 162, '中国科学院深圳先进技术研究院', '基于单细胞机器视觉系统的肿瘤药物的筛选及评估', 3, '开发了一种融合单细胞分析与机器视觉算法的智能化高通量平台，实现对肿瘤细胞在药物干预下的响应行为进行精细化动态监测与多维度量化分析。该系统结合微流控芯片技术、高分辨显微成像和人工智能图像识别模型，针对单细胞水平的形态变化、迁移行为、凋亡特征及细胞异质性，开展肿瘤药物的快速筛选与精准效应评估，助力个体化肿瘤治疗方案的开发和优化。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "自动化评估\n高准确率分析\n单细胞识别分类\n快速药物效果评估"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "开发中"}, {"title": "可应用领域", "content": "临床肿瘤药物敏感性测试"}]', 'negotiable', NULL, NULL, '杨慧', NULL, NULL, 'hui.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 17:54:17+08', '2025-07-16 17:54:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (19, 2, 162, '中国科学院深圳先进技术研究院', '仿生水下机器人的高效推进与智能深度控制系统专利组合', 13, '专利组合包含如下：
水下航行器控制方法
可调幅正弦机构
仿生鱼尾及仿生机器鱼
基于攻角法的仿生机器鱼定深控制方法和装置', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "用于仿生机器鱼、水下航行器的设计及控制。研制设备可用作水下仿生机动平台，搭载专用传感器和光学设备，执行各项水下任务，在海洋探索和开发上具有巨大潜力。"}, {"title": "技术问题", "content": "提供仿生机器鱼的控制和结构设计方案，进一步提高机器鱼的游动速率、灵活性、定深控制及巡游性能。"}, {"title": "技术手段", "content": "采用新型可调幅正弦机构及相关控制方法，简化装置结构，实现全航速的减摇控制，提高抗浪干扰和稳定巡航能力。"}, {"title": "技术功效与成熟度", "content": "基于相关技术已成功开发了身长约为0.5~5.1米的多款机器鱼样机，这些样机均经过湖试或海试，验证了可行性。"}]', 'negotiable', NULL, NULL, '左启阳、何凯', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 1, '2025-12-11 16:39:27+08', '2025-12-11 16:39:27+08', '2026-09-08 16:14:03.872493+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (12, 2, 162, '中国科学院深圳先进技术研究院', '微流控液滴散射光和荧光计数芯片', 13, '专利号：ZL201810438749.2', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "本专利提供一种微流控液滴散射光和荧光计数芯片，通过集成激发光纤、检测光纤及反光镜于芯片内部，实现液滴的散射光与荧光信号高效检测。其应用聚焦于数字PCR技术，解决了传统光学系统体积大、操作复杂的问题。随着全球数字PCR市场迈向百亿美元规模，该芯片凭借小型化、高通量优势，在即时诊断（POCT）与自动化检测场景中具备显著商业化潜力。"}, {"title": "技术功效与成熟度", "content": "本专利技术通过高度集成化的微流控光学设计，实现了显著的技术功效：其一，解决了传统数字PCR检测中因拍照面积限制导致的统计误差问题，提升了检测准确性；其二，将激发光纤、检测光纤及液态金属反光镜集成于芯片内部，有效克服了传统空间光学系统体积庞大、调焦复杂的弊端，实现了设备小型化与操作简便化。"}, {"title": "技术问题", "content": "现有技术中，数字PCR的样品浓度测定准确性受限于拍照面积的限制，且传统空间光学方案的光学空间自身体积庞大、调焦操控复杂，影响样品浓度计算结果的准确性。"}, {"title": "技术手段", "content": "设计了一种微流控液滴散射光和荧光计数芯片，采用集成的激发光纤、检测光纤和反光镜，通过激发光纤照射液滴产生散射光，反光镜反射光信号，检测光纤收集并传送阴性和阳性信号，利用光电倍增管实现信号检测，减小了空间操作体积，简化了制作过程，避免了传统方案的光学空间自身体积和调焦复杂性。"}]', 'negotiable', NULL, NULL, '冯鸿涛', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-25 11:25:43+08', '2025-12-25 11:25:43+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (101, 2, 162, '中国科学院深圳先进技术研究院', '虚拟电厂边缘智能采控终端', 14, '虚拟电厂边缘采控终端是一种集数据采集、边缘计算与智能控制于一体的关键基础设备，是“能源互联的神经末梢”。冯威团队通过软硬件协同设计与边缘智能算法深度融合，突破了传统终端在通信时效、控制精度与多源数据处理上的性能瓶颈，实现了对分布式能源、负荷和储能等资源的高效接入与分布式聚合控制，支撑大规模虚拟电厂场景下的实时调度与灵活互动，显著提升新能源消纳能力与电力系统韧性，为构建新型电力系统注入“感知—计算—控制”一体化智能底座。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "融合边缘智能算法余可靠工业通信架构，实现本地分布式自治与云边一体化协同管控。"}, {"title": "可应用领域", "content": "建筑能源领域\n综合能源领域\n低空能源领域\n虚拟电厂领域"}, {"title": "项目支持", "content": "国家重点研发计划\n深圳市重点研发计划\n国家电网、华润燃气、深圳能源企业项目等"}]', 'negotiable', NULL, NULL, '冯威', NULL, '13564648453', 'w.feng@siat.ac.cn_x000b_个人网站', NULL, 'published', NULL, 1, 0, '2025-09-10 11:40:18+08', '2025-09-10 11:40:18+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (171, 2, 162, '中国科学院深圳先进技术研究院', '结构色美瞳及其健康监测应用', 13, '面向与日俱增的健康监测需求，研发了无化学色素或染料添加、对湿度和压力信号敏感的结构色美瞳，可通过肉眼可见颜色变化，实时监测干眼症和高眼压症高风险人群的生理指标；还可负载药物，实现眼科保健和眼科相关疾病的治疗，为相关眼科疾病早发现早治疗提供全新工具。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "安全无毒、色彩丰富、易于佩戴：无化学色素或染料添加，与眼球组织模量接近；\n眼压、泪液可视化监测：用于青光眼、干眼症防控。"}, {"title": "技术成熟度", "content": "实验原型样品在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n国家重点研发计划\n广东省项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "美妆、智能穿戴、健康监测等应用领域。"}]', 'negotiable', NULL, NULL, '杜学敏', NULL, NULL, 'xm.du@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:00:47+08', '2025-04-15 11:00:47+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (60, 2, 162, '中国科学院深圳先进技术研究院', 'MiND-DMF多重细菌快速核酸检测平台', 3, 'iND-DMF是一款面向感染性疾病快速诊断的创新型数字微流控核酸检测平台。该系统将核酸提取、恒温扩增（RPA）与CRISPR/Cas12a分子识别技术集成于单一芯片，实现了从样本到结果的全自动化检测流程，仅需55分钟即可完成6种常见致病菌的同步识别。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高集成度：单芯片集成提取、扩增、检测三步流程（120×63×1.2 mm）；\n高灵敏度：检测限低至 100 CFU/mL，六菌种同时检测，准确率 ≥98%；\n快速检测：全流程仅需 55 分钟，恒温 37°C 无需循环"}, {"title": "技术成熟度", "content": "实验室原理样机。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "体外诊断"}]', 'negotiable', NULL, NULL, '沈杰男', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-11-05 15:47:54+08', '2025-11-05 15:47:54+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (179, 2, 162, '中国科学院深圳先进技术研究院', '基于多源信息融合的能量代谢评估', 9, '首次用可穿戴单导联心电图、运动信号及人体基础信息，建立基于深度神经网络的能量代谢精准计算模型；提出了一种多分支多尺度特征提取网络和两阶段回归的能量代谢预测方法，提升了模型的准确性，平均误差小于10%，并且对从静息到力竭再到静息的全过程都有比较好的跟踪效果。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "平均绝对误差（MAE）：0.7Kcal/min；\n相对误差：小于10%\n实时监测：每分钟计算一次；\n从静息到力竭再到静息全过程跟踪效果较好。"}, {"title": "技术成熟度", "content": "已完成在实验室采集数据集上的实验验证"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省粤莞联合基金重点项目"}, {"title": "可应用领域", "content": "运动监测\n运动康复\n工作负荷评估\n代谢性疾病管理"}]', 'negotiable', NULL, NULL, '孙方敏', NULL, NULL, 'fm.sun@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:37:35+08', '2025-04-15 10:37:35+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (39, 2, 162, '中国科学院深圳先进技术研究院', '溶藻弧菌噬菌体及包含该噬菌体的杀菌组合物', 16, '专利号：ZL201710953777.3', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 25%，细分场景需求持续释放。"}, {"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "弧菌引起的水产养殖疾病由于抗生素滥用导致耐药性问题，单一噬菌体疗法存在宿主菌易产生抗性的缺陷，难以有效控制弧菌病原菌。"}, {"title": "技术手段", "content": "开发一种溶藻弧菌噬菌体ValSw3-2及其组合物，通过混合噬菌体鸡尾酒疗法扩大宿主谱范围，降低抗性产生，结合副溶血弧菌噬菌体VpaSw-1、VpaSw-2等，形成协同作用的杀菌组合物。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:22:49+08', '2025-12-09 18:22:49+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (148, 2, 162, '中国科学院深圳先进技术研究院', '高性能、低成本质子交换膜电解槽阳极催化剂的研发', 14, '针对可再生能源驱动的电解水制氢对低能耗、宽功率波动的需求，深度开发低成本质子交换膜(PEM) 电解槽阳极催化剂层的技术创新，提供了在酸性环境中具有长期稳定性的高效催化剂。通过构建具有动态电子转移的自适应活性位点、晶格水辅助的改性氧交换机制、贵金属-非贵金属界面电子调控、阴离子配位调制等策略，成功解决了阳极催化剂活性和稳定性之间的平衡问题，实现了PEM水电解性能的大幅提升。器件测试性能已达到中国氢能专项的项目指标要求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高活性：研发的催化剂在三电极测试中过电势较低(186 mV@10 mA cm-2)，远超商业IrO2；\n高稳定性：稳定性达到创纪录的1.9 × 107 noxygen nIr-1；\n作用机制清晰：多种高端表征技术明确OER反应机制；\n工业实用性：在0.3 mgIr cm-2低Ir负载量下，PEM电解槽在2.0 A cm-2电流密度下实现1.76 V的电池电压(达到中国氢能专项的项目指标要求2.0 A cm-2, 1.8 V)。"}, {"title": "技术成熟度", "content": "低于1.86 V时PEM电解槽获得3.0 A cm-2的电流密度，接近美国能源部2030年关于PEM电解槽的指标要求。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "与风能、太阳能等可再生发电技术结合来实现“绿氢”制备。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:16:02+08', '2025-04-15 14:16:02+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (185, 2, 162, '中国科学院深圳先进技术研究院', '数字化、自动化非人灵长类动物认知行为检测技术', 3, '围绕非人灵长类神经精神疾病的行为学检测技术，结合视频分析、机器学习及光电传感技术，从优化实验检测及数据精准捕捉方面入手，实现了多款适用于大型非人灵长类动物猕猴行为检测技术的应用开发。新型数字化、自动化行为学检测技术响应灵敏度高、客观性强、并且增加了数据维度，可用于猕猴的工作记忆、视空间认知记忆、成瘾、抑郁等行为的测量。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "利用光电传感技术，自动测量动物执行认知功能的过程，数据更准确、客观；可以收集更多的精确数据，尤其是手动的技术不可能检测到的参数，增加了数据维度；配套自动化数据分析和处理软件，一键出图，方便后期数据深度挖掘分析。"}, {"title": "技术成熟度", "content": "目前已经以技术服务的形式在海南大学、广州实验室等实现销售。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省基础与应用基础研究项目\n深圳市药物成瘾重点实验室项目\n深港脑科学创新研究院项目"}, {"title": "可应用领域", "content": "各种神经、精神疾病猕猴动物模型的认知功能检测。"}]', 'negotiable', NULL, NULL, '孟志强', NULL, '18824235390', 'zq.meng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:26:51+08', '2025-04-15 10:26:51+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (106, 2, 162, '中国科学院深圳先进技术研究院', '基于微纳米加工技术的生化检测平台开发', 3, '面向生化检测领域的临床需求与技术瓶颈，依托微纳制造领域的跨学科优势，在微流控光学芯片、超构表面传感以及生物检测系统开发等方向取得了一系列创新成果，主要包括以下三方面突破：首创基于分光波导调控的光遗传器件集成方案，通过光场重构技术实现神经调控芯片的微型化及多位点重构；研制多功能集成液滴微流控系统，集成荧光检测、液滴分选等模块，结合分子探针技术实现肿瘤miRNA高特异性检测；开发梯度纳米加工新工艺，成功构建可视化超构表面传感器，突破常规LSPR检测技术手段对光谱仪的依赖。', NULL, '02_lab', NULL, NULL, NULL, 'negotiable', NULL, NULL, '冯鸿涛', NULL, '13676736396', 'ht.feng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 18:03:44+08', '2025-07-16 18:03:44+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (13, 2, 162, '中国科学院深圳先进技术研究院', 'AI赋能智慧城市与社会治理', 9, '该组合包含如下专利：
城市地铁站域的认知场所特征识别方法及系统          地铁站服务范围确定方法及系统
一种轨迹生成方法、装置、设备及存储介质               一种时空轨迹生成方法、装置、计算机设备及存储介质
城市内部登革热时空预测方法、系统及电子设备      城市内部传染病时空扩散建模方法及系统
区域POI配置可视化方法及系统                                      初始暴发位置致传染病时空传播风险定量评估方法及系统', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "可面向政府与智慧城市相关企业，1）赋能智慧城市相关软件平台，提供关键技术；2）赋能公共安全与公共卫生智慧防控体系建设；3）赋能地铁规划与交通协同优化；4）赋能城市规划智能化升级。2024年城市治理行业市场规模已达1.87万亿元。"}, {"title": "技术问题", "content": "如何精准构建城市时空仿真推演模型？如何自动识别地铁站服务范围？如何自动识别城市功能区类型？"}, {"title": "技术手段", "content": "涉及多模态数据融合技术、人工智能与大模型技术、系统动力学模型、机理-数据双驱动技术等。"}, {"title": "技术功效与成熟度", "content": "可实现城市级居民时空动态仿真推演、疫情时空传播仿真推演、地铁站服务范围自动识别、城市功能区类型自动识别等。技术成熟度高，可直接应用。"}]', 'negotiable', NULL, NULL, '刘康博士团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 1, '2025-12-23 14:38:12+08', '2025-12-23 14:38:12+08', '2026-09-09 17:19:07.566206+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (45, 2, 162, '中国科学院深圳先进技术研究院', '杀鲑气单胞菌噬菌体、包含其的杀菌组合物及其应用', 16, '专利号：ZL201710250600.7', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "现有技术在控制大西洋杀鲑气单胞菌引起的疖疮病及溃肠病时，抗生素滥用导致耐药性问题，单一噬菌体疗法的应用存在宿主谱范围窄、剂量高和抗性快速发展的缺点。"}, {"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 25%，细分场景需求持续释放。"}, {"title": "技术手段", "content": "开发了一种广谱耐药大西洋杀鲑气单胞菌噬菌体鸡尾酒，通过混合多株噬菌体构建，增强了对多种致病菌的裂解能力，包括沙门氏杆菌、弧菌及大肠杆菌，且安全、有效，生产成本低。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:08:46+08', '2025-12-09 18:08:46+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (120, 2, 162, '中国科学院深圳先进技术研究院', '一种多用途手持跟踪靶标：坐标与轮廓测量的实验验证', 9, '本研究通过开发基于红外标志点的手持式通用跟踪靶标系统，并解决传统光学跟踪靶标存在的角度受限、环境抗干扰能力弱、测量对象单一等问题，实现了关键点位的高精度接触式测量以及型面轮廓的高密度非接触式点云扫描，为复杂工业场景提供了高性价比的一体化测量方案。本研究为基于红外标志点的手持靶标多角度鲁棒跟踪技术的模块化应用提供了实验支持，并为该技术与其他终端设备的融合设计提供了可借鉴的框架，有助于推动工业检测与智能制造等领域的发展。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "1. 多角度鲁棒跟踪：通过红外标志点系统解决传统光学靶标角度限制，实现更广泛精确的跟踪能力。\n2. 集成测量与扫描：结合高精度接触式测量与非接触式点云扫描，扩展复杂形状检测应用场景。\n3. 模块化与设备融合：提出模块化靶标设计，支持与多种终端设备高效融合，推动跨行业应用。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "可应用领域", "content": "精密测量、工业检测。零件检测：用于检测机械零件的尺寸、公差和形状精度，特别是在航空、汽车等行业。在汽车制造过程中，用于扫描零部件或车身，进行尺寸检查、逆向设计等。"}, {"title": "项目支持", "content": "国家自然科学基金\n人工智能与数字经济广东省实验室（深圳）开放合作研究课题"}]', 'negotiable', NULL, NULL, '谷飞飞', NULL, '17603055357', 'ff.gu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 04:02:10+08', '2025-06-18 04:02:10+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (23, 2, 162, '中国科学院深圳先进技术研究院', '一种抗体偶联的细胞及其制备方法与应用、靶向给药系统', 13, '专利号： ZL202411354633.2', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "Ac-MSC制备工艺简单，无需改变细胞基因，安全性高且风险可控，可迅速推进IIT临床试验。该技术尤其适用于银屑病、类风湿性关节炎及炎性肠病，为难治性疾病提供高效、经济且安全的新型干细胞治疗方案。"}, {"title": "应用场景及市场规模", "content": "抗体偶联间充质干细胞（Ac-MSC）可以实现间充质干细胞在炎症部位聚集，单独使用可以提高银屑病、类风湿性关节炎等自身免疫性疾病的治疗效果，也可以作为药物或基因治疗载体，进行靶向递送。"}, {"title": "技术问题", "content": "现有抗体药物偶联物（ADC）存在连接子设计难度大、生产工艺复杂且成本高的问题，且现有利用细胞偶联抗体方法需要巯基化修饰细胞，影响药物载体功能。"}, {"title": "技术手段", "content": "采用点击化学方法在细胞表面引入叠氮化物基团，并与含炔基化合物-PEGn-NHS反应，通过生物正交偶联的方式将抗体偶联到细胞上，制备抗体偶联的细胞，作为药物载体，简化生产工艺并避免巯基化修饰。"}]', 'negotiable', NULL, NULL, '王言团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 19:29:04+08', '2025-12-09 19:29:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (28, 2, 162, '中国科学院深圳先进技术研究院', '一种流体的驱动装置及其制备方法', 13, '专利号：ZL201911287062.4', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本专利提供了一种无泵、低能耗、高精度的流体驱动解决方案。其核心功效在于利用特殊的表面微结构处理，实现了对极微量流体的自发、定向输运，克服了传统机械泵体积大、能耗高、控制复杂等痛点。\n技术成熟度已达到TRL 6级（系统/分系统原型在相关环境中验证），已完成实验室原理样机验证，性能稳定可靠，具备进行中试和产业化开发的条件。"}, {"title": "应用场景及市场规模", "content": "本专利技术主要应用于生物医疗检测（如芯片实验室、即时诊断设备）、精密化工输送、以及软体机器人驱动等领域。随着精准医疗和自动化产业的发展，\n全球微流控市场规模预计在2025年超过200亿美元，年复合增长率保持高位。本技术作为其中的核心驱动部件，市场需求明确且增长潜力巨大，有望在高端医疗器械和智能装备领域开辟新的市场增长点。"}, {"title": "技术问题", "content": "现有微流控芯片在流体驱动和控制方面存在集成化和复杂操作功能的难题，尤其是在样品处理与检测时无法实现多种流体操作与控制流程的集成。"}, {"title": "技术手段", "content": "设计了一种多功能流体驱动装置，包括N层相互连接的流体通道，包含流体进样模块、功能模块、混合单元、量取单元和动力单元，通过微阀结构和微柱组件实现流体的精确控制和自驱动，适用于缓冲液、血浆、血清等流体的混合和量取。"}]', 'negotiable', NULL, NULL, '杨慧团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:56:43+08', '2025-12-09 18:56:43+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (31, 2, 162, '中国科学院深圳先进技术研究院', '一种融合光学显微成像与大样本组织切片的自动化断层扫描成像系统', 15, '专利号：ZL202311448159.5', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "该专利融合光学显微成像与自动化组织切片技术，实现高清三维图像快速获取，显著提高成像效率与吞吐量。其技术功效主要体现在高分辨率、多色荧光成像及快速扫描应用中，可应用于病理诊断和生物医学研究。技术成熟度较高，基于现有光学显微与智能化机械设备进行优化整合，具备可量产性和市场推广潜力，为数字病理学及显微成像领域提供创新解决方案。"}, {"title": "技术问题", "content": "现有技术在对大尺寸生物组织进行成像时，容易引入畸变且需要大量人工手动操作，导致时间和人力成本高，且难以实现高效的三维拼接。"}, {"title": "技术手段", "content": "设计了一种融合光学显微成像与大样本组织切片的自动化断层扫描成像系统，采用双激发光路和远程聚焦技术，通过自动切片系统和精确位移台实现快速切片和成像，结合双轴检流计扫描镜进行扫描成像。"}, {"title": "应用场景及市场规模", "content": "该专利应用于生物医学领域，特别是大样本组织切片成像和三维重建，可在较短时间内获取离体器官或生物组织的海量三维图像信息。其快速成像、多色组织分辨能力提高了临床诊断效率和研究精度。随着数字病理学和显微成像市场需求增长，此技术在全球疾病诊断设备市场规模有望大幅扩展，尤其在医疗、科研和教育领域潜力巨大，预计市场容量逐年增加，可达百亿美元级别。"}]', 'negotiable', NULL, NULL, '李宝强', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:53:04+08', '2025-12-09 18:53:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (33, 2, 162, '中国科学院深圳先进技术研究院', '一种低光损伤双光子显微成像系统', 15, '专利号：ZL202110746188.4', NULL, '02_lab', NULL, NULL, '[{"title": "技术手段", "content": "设计了一种低光损伤双光子显微成像系统，通过飞秒脉冲激光器、光电调制器、扫描模块和显微镜物镜等组件，实现逐点慢速扫描和视频级快速成像，并通过移动反射镜切换和光电调制器的实时控制，减少无效激光照射，门控激发特定像素点。"}, {"title": "技术功效与成熟度", "content": "该专利技术运用先进的多光子显微成像技术，能够实现高分辨率、深层次的生物组织微循环观测，并支持实时动态追踪，为脑科学和心血管疾病的研究提供重要数据支撑。技术功效显著，能有效提升疾病早期诊断的精准度与效率。目前，该技术已完成实验室验证，具有良好的稳定性和可靠性，成熟度高，并具备向产业化转化的条件，适用于科研机构和医疗检测领域，具备广阔的应用前景。"}, {"title": "技术问题", "content": "双光子荧光显微成像在长时程激光照射下对生物组织造成热效应，导致温度升高、脑水肿、蛋白质凝固变性、炎症反应和细胞死亡，影响实验结果，同时降低激光功率会降低成像质量。"}, {"title": "应用场景及市场规模", "content": "该专利主要应用于医疗领域的脑科学研究、神经疾病诊断，以及心血管疾病的早期检测与治疗。通过光学成像技术对生物活体中的快速神经活动变化进行精准解析，可实现脑功能和病理的实时观测，提升医疗诊断准确性和效率。市场规模巨大，尤其随着脑科学和精准医疗的需求增加，全球相关市场预计将在未来几年突破千亿美元。该技术在科研机构、生物医药企业及临床医院具备广泛应用潜力，推动医疗器械与光学技术的进一步融合与发展。"}]', 'negotiable', NULL, NULL, '李宝强', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:51:03+08', '2025-12-09 18:51:03+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (213, 2, 162, '中国科学院深圳先进技术研究院', 'FCBGA封装用AD胶研发及产业化', 14, 'AD胶是一种用于倒装芯片球形栅格阵列封装的先进封装材料，主要用于固定和连接芯片与基板之间的位置，同时提高热传导，降低封装器件的过热问题。AD胶使用过程中无需底漆，能与多种常见基材，如金属、陶瓷、环氧压层板，形成良好的粘接。', NULL, '02_lab', NULL, NULL, '[{"title": "产品特点", "content": "单组分：使用前无需额外混合操作；\n流动性好：填充后能够自动流平；\n高粘接强度：有效提供异质界面粘接力，高至7.5MPa；\n导热：能够有效将热量导出；\n多功能热固化。"}, {"title": "技术成熟度", "content": "能够实现芯片封装中的异质界面的连接与固定。"}, {"title": "项目支持", "content": "深圳先进电子材料国际创新研究院自主部署项目"}, {"title": "可应用领域", "content": "芯片、器件封装用粘接与导热领域。"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:05:40+08', '2025-04-14 17:05:40+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (48, 2, 162, '中国科学院深圳先进技术研究院', '自动化试剂补液装置及全自动移液工作站', 16, '专利号：ZL202223096421.8', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有的全自动移液工作站在长时间、高通量的自动化生物实验中无法提供实时补液设备，导致生物试剂容易污染或变质，无法满足长时间的高精度液体处理需求。"}, {"title": "技术功效与成熟度", "content": "\"技术功效：通过重力称量机构实现试剂重量实时监测，结合泵装置自动补液，解决生物试剂暴露污染问题。溢流保护设计确保操作安全，提升实验自动化水平。\n技术成熟度：具备完整机械架构与控制逻辑，具备详细组件连接步骤，具备产业化条件。\""}, {"title": "\"应用场景及市场规模", "content": "应用场景：专为全自动移液工作站设计，用于生物实验高通量液体处理。通过重力称量实时监测液位，实现试剂自动补给，避免试剂污染，满足科研及医疗实验室的自动化、无菌操作需求。\n市场价值：面向生物制药、科研机构等高需求领域，随着精准医疗发展，自动化液体处理设备市场前景广阔。\""}, {"title": "技术手段", "content": "设计了一种自动化试剂补液装置，采用重力称量机构实时检测容器中溶液的剩余量，通过控制泵装置的启停实现溶液的不间断供应，并通过接水件和容器的非接触设计保证重量称量的准确性，具备溢流保护功能以避免溶液污染和设备损坏。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:04:25+08', '2025-12-09 18:04:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (84, 2, 162, '中国科学院深圳先进技术研究院', '云鸢·低空大模型', 9, '针对低空智能计算面临的多源数据融合、任务规划决策和跨域资源调度等难题，设计并研发云鸢·低空大模型系统，构建“感知层、算法层、系统层、应用层”四层架构，突破多源异构数据感知融合、多智能体自主决策、大模型轻量化与云边端推理优化等关键技术，并在典型低空无人场景开展验证及应用，推动低空智能计算技术的实现与落地，服务国家及粤港澳大湾区低空新经济产业的发展。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "空间感知：提出面向低空场景的多源异构时空数据精准感知及高效融合技术；\n算法模型：提出基于世界模型的无人机多智能体自主决策及高效协同方法；\n系统加速：提出基于云边端三级架构的跨域资源协同部署及推理加速方法。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家重点研发计划“战略性科技创新合作”重点专项项目“基于人工智能大模型的低空智能计算理论与方法研究”"}, {"title": "可应用领域", "content": "低空巡检、低空物流、低空旅游、低空农业、低空消防、低空执法等多种低空应用场景"}]', 'negotiable', NULL, NULL, '叶可江', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 16:14:40+08', '2025-10-29 16:14:40+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (189, 2, 162, '中国科学院深圳先进技术研究院', '骨创伤手术机器人应用', 9, '针对骨科、骨创伤手术机器人智能引导和操作力量不足的问题，构建了基于增力机构的串并混联骨折复位机器人设计方案，提出了术中基于二维X光影像的三维立体定位技术，实现复杂骨折骨块的精准定位技术；提出了具有过渡区域特性的手术状态精细感知策略，以及基于多源信息融合的手术状态识别方法，实现基于多模态信息的手术操作状态精细感知，提升骨创伤手术机器人的临床可用性，以及操作的安全性。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "增力机构自由度：6个\n增力系数：≥4@100×100×100mm3\n系统重复定位误差：0.04mm和0.02°\n系统平均定位误差：0.44mm和0.35°"}, {"title": "技术成熟度", "content": "实验室原理样机组件在动物实验环境中验证，导航系统在临床实验中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "手术机器人、手术导航、手术规划"}]', 'negotiable', NULL, NULL, '胡颖', NULL, NULL, 'ying.hu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:10:54+08', '2025-04-15 10:10:54+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (201, 2, 162, '中国科学院深圳先进技术研究院', '机器人视触觉感知与学习技术', 9, '面向机器人自主作业和智能制造等需求，结合多模态大模型的优势，开发了受人体机械刺激感受器的光学触觉传感器，提出了基于对比学习的机器人稳定抓取策略，构建了基于标签学习的机器人触觉感知方法，部分技术成功应用于协作机器人人机交互、工业机器人精细装配、医疗机器人智能触诊等场景。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "能同时实现对静态和动态多种类别的机械刺激的感知；\n三维力测量范围可达50N；\n测量精度≤5%FS。"}, {"title": "技术成熟度", "content": "6级\n形成原型样机并并证明可行"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发项目\n广东省粤深联合基金重点项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "协作机器人人机交互、工业机器人精细装配、医疗机器人智能触诊。"}]', 'negotiable', NULL, NULL, '易正琨', NULL, NULL, 'zk.yi@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:38:36+08', '2025-04-14 17:38:36+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (196, 2, 162, '中国科学院深圳先进技术研究院', '地铁车辆底部智能巡检机器人', 9, '智能巡检机器人不仅可以对地铁车辆底部进行全范围的巡检覆盖，还能对地铁车辆底部的灰尘进行清理,减少因灰尘而产生的漏检;采用多种传感器融合感知，安全高效的进行自动化巡检;基于2D和3D相机的实时图像采集，结合深度学习算法实现车底全景图扫描及螺栓松动、裂纹、异物、转向架等关键零部件的检测，提高地铁车辆底部的检修准确率和效率。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高检测精度: 针对小目标检测，具有较高的检测精度；高鲁棒性定位：适应长地沟单一环境和相似环境等复杂环境下精准定位；\n双臂智能协同控制：通过手眼系统在线自标定，基于局部三维重建的机械臂自主路径规划达到视觉检测与灰尘清理的自主协同。"}, {"title": "技术成熟度", "content": "样机已在在实验环境和现场环境（北京地铁和深圳地铁）中开展验证。"}, {"title": "项目支持", "content": "深圳市科技创新委员会\n香港生产力促进局\n深圳地铁\n北京地铁\n香港地铁"}, {"title": "可应用领域", "content": "地铁、高铁等底部巡检"}]', 'negotiable', NULL, NULL, '何凯', NULL, '15013869572', 'kai.he@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:49:40+08', '2025-04-14 17:49:40+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (52, 2, 162, '中国科学院深圳先进技术研究院', '一种显微制样装置及其使用方法', 16, '专利号：ZL202111488947.8', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "技术功效：通过集成LED灯板、匀光及滤光组件，实现自动化压片，提升制样效率、一致性及光照控制精度，满足光遗传学等高通量实验需求。\n技术成熟度：作为授权发明专利（CN114279782B），具备完整机械设计及附图验证，通过实用性审查，已具备产业化条件。"}, {"title": "技术问题", "content": "本发明提供一种显微制样装置及其使用方法，解决了生物细胞实验压片过程操作不便，实验样品制作时间漫长，效率过低的问题"}, {"title": "应用场景及市场规模", "content": "应用场景:本装置专为微生物实验设计，实现高效、一致的压片处理，适用于光遗传学等需精确光照控制的场景，满足科研实验室中通量需求，显著提升制样效率。\n市场价值:随生命科学自动化发展，设备在实验标准化方面具备增长潜力，契合高通量解决方案需求，在生命科学仪器细分市场中具有商业化前景。"}, {"title": "技术手段", "content": "提出了一种适用于显微镜载物台的制片装置，针对特定的显微镜固定装置，做出相互配合的尺寸。从而从单次只能观察一个试验样品的传统装置，到现在一次性可以进行7份试验样品的观察。能够完成数量不多的样品的同时快速的制样和观察。本发明能够简化制样过程，使得初学者能够很迅速的完成制样流程，且制样效果很好。多孔的设计，满足实际实验中对中通量样品的实验需求。平凸镜使得LED光源更加均匀，滤光片用来选取所需波段的光线。利用软件可以对LED灯板灯珠的光照颜色和强度进行控制，多孔之间相互独立，满足不同需求的光遗传学实验。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:56:52+08', '2025-12-09 17:56:52+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (137, 2, 162, '中国科学院深圳先进技术研究院', '晓星智能学伴: 基于教育和心理大模型的AI学习伙伴', 9, '晓星智能学伴是由中国科学院深圳先进院和深圳联合信息联合研发的人工智能教育产品，旨在满足教育行业用户需求。它具备智能预习、复习、听读、听写、AI语音问答和心理辅导等功能，通过精准教学改善发音问题。此外，晓星智能学伴还提供技术支持和解决方案，助力教育机构智能化升级，推动数字化校园建设。它特别关注家庭教育场景，解决家长辅导难题，并通过启发式学习模式和情感化陪伴，为学生提供全方位的学习支持，营造轻松的学习氛围。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "实现教育和心理双域大模型协同驱动的智能对话系统。"}, {"title": "项目支持", "content": "中国科学院深圳先进院-深圳联合信息-教育人工智能联合实验室"}, {"title": "可应用领域", "content": "教育领域\n心理健康领域"}, {"title": "产业合作", "content": "2023年与深圳联合信息成立联合实验室\n电话：0755-86665684  \n邮箱：support04@szunion-info.com"}]', 'negotiable', NULL, NULL, '倪仕文', NULL, '15827639393', 'sw.ni@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:48:26+08', '2025-04-15 10:48:26+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (157, 2, 162, '中国科学院深圳先进技术研究院', '如何用质谱仪器研究肿瘤代谢异质性机制？', 13, '用于肿瘤代谢异质性机制研究的在体质谱仪器创新性地提出基于原位质谱的代谢组学化学识别方法，研究活体脑肿瘤代谢异质性的分布特征，研制复合电离源质谱、活体采样系统、细胞处理系统和多微通道分离系统等关键部件，实现活体动物肿瘤代谢异质性的“时间、结构和空间”质谱可视化分析，构建一套活体、实时和高通量的质谱系统。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "创新的技术：超声提取、吸引和传输一体集成化\n独到的设计: 微通道传输、分离和导入系统的有机整合\n创新的数据处理方式: 成像质谱数据的智能化分析和多维数据融合"}, {"title": "技术成熟度", "content": "实验室原理样机研制阶段。"}, {"title": "项目支持", "content": "国家自然科学基金-重大仪器研制项目"}, {"title": "可应用领域", "content": "活体肿瘤检测、精准医学的早期干预策略、肿瘤防治等医学应用。"}]', 'negotiable', NULL, NULL, '罗茜', NULL, NULL, 'qian.luo@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:42:58+08', '2025-04-15 13:42:58+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (53, 2, 162, '中国科学院深圳先进技术研究院', '一种显微镜同步控制系统及方法', 16, '专利号：ZL202111227372.4', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "传统显微镜成像控制系统在高速成像时存在图像采集延迟和时间控制不精确的问题，无法满足高精度高速图像采集的需求，尤其是在生物学研究中对荧光成像的同步性和精准性要求较高。"}, {"title": "技术功效与成熟度", "content": "\"技术功效：本专利通过微秒级时序同步攻克传统软件控制的毫秒级延迟问题，支持30Hz以上高速采集，显著减少荧光成像中的光毒性与光漂白。\n技术成熟度：技术方案完备，具备具体硬件架构和实测数据支持，已具备工业化落地条件\""}, {"title": "应用场景及市场规模", "content": "应用场景：聚焦生物医学研究领域的高速、高精度显微镜成像，具体应用于细菌游动观测（需30Hz以上采集速度）、荧光成像等场景。\n市场规模潜力：面向科研机构、高通量药物筛选平台等高端需求，填补高精度时序控制市场空白，在生命科学仪器细分领域具备商业化潜力。"}, {"title": "技术手段", "content": "采用显微镜同步控制系统，通过显微镜高速同步控制装置与上位机、相机、激光器、LED光源及空间光调制器的同步运行，利用数字信号输出实现相机、光源及其他设备的高精度时序控制，结合电动位移台和压电陶瓷Z台的精准移动，实现图像采集的低延迟和高同步性。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:55:35+08', '2025-12-09 17:55:35+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (29, 2, 162, '中国科学院深圳先进技术研究院', '一种双层微孔芯片及其制备方法', 13, '专利号：ZL202011438141.3', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本专利技术通过创新的双孔结构设计，实现了对单细胞的高效、温和捕获与长期稳定培养，捕获率 > 90%，存活率 > 95%。其核心功效在于解决了传统方法通量低、细胞损伤大、难以进行下游分析等技术瓶颈。"}, {"title": "技术问题", "content": "现有单细胞筛选技术中，微孔设计尺寸过大导致筛选效率降低，且单一微孔系统难以精确控制流量，导致目标细胞丢失和筛选效率下降。"}, {"title": "技术手段", "content": "采用双层微孔芯片设计，其中第一层微孔结构层和第二层微孔结构层的孔径由小到大，且第二层微孔仅可容纳一个样本，通过软光刻复制技术制备，减少层间压力差，防止堵塞，并提高捕获效率。"}, {"title": "应用场景及市场规模", "content": "本专利产品主要应用于高通量单细胞培养与分析、抗体筛选、细胞克隆筛选以及预临床药物评估等领域。这些领域是精准医疗和生物制药研发的核心环节。市场对高效、低成本、自动化的单细胞操控工具需求迫切，本产品市场前景极为广阔。"}]', 'negotiable', NULL, NULL, '杨慧', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:55:50+08', '2025-12-09 18:55:50+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (131, 2, 162, '中国科学院深圳先进技术研究院', '先进光纤传感技术及其海洋监测应用', 9, '围绕海洋复杂应用环境和实时监测需求，结合光纤传感技术优势，从光纤传感器海洋应用的适用性和性能提升方面入手，实现海洋原位多参数（地震、地磁、形变、压力、水听等）光纤传感器及其海洋传感舱应用开发。自主研制的国际最优性能光纤超宽频带海底地震仪，满足我国海洋地震监测需求；海洋超低频光纤水声-地声监测仪器，可实现大型潜航器远距离监听；多种高性能海洋光纤传感器，将成为我国海洋地震台网和海底观测网的物理层支撑。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "超低频：地震至360s，水声至0.1Hz；\n低噪声：国际单位的10-9-10-10量级；\n环境适用性：共模噪声抑制能力强；\n湿端无需供电：全光纤传感探头；\n易分布易组网：与特殊结构匹配的复用技术，适用于大规模全方位监测。"}, {"title": "技术成熟度", "content": "实验样机或工程样机且已在海洋中得到应用验证。"}, {"title": "项目支持", "content": "国家重点研发专项\n中国科学院C先导专项\n中国科学院重点部署科研专项\n广东省重点基金项目\n深圳市基础研究重点项目"}, {"title": "可应用领域", "content": "智慧海洋、智慧城市、地铁隧道、特种设备与特殊结构健康监测、油气安全开采等应用领域。"}]', 'negotiable', NULL, NULL, '崔洪亮', NULL, NULL, 'hl.cui@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:09:48+08', '2025-04-15 14:09:48+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (51, 2, 162, '中国科学院深圳先进技术研究院', '安全夹爪和工业机器人', 16, '专利号：ZL202123155829.3', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "\"技术功效：本专利通过弹性缓冲结构实现夹爪与夹块的相对位移缓冲，解决工业机器人夹持高度误差问题，避免设备损坏。具备自适应调节功能，确保夹持稳定性。\n技术成熟度：技术已实用化：作为PCT国际申请，具备完整机械设计并通过附图验证，具备工业化实施条件。\""}, {"title": "技术问题", "content": "工业机器人的刚性夹持机构在控制系统或环境影响下可能导致夹持机构或对象的损伤，尤其是在夹持误差时产生过大作用力。"}, {"title": "技术手段", "content": "设计了一种安全夹爪，采用夹爪、夹块、第一弹性件和第一轴的组合结构，夹爪沿第一轴轴向与夹块相对位移时，第一弹性件发生弹性伸缩，提供竖直运动方向的缓冲功能，夹块可绕第一轴转动以自适应夹持误差，并通过弹性定位件和防滑垫片提高夹持稳定性。"}, {"title": "应用场景及市场规模", "content": "核心应用：专为生物实验自动化平台设计，解决微孔板等精密器材夹持中的碰撞风险。通过弹性缓冲结构与自适应调节机制，确保夹持过程安全可靠。\n市场价值：面向工业机器人安全末端执行器细分领域，契合高端实验设备与精密制造业对损伤零容忍的需求，在自动化生物实验场景中具有明确应用潜力。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:57:52+08', '2025-12-09 17:57:52+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (139, 2, 162, '中国科学院深圳先进技术研究院', '模拟失重仪及其配套可穿戴体征监测设备', 3, '项目组在肌骨系统发育与疾病研究中，原创开发了用于模拟失重的研究装置，并已制成若干套用于科学研究。鉴于上世纪70年代NASA开发的模拟失重系统在使用中存在的应激、炎症及肢体伤害方面的问题，机体的应激及慢性炎症等严重影响实验研究的可重复性和可靠性，亟待现代化设施填补空白。同时，为服务于模拟失重条件下的相关药物研发、地外移民等研究场景，课题组开发了用于监测动物生命体征的智能检测服及数据监测系统。项目原创性高，知识产权明确。', NULL, '02_lab', NULL, NULL, '[{"title": "项目支持", "content": "中国科技部专项：（SQ2021YFA079421）变革性技术关键科学问题。空间胚胎发育与类器官构筑的力学-生物学基础。"}, {"title": "技术创新点", "content": "自主首创：首次实现失重、超重条件下实验动物体征的实时、动态监测\n设备优势：无创模拟失重、超重条件，实验可重复性高\n高效稳定：可同时进行多只小鼠测试\n超重环境：可提供2-3g超重\n适用范围：药物研发、地外移民等研究场景\n知识产权：一系列发明专利支撑"}, {"title": "可应用领域", "content": "实验室装备：用于肌骨系统研究领域\n医药领域：实验动物体征实时监测"}]', 'negotiable', NULL, NULL, '任培根', NULL, '13603035435', 'pg.ren@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 03:34:16+08', '2025-06-18 03:34:16+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (184, 2, 162, '中国科学院深圳先进技术研究院', '复杂AI系统的通用自主智能体底座', 9, '自主智能体底座以大模型为基础，解决复杂AI系统三大共性能力：智力、工作能力和环境协同能力。其中，智力包含听看读写画能力、反思纠错能力以及学习能力；工作能力包括工具使用、多智能体协同工作能力、工作流生成执行能力；环境协同能力包括硬件资源规划、外部系统协同、数据治理以及交互。智能体底座可广泛应用于不同场景，驱动复杂AI系统高效工作，并且有着极高的兼容性与扩展性。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "强应用性；通用底座，可适用于不同场景与行业\n强扩展性：多尺度工具设计、多智能体主动相应策略、多智能体主动响应模式赋予系统强大的功能扩展性；\n高兼容性：与外部系统协同工作，与现有系统或外部系统有极强的兼容性"}, {"title": "技术成熟度", "content": "已经完成底座系统开发，可快速针对不同应用场景进行部署及应用扩展。"}, {"title": "可应用领域", "content": "数据管理平台、机器人系统等各场景下的多功能复杂AI系统。"}]', 'negotiable', NULL, NULL, '陈世峰', NULL, NULL, 'shifeng.chen@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:28:23+08', '2025-04-15 10:28:23+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (77, 2, 162, '中国科学院深圳先进技术研究院', '全息声镊生物显微操控系统', 13, '全息声镊是一种基于声学的非侵入式的精细操控手段。该创新性科研仪器融合了自主研发的多通道可编程超声硬件、高密度超声相控阵列等关键器件，开发了全息声学元素构建和迭代反推算法以精准构建复杂声场。为生命科学研究中类器官嵌合体的标准化构建，以及精准治疗中功能细胞的在体富集、靶向递送提供全新科学仪器。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "多功能全息声场动态生成\n个体分辨率的非接触式声学操控\n掌上多通道可编程超声硬件*\n多通道超声相控阵*\n*阵元数: 64，可编程电子通道数：64，\n工作频率 0.5~10MHz，脉冲重复频率 1~10MHz；\n发射幅值 -70~70V，聚焦点声压峰值不小于0.5 Mpa"}, {"title": "技术成熟度", "content": "完成原理样机搭建\n在实验环境中验证\n与质谱成像分析技术联用"}, {"title": "项目支持", "content": "科技部“纳米科技”重点研发专项\n工信部高质量发展专项\n医学成像科学与技术系统全国重点实验室专项支持\n深圳市医学研究专项\n深圳市科创委高层次人才创新创业基金"}, {"title": "可应用领域", "content": "生命科学：干细胞研究；复杂类器官打印；肿瘤浸润模型构建；空间代谢分析；药理机制作用。\n精准诊疗：细胞精准治疗；肿瘤靶向栓塞；在体声学打印。"}]', 'negotiable', NULL, NULL, '马腾', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:45:35+08', '2025-10-29 19:45:35+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (37, 2, 162, '中国科学院深圳先进技术研究院', '一种超声声场适形的基因转染装置', 16, '专利号：ZL202010734848.2', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "该专利技术是对现有超声靶向微泡破坏（UTMD）技术的改进型装置。其核心功效在于通过超声声场适形器精确匹配超声波的焦斑，实现对超声声场的适形覆盖。这一设计能够最大化利用超声能量，从而显著提高基因转染效率，并增强药物或基因的靶向传输特性和瞬间可逆渗透性 。在成熟度方面，该技术已获得发明专利授权，且专利中包含实验对比图，表明它已通过实验验证，已发展为具有实验基础的生物医学科研装置，为基因治疗的临床应用提供了新的高效工具。"}, {"title": "技术问题", "content": "现有的UTMD超声转染仪由于声场分布不均匀，导致超声探头辐照能量利用率低，进而造成基因转染效率低下。"}, {"title": "技术手段", "content": "设计了一种超声声场适形的基因转染装置，包括超声换能器、超声声场适形器和焦距适配器，超声声场适形器的形状和大小根据声场确定，通过焦距适配器固定于预设位置，实现对超声能量的最大化利用。"}, {"title": "应用场景及市场规模", "content": "该专利公开的超声声场适形的基因转染装置主要应用于生物医学研究和基因治疗领域。其核心价值是通过超声声场适形设计，解决传统超声靶向微泡破坏（UTMD）技术中超声能量利用率低、基因转染效率低下的问题，实现对细胞（如悬浮细胞、干细胞等）的高效、靶向的基因导入。在市场方面，该装置属于基因转染技术市场。鉴于全球转染技术市场规模在2024年已达12.589亿美元，且在癌症、慢性病研究及基因治疗的推动下持续增长。该装置作为一种高效的新型仪器，具有广阔的市场潜力和应用前景。"}]', 'negotiable', NULL, NULL, '严飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:45:59+08', '2025-12-09 18:45:59+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (35, 2, 162, '中国科学院深圳先进技术研究院', '一种靶向肿瘤的超声造影剂及其制备方法和应用', 16, '专利号：ZL202310218086.4', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "该专利公开的一种靶向肿瘤的超声造影剂，利用共价连接了环状多肽（如ZD2肽）的纳米泡，高特异性地靶向肿瘤细胞外基质。主要用于早期肿瘤（如膀胱癌）的精准诊断和分子成像，以及制备高特异性的抗肿瘤药物或药物递送剂，实现肿瘤的诊断和治疗一体化。该技术属于超声分子影像和靶向超声造影剂领域。该领域是医学影像诊断的“第三次革命”，正处于高速增长期。全球超声设备市场到2032年预计达169.1亿美元，而超声造影剂在中国市场的增速超过44%，是前景广阔的蓝海市场。该专利的靶向性、高安全性和低成本优势，预示其具有巨大的临床转化和商业潜力。"}, {"title": "技术功效与成熟度", "content": "该专利技术中的靶向超声造影剂（ZD2-GVs）功效显著，体现在其实现了对肿瘤区域的高特异性靶向结合和高穿透力，能有效穿透肿瘤血管间隙进入基质空间，并在体内动物实验中显示出远优于非靶向造影剂的超声成像效果。成熟度方面，该技术已成功制备，制备工艺简单且成本低 。目前处于临床前验证阶段，已在体外细胞和荷瘤小鼠模型上完成了靶向性、成像效果和稳定性的充分验证，为肿瘤的精准诊断、抗癌药物制备及药物靶向递送提供了重要的技术基础 。"}, {"title": "技术问题", "content": "现有超声造影剂在肿瘤靶向性、成像性、穿透力、抗原性和制备难度等方面存在缺陷，导致其在肿瘤诊断和治疗中效果不佳。"}, {"title": "技术手段", "content": "通过在纳米泡表面共价连接靶向肿瘤的环状多肽CTVRTSADC，并使用从Holabacteria NRC-1中提取的气体囊泡作为纳米泡，优化制备工艺以提高造影剂的靶向性和成像能力。"}]', 'negotiable', NULL, NULL, '严飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:48:55+08', '2025-12-09 18:48:55+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (46, 2, 162, '中国科学院深圳先进技术研究院', '高热稳定性酶的蛋白序列生成方法、装置、介质和设备', 16, '专利号：ZL202110726343.6', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本专利利用生成式对抗网络对高热稳定酶进行序列设计，实现从序列预测到实验验证的闭环，提高了酶的热稳定性和设计效率。技术依托成熟的深度学习算法和蛋白序列数据库，方法可批量生成高热稳定酶并筛选出最优候选，具有可重复性强、可靠性高的特点，已具备实验验证基础，技术成熟度较高，适合工业化应用推广。"}, {"title": "技术问题", "content": "现有方法难以快速批量生成高热稳定性酶，基于理性设计和定向进化方法存在局限性，无法满足工业需求。"}, {"title": "技术手段", "content": "采用生成式对抗网络模型，利用耐受高温特定类酶的蛋白序列数据进行训练，生成蛋白序列生成模型，批量生成高热稳定性酶的蛋白序列。"}, {"title": "应用场景及市场规模", "content": "该专利可应用于工业生物催化、制药和食品加工等领域，特别适用于需要高温条件下稳定运作的酶，如淀粉酶、蛋白酶和脂肪酶等。通过计算机辅助生成高热稳定性蛋白序列，可显著提高酶的设计效率，减少实验成本。随着全球工业酶市场持续增长，尤其是高性能酶在生物制药、纺织、造纸及生物燃料领域的需求增加，该技术具有广阔的市场前景，预计市场规模可达数十亿美元。"}]', 'negotiable', NULL, NULL, '罗小舟', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:07:23+08', '2025-12-09 18:07:23+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (55, 2, 162, '中国科学院深圳先进技术研究院', '一种用于X射线探测的钙钛矿络合物的制备方法及其产品与应用', 14, '专利号：ZL202310387749.5', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "项目团队已完成该技术中小试验证，在国际上率先制备了CMOS芯片驱动的钙钛矿半导体X射线成像面阵探测器，探测灵敏度高达1.6×104 µCGyair⁻¹cm⁻²，检测限低至321 nGyairs⁻¹，帧速可达300帧/秒。相比商用间接X射线探测器，可降低50%以上的辐射剂量，同时保持优异的空间分辨率（5.0 lpmm⁻¹。"}, {"title": "应用场景及市场规模", "content": "X射线成像在医疗影像、工业无损检测和安防检查等领域具有广泛应用。特别是在医疗诊断中，X射线成像是最常用方法，包括X射线造影、CT等。2024年全球CT市场规模已达100亿美元，且年复合增长率保持在8%-10%之间。"}, {"title": "技术问题", "content": "现有钙钛矿材料在X射线探测器领域存在单晶生长耗时长、难以大面积制备及厚膜制备受限，且多晶钙钛矿晶片中含有空隙和晶界，影响探测效率和稳定性，难以与基板集成。"}, {"title": "技术手段", "content": "采用钙钛矿与极性溶剂的混合干燥法制备钙钛矿络合物，通过压片技术获得致密均匀的钙钛矿晶片，并在退火过程中促进溶剂挥发和晶界融合，提高电荷传输性能。"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:48:34+08', '2025-12-09 17:48:34+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (163, 2, 162, '中国科学院深圳先进技术研究院', '骨科X射线影像采集及脊柱侧弯诊断系统', 13, '围绕低碳生产及应用，结合无机低维材料体系优势，从新材料制备及物性提升方面入手，实现了多款环保低功耗无机二维液晶的可控合成及其新奇应用开发。新型二维无机液晶响应灵敏度高且具有极大的电光克尔系数（高出传统液晶数个量级），可在超低场驱动下展现丰富生动的干涉色彩，突破了传统二色性染料液晶仅能实现黑态、亮态及灰阶状态的调节。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "采用单板单源的构成形式，通过对机械结构的精确运动控制，实现光源与平板探测器的整体直线运动与旋转运动，不仅大大降低成本，也能获取精确对齐的脊柱正侧位医学影像\n基于深度学习的二维脊柱图像分割与特征提取方法\n基于深度学习与统计形状模型的脊柱三维快速建模"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "青少年脊柱侧弯筛查\n骨科X射线成像"}]', 'negotiable', NULL, NULL, '谢耀钦', NULL, '13620902469', 'yq.xie@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:54:24+08', '2025-04-15 11:54:24+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (182, 2, 162, '中国科学院深圳先进技术研究院', '传染病精细化社会治理的时空数据智能技术', 9, '通过“地理信息+公共卫生”交叉技术创新，融合大规模人口、轨迹、环境、气象等多源时空大数据，利用空间显式多智能体模型、机器学习/深度学习模型以及传播动力学模型，实现了高风险人群快速感知、重大传染病的社区级/百米级传播风险时空模拟与预测、精细化防控措施的智能优化等关键技术。', NULL, '02_lab', NULL, NULL, '[{"title": "主要技术指标及优势", "content": "1.支持呼吸道传染病、虫媒传染病、肠道传染病等多种疾病类型；\n2.扩散模拟个体规模可达千万级，空间分辨率可达建筑物；\n3.风险预测空间精度可达百米级；\n4.支持各类精细化防控措施及其实施的力度和时空节点的智能优化。"}, {"title": "技术成熟度", "content": "成果实际应用于从国家到地方的呼吸道与虫媒等重大传染病防控工作，取得了显著的社会效益。"}, {"title": "主要应用领域", "content": "传染病防控决策、数字孪生、城市治理"}, {"title": "项目支持", "content": "国家自然科学基金、国家重点研发计划、广东省基础研究重点项目、深圳市基础研究重点项目、盖茨基金"}]', 'negotiable', NULL, NULL, '尹凌', NULL, NULL, 'yinling@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:32:04+08', '2025-04-15 10:32:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (40, 2, 162, '中国科学院深圳先进技术研究院', '副溶血弧菌噬菌体及包含该噬菌体的杀菌组合物', 16, '专利号：ZL201710953780.5', NULL, '02_lab', NULL, NULL, '[{"title": "技术手段", "content": "开发了一种专一性裂解弧菌的副溶血弧菌噬菌体VpaSw-1，并结合其他弧菌噬菌体构建杀菌组合物，通过噬菌体鸡尾酒疗法扩大宿主谱范围，降低抗性产生，实现快速高效的弧菌控制。"}, {"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "弧菌引起的水产养殖疾病由于抗生素滥用导致致病菌耐药性问题，单一噬菌体疗法存在宿主菌易产生抗性的缺陷，难以有效控制弧菌病的传播。"}, {"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 25%，细分场景需求持续释放。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:21:17+08', '2025-12-09 18:21:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (50, 2, 162, '中国科学院深圳先进技术研究院', '培养皿灌装设备', 16, '专利号：ZL202210078920.X', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有的自动化灌装设备无法对方形培养皿进行自动灌装，导致实验效率低下和平板厚度不一致的问题。"}, {"title": "技术手段", "content": "设计了一种包括设备架、灌装机构、储存机构和移动机构的培养皿灌装设备，通过可移动的出料管沿着培养皿的长度和宽度方向移动，实现对方形培养皿多个孔位的自动灌装。"}, {"title": "技术功效与成熟度", "content": "\"技术功效：通过可移动出料配合横向纵向运动结构，实现方形培养皿多孔位精准灌装。转盘式移动机构与夹紧结构协同作业，解决手工操作低效和污染问题。\n技术成熟度：具备完整机械架构及控制流程，经实施例验证模块协同能力，达到产业化实施条件。\""}, {"title": "应用场景及市场规模", "content": "应用场景：专为方形多孔培养皿（如4孔、24孔）自动化灌装设计，通过可移动出料管精准定位，解决手工操作效率低、易污染问题，适用于微生物研究、药物筛选等高通量实验场景。\n市场规模潜力：填补方形培养皿自动化设备市场空白，面向科研机构、制药企业等生命科学领域，随行业对标准化需求增长，具备明确商业化前景。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:58:52+08', '2025-12-09 17:58:52+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (105, 2, 162, '中国科学院深圳先进技术研究院', '水下多模态传感柔性电子皮肤', 3, '利用水环境和电极表面之间的天然离电界面，提出了一种适用水下场景的触觉传感策略，集成了包括接触压、触觉图像、深度、温度和盐度的多模态传感功能。可以在不同深度下实现接触压力的高敏感精确测量，解决了现有水下触觉传感器液压平衡结构设计产生所带来的尺寸过大、柔软性下降等问题。利用不同模块之间的数据处理可以实现环境自补偿功能，提高传感器在水下复杂环境中测量的准确性与稳定性。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "开放式结构设计：环境水作为传感组分，传感结构无需封装\n适应水深：0-40m\n接触力响应范围：0-250 kPa\n高空间分辨的触觉阵列：密度大于500点/cm²。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市基础研究重点项目"}, {"title": "技术成熟度", "content": "实验室原理组件或实验板在实验环境中验证。"}, {"title": "可应用领域", "content": "水下潜水员健康监测\n水下机器人精细操作"}]', 'negotiable', NULL, NULL, '程玙', NULL, NULL, 'Yu.cheng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 18:06:01+08', '2025-07-16 18:06:01+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (128, 2, 162, '中国科学院深圳先进技术研究院', '废旧塑料资源化利用技术', 14, '基于当前废弃塑料带来的”白色污染”和资源错配问题，通过绿色能源驱动的光热-光电一体化新型回收提值方式，实现了废旧聚酯类塑料向乙醇酸、电子级乳酸酯等高值产品的绿色转化。构筑的光热-光电耦合体系为解决塑料废弃物的绿色增值回收提供了新的方向，侨联废旧塑料赋能与绿色制造，为低碳社会的建设提供新的路径。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "新体系：光热-光电一体化；\n高增值：聚酯类塑料废弃物转化为电子级乳酸酯、乙醇酸等；\n普适性：开发规模化催化体系应用实现废旧塑料绿色解聚。"}, {"title": "技术成熟度", "content": "已通过溶剂热解聚法，结合电催化技术实现了聚对苯二甲酸乙二醇酯(PET)以及聚乳酸(PLA)的升级回收，得到乙醇酸和电子级乳酸酯等一系列高附加值精细化学品。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "再生塑料制品、 能源回收、化学原料回收、工业添加剂、液体燃料等领域。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:11:33+08', '2025-04-15 14:11:33+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (132, 2, 162, '中国科学院深圳先进技术研究院', 'CMOS兼容的近红外宽波段探测器及成像芯片', 14, '近红外探测与成像技术可以获得媲美可见光成像的分辨能力，又兼具有红外成像的微光夜视效果及较强的穿透雾霾、水汽能力，是国土安全防御，新一代夜视单兵装备等核心器件，同时在机器视觉、个人智能终端中的需求越来强烈。我们开发了一种新型优良窄带隙p型半导体材料，实现了CMOS晶圆上硅基单片异质集成、低成本、高分辨率近红外阵列成像芯片。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高分辨率：640*512；\n宽谱响应：300-1600 nm；\n暗电流：≤500 nA/cm2\n峰值量子效率≥60%@1310 nm\n响应时间：~3 ns\n硅基单片异质集成"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "国防安防、个人智能终端、生物医学、智能驾驶、光通信、具身智能等应用。"}]', 'negotiable', NULL, NULL, '杨春雷', NULL, NULL, 'cl.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:18:38+08', '2025-04-15 14:18:38+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (173, 2, 162, '中国科学院深圳先进技术研究院', '干预帕金森病的新型靶向神经调控技术', 13, '帕金森病是老年人群中最为常见的神经退行性疾病之一。目前，帕金森病以多巴胺替代药物治疗为主，然而随着病程进展，疗效减退且出现异动症等副作用。因此，亟需研发高效、安全、持久的新型帕金森病疗法。深圳先进院路中华、戴辑、鲍进团队在《细胞》发表研究工作，提出了一种用于治疗帕金森病的新型神经调控技术。在前期非人灵长类动物上的实验表明，该疗法在不影响大脑其他神经环路的情况下，对帕金森病累及的关键神经环路进行精准靶向干预，为帕金森病临床治疗提供了潜在的全新策略。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "团队开发的靶向神经调控技术解决了如何在灵长类脑中实现对疾病累及的神经环路实现高度靶向精准调控的技术挑战，该解决方案理论上可以应用于帕金森病的临床干预。"}, {"title": "技术成熟度", "content": "已完成在非人灵长类帕金森病动物模型中的效价测试。"}, {"title": "项目支持", "content": "国家自然科学基金\n深港脑科学创新研究院"}, {"title": "可应用领域", "content": "帕金森病运动相关症状的干预。"}]', 'negotiable', NULL, NULL, '路中华', NULL, '13534231201', 'zh.lu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:57:33+08', '2025-04-15 10:57:33+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (70, 2, 162, '中国科学院深圳先进技术研究院', '为开发靶向ecDNA的抗肿瘤策略提供关键突破口', 16, '围绕肿瘤发生发展的关键驱动因素，聚焦染色体外DNA（ecDNA）这一与肿瘤恶性演进密切相关的特殊环状DNA分子。首次捕获了ecDNA进行复制的直接证据，并全面解析了与ecDNA复制相关的蛋白质网络，系统揭示了ecDNA维持与DNA损伤应答之间的双向调控关系、ecDNA在复制维持机制、表观遗传调控及其促癌作用中的新规律，为开发靶向ecDNA的抗肿瘤策略提供了理论依据和转化应用靶点。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "ecDNA通过复制依赖性激活ATM及DDR机制维持其稳定性\nTOP1与TOP2B是ecDNA诱导DDR的关键调控因子\n替代性非同源末端连接途径（Alt-NHEJ）促进ecDNA的维持\nATM介导的DDR机制成为治疗ecDNA阳性肿瘤的潜在靶点"}, {"title": "项目支持", "content": "国家重点研发计划\n国家自然科学基金\n中国科学院战略性先导科技专项\n广东省基础与应用基础研究基金\n深圳市自然科学基金\n深圳市医学研究专项资金\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "理论的重大突破\n靶点处于动物实验阶段"}, {"title": "可应用领域", "content": "脑胶质瘤等恶行肿瘤的诊疗"}]', 'negotiable', NULL, NULL, '甘海云', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 17:30:35+08', '2025-10-30 17:30:35+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (76, 2, 162, '中国科学院深圳先进技术研究院', '水合物储层和海底渗漏一体化原位动态监测技术', 9, '水合物储层稳定性及海底渗漏监测是海洋水合物商业化开采进程的重要一环，已有海底原位监测系统方法受限于大水深、大数据量、通讯手段匮乏，通常将监测数据原位存储，在此背景下，采用研发的水合物储层及海底渗漏一体化原位监测系统，将监测数据回传并实现动态监测。本项目中海底原位设备搭载地震波四分量传感器、甲烷传感器，连续采集地震波以及甲烷浓度数据，并进行数据边缘处理、提取、压缩；数据通讯部分采用声学通讯机实现大数据量传输，稳定通讯距离达2km，峰值通讯速率达6000bps，同时搭配控制模块以及通讯协议实现水下设备休眠、唤醒；动态监测部分通过自主研发软件对回传数据进行实时解码、分析、显示。本项目的相关成果可拓展至海洋生态、环境、自然灾害监测等较多应用场景。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "一体化潜标设计：支持多种多源数据同步获取。\n动态传输：突破自容式存储，利用声学通讯动态传输数据\n高速通讯：2km可靠通讯速率可达6kbps。"}, {"title": "技术成熟度", "content": "完成系统联调、近海测试与物试验区海试验证，从中试向示范验证推进。"}, {"title": "项目支持", "content": "广东省海洋六大产业重大项目\n深圳市基础研究专项重点项目"}, {"title": "可应用领域", "content": "天然气水合物开采监测、海洋环境与生态监测、海洋地质灾害预警、海洋资源勘探、海洋科学研究"}]', 'negotiable', NULL, NULL, '李林伟', NULL, '15165272258', 'lw.li1@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:49:33+08', '2025-10-29 19:49:33+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (34, 2, 162, '中国科学院深圳先进技术研究院', '一种超声声场适形的基因转染装置', 16, '专利号：ZL202021510276.1', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": ""}, {"title": "技术手段", "content": "设计了一种超声声场适形的基因转染装置，包括超声换能器、超声声场适形器和焦距适配器，通过适形覆盖超声声场，实现对超声能量的最大化利用，提高基因转染效率。超声声场适形器根据声场形状和大小确定，并通过焦距适配器固定于预设位置，确保超声能量的均匀覆盖。"}, {"title": "技术功效与成熟度", "content": "该专利技术是对现有超声靶向微泡破坏（UTMD）技术的改进型装置。其核心功效在于通过超声声场适形器精确匹配超声波的焦斑，实现对超声声场的适形覆盖。这一设计能够最大化利用超声能量，从而显著提高基因转染效率，并增强药物或基因的靶向传输特性和瞬间可逆渗透性 。在成熟度方面，该技术已获得发明专利授权，且专利中包含实验对比图，表明它已通过实验验证，已发展为具有实验基础的生物医学科研装置，为基因治疗的临床应用提供了新的高效工具。"}, {"title": "应用场景及市场规模", "content": "该专利公开的超声声场适形的基因转染装置主要应用于生物医学研究和基因治疗领域。其核心价值是通过超声声场适形设计，解决传统超声靶向微泡破坏（UTMD）技术中超声能量利用率低、基因转染效率低下的问题，实现对细胞（如悬浮细胞、干细胞等）的高效、靶向的基因导入。在市场方面，该装置属于基因转染技术市场。鉴于全球转染技术市场规模在2024年已达12.589亿美元，且在癌症、慢性病研究及基因治疗的推动下持续增长。该装置作为一种高效的新型仪器，具有广阔的市场潜力和应用前景。"}]', 'negotiable', NULL, NULL, '严飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:49:59+08', '2025-12-09 18:49:59+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (178, 2, 162, '中国科学院深圳先进技术研究院', '晓星智能学伴: 基于教育和心理大模型的AI学习伙伴', 9, '晓星智能学伴是由中国科学院深圳先进院和深圳联合信息联合研发的人工智能教育产品，旨在满足教育行业用户需求。它具备智能预习、复习、听读、听写、AI语音问答和心理辅导等功能，通过精准教学改善发音问题。此外，晓星智能学伴还提供技术支持和解决方案，助力教育机构智能化升级，推动数字化校园建设。它特别关注家庭教育场景，解决家长辅导难题，并通过启发式学习模式和情感化陪伴，为学生提供全方位的学习支持，营造轻松的学习氛围。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "实现教育和心理双域大模型协同驱动的智能对话系统。"}, {"title": "项目支持", "content": "中国科学院深圳先进院-深圳联合信息-教育人工智能联合实验室"}, {"title": "可应用领域", "content": "教育领域\n心理健康领域"}, {"title": "产业合作", "content": "2023年与深圳联合信息成立联合实验室\n电话：0755-86665684  \n邮箱：support04@szunion-info.com"}]', 'negotiable', NULL, NULL, '倪仕文', NULL, '15827639393', 'sw.ni@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:48:26+08', '2025-04-15 10:48:26+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (220, 2, 162, '中国科学院深圳先进技术研究院', '仿生自体纳米免疫检查点药物', 3, '仿生自体纳米免疫检查点药物（BAN）是一种模仿人体内自身可少量合成的物质的纳米药物。通过精准靶向肿瘤微环境中肿瘤细胞及巨噬细胞/髓系细胞上的Siglec15受体，有效抑制其表达，从而阻断髓系细胞对T细胞的耗竭作用，恢复并增强T细胞的免疫功能，实现对肿瘤细胞的直接杀伤与抑制其生长扩散的双重效果。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "新免疫检查点治疗：避开了研发同质化严重的PD-1/PD-L1。仿生材料：模仿人体自身活性物质。成本低：合成工艺简易，存储运输便利，有效降低生产成本。多剂型开发：除血液注射外，还可通过口服的方式给药。"}, {"title": "技术成熟度", "content": "已完成临床前实验实验：在体内外已验证BAN能显著抑制Siglec15的表达，有效遏制肿瘤生长。且在与PD-1/PD-L1免疫检查点抑制剂联合使用时，展现出更为强劲的协同抗肿瘤效应，显著提高了实验动物的生存率。"}, {"title": "可应用领域", "content": "抗肿瘤治疗：因为在人肿瘤中，髓源细胞具有大量浸润的特点。因此BAN的适应症可包括大多数肿瘤类型，如结直肠癌、肺癌、肝癌、黑色素瘤等。"}]', 'negotiable', NULL, NULL, '李洋', NULL, NULL, 'yang.li@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 16:52:05+08', '2025-04-14 16:52:05+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (119, 2, 162, '中国科学院深圳先进技术研究院', '海洋作业外骨骼机器人', 9, '海洋作业如石油平台维护、管道安装与检查、水下救援和船体清洁等，通常需要潜水员在水下长时间工作。长时间的潜水活动会导致潜水员的代谢成本大幅增加，进而增加减压病等疾病风险。团队依据潜水员水下多模态动作特征，研制了柔性潜水助力外骨骼系统PEAKED，能够协助潜水员完成包括交替打腿、蛙泳腿以及水下行走三类水下动作，同时大幅降低水下耗气速率达29.77%，有效提升水下作业效率与安全性。相关成果发表在机器人权威期刊IEEE Transactions on Robotics上。
Marine operations such as offshore maintenance, pipeline inspection, underwater rescue, and hull cleaning often require divers to work underwater for long periods. Prolonged diving substantially increases metabolic cost and the risk of decompression sickness. To address this challenge, our team developed PEAKED, a soft diving assistive exoskeleton that supports flutter kicking, breaststroke kicking, and underwater walking. PEAKED reduced divers’ air consumption rate by 29.77%, thereby improving underwater operational efficiency and safety. This work was published in IEEE Transactions on Robotics.', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点Technical Innovations", "content": "新型套索传动驱动器：支持大腿屈曲和伸展方向助力，不阻碍腿部正常动作；\n水下动态密封技术：支持最大水深150m防水，满足主要任务深度潜水需求；\n自适应助力方法：支持交替打腿、蛙泳腿和水下行走助力，精准预测助力动作相位。\nHip flexion and extension assistance\nWaterproof up to 150 m\nAccurate multi-mode phase prediction"}, {"title": "技术成熟度Technology Readiness Level", "content": "7级-环境级\n在实际环境中的系统样机试验\nLevel 7 – Environment\nSystem prototype testing in real-world conditions"}, {"title": "项目支持Fundings", "content": "国家自然科学基金杰出青年基金\n国家自然科学基金面上项目\n广东省粤港澳研究团队项目\n深圳市医学研究专项资金项目\nNSFC Distinguished Young Scholars Fund\nNSFC General Program\nGuangdong–Hong Kong–Macao Joint Research Team Program\nShenzhen Medical Research Fund"}, {"title": "可应用领域Applications", "content": "海洋工程（石油、风电）\n水库船坞服务（切割、清理）\n救援组织（潜水协会、搜救中心）\nOffshore engineering (oil, wind power)\nReservoir and dock services (cutting, cleaning)\nRescue organizations (search and rescue centers)"}]', 'negotiable', NULL, NULL, '吴新宇Xinyu Wu', NULL, NULL, 'xy.wu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 04:04:34+08', '2025-06-18 04:04:34+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (6, 2, 162, '中国科学院深圳先进技术研究院', 'High Temporal & Spatial Resolution Real-time 4D Imaging Technology', 9, 'Dynamic 3D imaging (4D imaging) is a research frontier​ in information technology. Compared with traditional low-resolution RGB-D systems, the high temporal-spatial resolution real-time 4D imaging system developed by our team​ demonstrates significant improvements​ in resolution, accuracy, and speed. Utilizing​ self-developed high-frequency structured light coding algorithms and digital grating fringe projection devices, this system delivers 120 Hz 3D imaging at 1920×1080 resolution​ with a depth measurement accuracy of 0.05 mm, placing its core technical indicators at the internationally leading level.', NULL, '02_lab', NULL, NULL, '[{"title": "Technical Innovations", "content": "Imaging Resolution: 1920 × 1080 pixels\n3D Imaging Frame Rate: 120 Hz\nDepth Measurement Accuracy: 0.05 mm"}, {"title": "Technology Readiness", "content": "Laboratory prototype components have been validated in the experimental environment."}, {"title": "Project Support", "content": "Key-Area Research and Development Program of Guangdong Province, China"}, {"title": "Application Fields", "content": "Robotics, virtual reality, digital humans, holographic video transmission, healthcare, industrial automation, etc."}]', 'negotiable', NULL, NULL, 'SongZhan, PhD, Professor', NULL, '15889608167', 'zhan.song@siat.ac.cn', NULL, 'published', NULL, 1, 1, '2026-05-18 20:24:17+08', '2026-05-18 20:24:17+08', '2026-09-15 15:06:37.257658+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (143, 2, 162, '中国科学院深圳先进技术研究院', '云冕：工业人工智能大模型', 9, '随着新型工业化的加速推进，人工智能大模型已成为现代工业生产的新型驱动力。围绕新型工业化转型的需求，SIAT云计算研究中心叶可江团队基于通用开源大模型基座研发出了面向工业领域的云冕工业大模型，利用领域工业场景数据及大模型微调技术，已在工业知识问答、工业产品表面缺陷检测及工业产品设计代码辅助生成等场景中发挥重要作用，该成果获2024全国工业互联网创新大赛“优秀奖”、2024年中国国际高新技术成果交易会“优秀科研成果创新奖”。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "基于国产基模\n中文交互界面\n先进的微调技术\n强大的泛化能力"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家重点研发计划“工业软件”专项青年科学家项目\n国家自然科学基金“未来工业互联网”重大研究计划培育项目"}, {"title": "可应用领域", "content": "在工业生产环节的研发设计、工艺优化、产品质检等场景中可以发挥重要作用"}]', 'negotiable', NULL, NULL, '叶可江', NULL, NULL, 'kj.ye@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:24:53+08', '2025-04-15 14:24:53+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (197, 2, 162, '中国科学院深圳先进技术研究院', '面向人机物共融的智能感知与决策研究', 9, '随着人口红利的消失与“小批量、多批次”产品需求的增加，制造型企业面临劳动力短缺与快速产线切换的挑战，亟需建立高度灵活的数字化生产新模式，大力提升柔性化和智能化水平。基于人机物共融协同工作的智能制造是应对这些挑战的有效途径，面向智能制造的非结构化复杂环境不断提高人机协同智能感知和决策能力是核心所在。针对人机共融面临的挑战，研究主要从多模态感知与场景语义理解、人机共融场景三维模型的一致性构建、多通道意图推理与自然人机交互、融合感知与交互的人机协同决策四个方面展开。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "小样本学习的语义理解；\n不完整数据的三维建模；\n多通道稳态的自然人机交互；\n多维驱动的人机协同可信决策。"}, {"title": "技术成熟度", "content": "实验室原理样机组件在实验环境中验证。"}, {"title": "项目支持", "content": "广东省基础研究重点基石项目"}, {"title": "可应用领域", "content": "智能制造和装配、智能制造与数字孪生等应用。"}]', 'negotiable', NULL, NULL, '程俊', NULL, '13510704355', 'jun.cheng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:47:43+08', '2025-04-14 17:47:43+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (107, 2, 162, '中国科学院深圳先进技术研究院', '高灵敏度表面增强拉曼散射芯片', 3, '表面增强拉曼散射SERS技术，是一种通过将分子吸附在粗糙金属纳米结构表面，利用电磁场局域共振效应和化学增强机制，使拉曼散射信号强度显著提升的高灵敏度分析技术，广泛应用于化学、生物医学等领域的微量物质检测。团队运用超快激光微纳加工与化学修饰相结合的技术，设计和研制了可限域液滴的图案化SERS芯片，能够高效定位和富集分析物分子，实现被测物质分子快速、灵敏和精准的分析检测。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "超亲/疏水复合图案化结构可高效定位浓缩和富集分析物；\n易于与微透镜集成和协同实现超高灵敏度的拉曼散射增强；\n激光加工灵活度高、材料适用范围广、制备步骤少、效率和成本效益高。"}, {"title": "项目支持", "content": "国家自然科学基金-重大科研仪器研制项目\n国家自然科学基金-面上项目\n广东省自然科学基金-面上项目"}, {"title": "技术成熟度", "content": "已设计和制作了多种不同规格的芯片，并成功应用于有害鱼药检测和肿瘤分子边界术中定位等领域。"}, {"title": "可应用领域", "content": "生物医学检测、环境与食品安全、药物开发与临床诊断等。"}]', 'negotiable', NULL, NULL, '顾国强', NULL, NULL, 'gq.gu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 18:01:34+08', '2025-07-16 18:01:34+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (11, 2, 162, '中国科学院深圳先进技术研究院', '面向车网互动的新能源汽车充电站运营技术', 9, '通过对充电站运营数据的分析，提取新能源汽车用户充电特征并预测充电站使用情况和充电站充电负荷，从用户、充电站、电网的角度考虑，对未来新能源汽车规模迅速扩大和车网互动技术下的新能源汽车多目标充放电技术进行了探索，对新能源汽车充电站和电网运营提供了技术参考和解决方案。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "基于数据分解和深度学习的充电站充电负荷混合预测方法；\n考虑用户、充电站、电网的新能源汽车多目标充放电策略；\n基于新型深度强化学习算法的新能源汽车充放电策略。"}, {"title": "技术成熟度", "content": "受限于有限的车网互动环境，目前完成了计算机仿真验证。"}, {"title": "项目支持", "content": "中国科学院-韩国国家科技理事会协议项目"}, {"title": "可应用领域", "content": "智能电网管理、风电/光伏发电/充电负荷等预测、光储充一体化运营站管理等"}]', 'negotiable', NULL, NULL, '郑春花', NULL, '18665904226', 'ch.zheng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2026-03-09 16:12:09+08', '2026-03-09 16:12:09+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (145, 2, 162, '中国科学院深圳先进技术研究院', '光通讯智能控温用微型热电器件', 14, '围随着人工智能、云计算、大数据中心、5G通讯的快速发展，对高速率光模块的依赖越来越重。5G基站/数据中心光模块TEC总需求量超过超过7000万颗，年增速超过20%；
采用热电制冷器件对光模块进行精准的主动控温，保持其工作在温度稳定的环境下，是目前最主要的确保光模块有效工作、延长使用寿命的技术解决方案。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高性能：P型ZT>1.3，N型＞1.0\n大尺寸：直径30mm或者30mm×30mm方棒\n低能耗：最大致冷温差72 K\n最小单元尺寸：0.25mm×0.25mm；\n最大致冷功率密度：26W/cm2；"}, {"title": "技术成熟度", "content": "器件小批量定制\n技术成熟度：5级"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "5G/数据中心光模块、车载激光雷达\n光纤放大器、激光泵浦器、雪崩二极管等\n基站空调、医疗装备"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:20:45+08', '2025-04-15 14:20:45+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (162, 2, 162, '中国科学院深圳先进技术研究院', '新型生理参数监测及慢病管理', 13, '采用智能传感器收集连续的生理、生化和行为数据，通过人工智能和混合智能分析，提取高精度的无创连续生理信号；同时结合疾病进展或治疗干预反应，挖掘相应表征的新型数字生物标志物。从而为用户提出健康风险预警、制定个性化健康管理和干预方案，实现疾病的早预防、早诊断、早治疗。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "多生理参数监测：睡眠（接触/非接触）、心电、血氧、心电图等多参数；\n连续监测：24小时连续采集和存储；\n营养健康：拍照识别食物及营养信息；\n科研平台：可连续保存长时间的生理参数原始数据。"}, {"title": "技术成熟度", "content": "该健康管理平台已在部分医院试点使用"}, {"title": "项目支持", "content": "科技部重点研发计划\n中科院STS黄埔专项\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "疾病诊断及治疗，个体健康管理，药物研发及临床试验科研"}]', 'negotiable', NULL, NULL, '聂泽东', NULL, '13926598060', 'zd.nie@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:55:50+08', '2025-04-15 11:55:50+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (108, 2, 162, '中国科学院深圳先进技术研究院', '基于指尖血干血斑样本的免疫防护检测技术', 3, '围绕人体的抗体免疫水平评估，结合管式微流控化学发光免疫分析（TOI）技术，从样本的采样便捷程度与储存性能提升入手，整合了一套基于指尖血干血斑样本的抗体免疫水平检测系统。该技术只需要5-10 μL指尖血全血制成的干血斑样本，即可精准量化至少六种传染性病原体的特异性抗体水平。干血斑样本便于采集，且非常稳定，可在常温下保存至少70天。可服务于偏远地区公共卫生研究、战场防疫、居家样本采集等非典型医疗场景。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "样本提取简便：创口小且无需专业医师；\n速度快：在20分钟内评估抗体免疫反应；\n所需样本量小：只需5-10 μL指尖血即可完成至少六种传染性病原体的特异性抗体定量。\n样本保存便利：在常温下稳定保存长达70天，在37°C中保存14天。"}, {"title": "项目支持", "content": "深圳先进技术研究院优秀青年创新基金\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "与罗湖医院集团合作，采集了数百位志愿者指尖血干血斑样本，完成了基于TOI上进行了验证，并应用于大批量的临床样本的检测中。"}, {"title": "可应用领域", "content": "临床诊断、疫苗接种与免疫反应评估、传染病监测与流行病学调查、野战卫生工作。"}]', 'negotiable', NULL, NULL, '谭骁天', NULL, '15810328603', 'Xt.tan@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 17:59:13+08', '2025-07-16 17:59:13+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (22, 2, 162, '中国科学院深圳先进技术研究院', '四核射频线圈电路', 13, '专利号：ZL202010346493.X', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本发明针对磁共振代谢成像应用，通过独特的双层嵌套式线圈结构与多通道电子系统协同工作，有效解决了不同代谢物信号采集过程中的相互干扰与电磁兼容难题。该实物系统已在MRI设备上成功应用，并获得高质量代谢图像。其具备高均匀性激发与高灵敏度接收能力，有效提升了代谢物检测精度与成像效率，为精准代谢成像提供了可靠技术。"}, {"title": "应用场景及市场规模", "content": "该发明专利主要应用于高端磁共振成像系统，特别适用于肿瘤、神经系统疾病及代谢性疾病的精准诊断。通过实现对多种关键代谢物的同步高灵敏度检测，该技术可显著提升医学研究与临床诊断水平。全球磁共振市场规模已超70亿美元，精准医疗与多模态分子成像需求的持续增长，为具备代谢成像能力的先进射频线圈技术带来了明确的市场空间与发展机遇。"}, {"title": "技术问题", "content": "在高磁场的大样本成像应用中，多通道四核RF线圈面临技术挑战，包括不同核通道之间的相互作用、通道间的相互耦合以及在高强度电磁场中的复杂电磁波行为，导致传输效率和接收灵敏度降低。"}, {"title": "技术手段", "content": "采用双层嵌套式结构组合设计的四核射频线圈电路，通过第一线圈阵列和第二线圈阵列的双层嵌套设计，实现多通道多频率高均匀性的射频激发和高灵敏度的信号采集。该设计通过相位差叠加排列的线圈单元，减少内外层线圈核素间的干扰，并通过独立失谐电路控制各核素线圈的工作状态，降低电磁干扰。"}]', 'negotiable', NULL, NULL, '李烨', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 19:30:03+08', '2025-12-09 19:30:03+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (151, 2, 162, '中国科学院深圳先进技术研究院', '基于超声相控阵的全息声镊操控平台', 13, '全息声镊是一种基于声学的非侵入式的精细操控手段。该创新性科研仪器融合了自主研发的多通道可编程超声硬件、高密度超声相控阵列等关键器件，开发了全息声学元素构建和迭代反推算法以精准构建复杂声场。为生命科学研究中类器官嵌合体的标准化构建，以及精准治疗中功能细胞的在体富集、靶向递送提供全新科学仪器。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高密度超声相控阵（阵元数 = 256），256路可编程电子通道，工作频率 0.5~10MHz，脉冲重复频率 10~4000Hz；\n发射幅值 -50~50V，聚焦点声压峰值不小于0.5 Mpa"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "科技部“纳米科技”重点研发专项\n中国科学院国家重点实验室\n深圳市医学研究专项"}, {"title": "可应用领域", "content": "生命科学、精准治疗，体外器官，病理模型的构建，细胞治疗。"}]', 'negotiable', NULL, NULL, '马腾', NULL, NULL, 'teng.ma@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:08:07+08', '2025-04-15 14:08:07+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (153, 2, 162, '中国科学院深圳先进技术研究院', '无透镜全息三维显微成像', 13, '生物样品的三维成像可以深入观察和分析复杂生物结构，从而获得关于细胞、组织、甚至整个生物体的空间信息，在癌症研究、神经科学、发育生物学和组织工程等领域得到了广泛应用。秦文健团队利用无透镜全息技术，结合多角度和多波长技术，完成样品信息的多维度采集，实现大视野无标记超分辨三维成像，且无需荧光标记，有效解决成像视场和光毒性光漂白难题，对于活细胞实时监测、活体组织成像等生物医学成像应用具有实际意义。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "无标记：无需染色，无光毒性；\n无机械运动三维成像：通过光源照明实现多维信息采集，实现三维成像；\n超分辨：突破图像传感器像元尺寸限制"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家重点研发项目\n深圳市基础重点"}, {"title": "可应用领域", "content": "病理切片，组织胚胎，类器官，活细胞"}]', 'negotiable', NULL, NULL, '秦文健', NULL, NULL, 'wj.qin@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:51:32+08', '2025-04-15 13:51:32+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (169, 2, 162, '中国科学院深圳先进技术研究院', '高清晰高灵敏MRI兼容小动物PET成像仪器', 13, 'PET和MRI功能高度互补和互相辅助，同时PET/MRI小动物成像为临床前生物医学研究提供一台强大的工具。本项目采用创新的高三维位置分辨率探测器和磁兼容电子学，填补了我国在高端MRI兼容小动物PET功能成像仪器研发方面的空白，仪器的空间分辨率和效率都达到国际先进水平。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "采用基于双端读出的高分辨率三维PET探测器，PET成像仪器同时达到整个成像视野均匀高清晰和高灵敏。"}, {"title": "技术成熟度", "content": "2020年完成样机，用于院内外多个研究课题数百只小动物成像研究。"}, {"title": "项目支持", "content": "国家自然科学基金重大科研仪器\n深圳市孔雀团队\n中国科学院仪器研制团队"}, {"title": "可应用领域", "content": "疾病的动物模型、新的药物和治疗方法等生物医学研究。"}]', 'negotiable', NULL, NULL, '杨永峰', NULL, '13802279548', 'yf.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:30:09+08', '2025-04-15 11:30:09+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (180, 2, 162, '中国科学院深圳先进技术研究院', '非植入式脑机接口芯片', 9, '围绕非植入式脑机接口中高集成度低功耗芯片的需求，研发了非植入式的8通道EEG/EMG采集芯片，实现了对肌电和脑电的低功耗低噪声采集。并基于以上芯片设计了两套肌电采集识别软硬件系统，分别在人体上臂和手腕处采集8通道表面肌电信号，实现了残疾人对假肢的控制，以及对机械手的远程控制。该研究成果还得到了华为的肯定，合作开展了将该系统转换到手表中的研究。相关论文也成功发表在了【IEEE TNSRE, 2022, 2024】。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低能耗：1.35mW；\n低噪声：2.18μVrms；\n普适性：自适应持续学习双模型策略建立个体化校准模型；\n推广性：轻量化算法的设计可以移植到智能终端设备"}, {"title": "技术成熟度", "content": "芯片已成功流片并经过实验室和第三方测试；肌电采集和控制系统原理样机在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市技术攻关项目"}, {"title": "可应用领域", "content": "人机控制系统、智能手表、假肢等。"}]', 'negotiable', NULL, NULL, '孙方敏', NULL, NULL, 'fm.sun@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:35:53+08', '2025-04-15 10:35:53+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (194, 2, 162, '中国科学院深圳先进技术研究院', '基于宽波段红外多光谱技术的气体泄露成像检测设备', 9, '围绕气体泄露成像监测的利用，利用宽波段非制冷红外探测器和光谱成像手段，实现了气体多光谱成像设备的研发，可以快速实现泄漏气体“云团”拍摄，定位泄露源，分析气体扩散趋势并确定气体成分，作为化工园区现有气体泄露技术的有效补充，有效提升园区安全级别，并作为应急管理部推荐使用的技术之一。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "采用宽波段红外探测器，\n同时具备中波和长波气体\n探测能力；\n创新的气体检测算法，实现气体快速检测和定位"}, {"title": "技术成熟度", "content": "在典型使用环境下得到验证。"}, {"title": "项目支持", "content": "广东省重点领域研发计划"}, {"title": "可应用领域", "content": "化工园区泄露气体监测、环境监测、战场毒气监测等。"}]', 'negotiable', NULL, NULL, '陈巍', NULL, NULL, 'chenwei@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:53:07+08', '2025-04-14 17:53:07+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (82, 2, 162, '中国科学院深圳先进技术研究院', '分布式刚度可调柔性力传感器及灵巧手', 13, '分布式刚度可调柔性力传感器及灵巧手采用五指仿生设计，高度模拟人手操作能力，作为人形机器人末端执行器，胜任多种复杂精细任务。具备多模态感知与刚度可调触觉系统，通过柔性驱动实现柔顺操作与精准力控，显著提升在非结构化环境中的适应性与操作稳定性。适用于工业装配、服务机器人及医疗辅助等领域，为智能机器人实际应用提供关键技术支撑。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "1. 传感器刚度可调；\n2. 多模态感知能力；\n3. 五指仿生机器手；\n4. 多自由度设计；\n5. 柔性肌腱驱动。"}, {"title": "技术成熟度", "content": "该灵巧机器人手在多种应用场景中表现出优异性能，成功实现了力检测及复杂操作等任务。"}, {"title": "可应用领域", "content": "工业装配、服务机器人及医疗辅助等领域。"}]', 'negotiable', NULL, NULL, '杨扬', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:33:48+08', '2025-10-29 19:33:48+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (83, 2, 162, '中国科学院深圳先进技术研究院', '多模成像引导腔内脉冲电场消融仪器', 13, '本仪器从新仪器研制及诊疗结合方面入手，实现了多模影像实时引导腔内脉冲电场消融仪器的设计开发，首次实现实时影像引导下开展的脉冲电场消融术。该仪器融合了超声、荧光、OCT三种成像模态，可同时实现形态学和病理学诊断，脉冲电场消融可选择性消融病灶并保留周围重要结构。诊疗一体化导管直径高度集成至3mm以内，可实现对消化道肿瘤、心血管疾病等重大慢病的超微创诊疗。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "首次实现三模态成像仪器研发，可提供自然腔道结构的高分辨全景信息\n首次集成影像导管与脉冲电场消融导管，可实现诊断与治疗的时空同步\n首创实时影像引导的脉冲电场消融术，大大简化了消融手术流程"}, {"title": "技术成熟度", "content": "完成原理样机搭建\n开展多例在体小动物消化道肿瘤消融研究\n开展多例在体小动物血管内影像分析\n筹备在体大动物胰胆管消融实验"}, {"title": "项目支持", "content": "自然科学基金委国家重大科研仪器研制项目\n科技部十四五重点研发项目\n深圳市科创委高层次人才创新创业基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "经自然腔道：结直肠癌、胰腺癌等消化道腔道肿瘤的诊断与治疗；慢阻肺、糖尿病等疾病的诊疗\n经血管通路：血管内不稳定斑块早期诊断及发生发展机理研究"}]', 'negotiable', NULL, NULL, '马腾', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:31:01+08', '2025-10-29 19:31:01+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (65, 2, 162, '中国科学院深圳先进技术研究院', '虚拟电厂分层分区聚合调控技术', 14, '围绕低碳能源转型与新型电力系统建设需求，聚焦虚拟电厂“分层分区聚合调控”关键技术，突破多源异构资源建模、响应不确定性量化与多主体协同决策等核心难题。依托人工智能驱动的动态聚合与精准调控能力，形成分层分区聚合调控架构，并在工业负荷型和商业负荷型虚拟电厂示范工程中落地验证。系统可聚合分布式光伏、储能与可调负荷等多类资源，显著提升资源响应能力、系统灵活性与多场景互动调控。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高精度量化：融合数据增强与迁移学习，量化多时域响应能力；\n高效智能决策：无模型强化学习驱动，实现多尺度自适应调控；\n高协同控制：结合联邦与实时强化机制，提升多区域资源协同效率；"}, {"title": "技术成熟度", "content": "已完成多类型负荷聚合建模与虚拟电厂平台实际应用验证。"}, {"title": "项目支持", "content": "国家重点研发项目\n国家电网项目"}, {"title": "可应用领域", "content": "用户侧虚拟电厂、分布式能源聚合、电力现货市场与辅助服务市场、分布式资源与电网灵活互动调控"}]', 'negotiable', NULL, NULL, '冯威', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 17:54:24+08', '2025-10-30 17:54:24+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (164, 2, 162, '中国科学院深圳先进技术研究院', '基于全息声镊的细胞3D培养技术', 13, '长期以来，在疾病机制研究、测试和选择合适的抗癌药物以及开发新药物方面，科研和临床领域一直对新型体外3D研究模型有着迫切需求。我们首次提出“全息晶格声镊”，将小鼠原代肝细胞组装成特异性点阵图案，模拟肝脏解剖结构。研究表明，声镊模型活细胞比例大于96%，传统3D模型则为86% ~ 93% ；声镊作用组细胞增殖迅速，肝细胞球直径显著增加，可达到与体内生理环境相似的形态；肝细胞蛋白合成代谢、糖代谢、解毒等方面功能亦显著增强。该技术可为长期体外培养原代细胞提供一种创新解决方案和功能强大的工具，其在组织工程、再生医学等领域具有重要的应用价值。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "首次提出“全息晶格声镊”\n为长期体外培养原代细胞提供一种创新解决方案和功能强大的工具"}, {"title": "技术成熟度", "content": "肝细胞球直径显著增加\n可达到与体内生理环境相似的形态"}, {"title": "可应用领域", "content": "组织工程、再生医学等领域"}]', 'negotiable', NULL, NULL, '李飞', NULL, '15915383539', 'fei.li@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:52:51+08', '2025-04-15 11:52:51+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (195, 2, 162, '中国科学院深圳先进技术研究院', '高时空分辨率实时4D成像技术', 9, '动态三维成像（4D成像）是信息领域的研究前沿方向。与传统的RGB-D低分辨率成像系统相比，本单位研发的高时空分辨率实时4D成像系统在成像分辨率、精度和速度方面均有大幅度的提升。本系统采用自主研发的高频结构光编码算法和光栅条纹投射数字器件，可在高清分辨率下（1920*1080像素）实现高达120HZ的三维成像速度，深度成像精度可达0.05毫米，主要技术指标处于国际领先水平。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "成像分辨率： 1920*1080像素；\n三维成像速度： 120HZ ；\n深度成像精度： 0.05毫米"}, {"title": "技术成熟度", "content": "实验室原理样机组件在实验环境中验证。"}, {"title": "项目支持", "content": "广东省重点领域研发计划专项"}, {"title": "可应用领域", "content": "机器人、虚拟现实、数字人、全息视频传输、医疗、工业自动化等领域."}]', 'negotiable', NULL, NULL, '宋展', NULL, '15889608167', 'zhan.song@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:51:18+08', '2025-04-14 17:51:18+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (75, 2, 162, '中国科学院深圳先进技术研究院', '无人艇载地震勘探系统集成与应用', 13, '无人化作业是一个海洋探测技术发展的大趋势，本项目基于自主研制的地震勘探设备，开展无人艇载地震勘探系统集成的关键技术研究。当前项目研究取得的阶段性成果验证了设计方案的可行性，能充分发挥无人水面艇吃水浅、机动性强、安全高效等特点，弥补常规调查船平台在环境复杂、工况恶劣的水域作业的局限性。项目组成员已在大亚湾及华南沿海地区开展了多次海试和项目应用，获取了数百公里的有效数据，最小作业水深2米左右。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高适应性：克服常规勘探在极浅水区和复杂海域作业的难题；\n高自主性：无人艇平台与地震勘探载荷高度集成，实现地震勘探作业自主巡线与远程控制；"}, {"title": "技术成熟度", "content": "多种型号的科研样机，已开展多次海试和项目应用。"}, {"title": "项目支持", "content": "南方海洋科学与工程广东省实验室（珠海）青年人才支持项目"}, {"title": "可应用领域", "content": "海洋地质调查、海洋工程勘察"}]', 'negotiable', NULL, NULL, '郑江龙', NULL, '13235920501', 'jl.zheng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:52:26+08', '2025-10-29 19:52:26+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (200, 2, 162, '中国科学院深圳先进技术研究院', '叠层异质结构超声成像方法与仪器', 14, '航空/天复合材料、芯片器件、动力电池等叠层异质结构力学性能与内部损伤检测对制造工艺优化与服役安全意义重大。团队主要开展工业超声高分辨成像方法与仪器研究，提出了基于新型传感器与超结构的的超声信号激励与接收方法，多因素耦合的声学建模与超声成像聚焦成像方法，复杂结构超声自适应扫描方法，联合多路径超声走时的材料力学性能原位检测方法；并开发了系列样机，实现了技术应用与转化。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "功能：力学性能与微观形貌成像检测\n复杂结构：三维曲面自适应扫描\n弱信号探测：新型超声传感器、超结构\n成像方法：2D、3D高分辨成像\n缺陷类型：分层、空洞、褶皱等\n成像空间分辨率：≤50 μm\n力学测量：杨氏模量、泊松比误差≤5%"}, {"title": "技术成熟度", "content": "7级\n真实环境下的系统演示"}, {"title": "项目支持", "content": "国家自然科学基金\n国家重点研发计划\n广东省自然科学基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "电子封装材料与器件\n航空复合材料结构\n动力电池\n核电压力容器与管道"}]', 'negotiable', NULL, NULL, '郭师峰', NULL, NULL, 'sf.guo@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:40:13+08', '2025-04-14 17:40:13+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (89, 2, 162, '中国科学院深圳先进技术研究院', '高时空分辨率4D成像系统', 9, '基于高频二值条纹相移成像方法，采用自主创新的高效二值时域编码及像素级颗粒度的高并行相位解码和三维重建算法，实现了时域结构光编码技术在扫描及成像速度上的大幅度提升，可在1920*1080分辨率下，实现高达120Hz的三维成像速度，深度成像精度可达0.02毫米，相关科研成果已入选2024年中科院自主研发科学仪器目录。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "基于DLP和工业相机，构建高时空分辨率4D成像系统；\n编码压缩算法、并行解码算法GPU、实时重建算法等；\n标准分辨率200万像素时，成像速度高达120Hz，z 向精度0.02毫米；\n超高分辨率1600万像素时，成像速度可达30Hz；\n低分辨率30万像素时，成像速度可达1000Hz。"}, {"title": "技术成熟度", "content": "完成原理样机研制，并在实验环境中验证。"}, {"title": "项目支持", "content": "国家重点研发计划\n国家自然科学基金\n广东省重点领域研发计划\n深圳市高精度高分辨率4D成像概念验证中心"}, {"title": "可应用领域", "content": "人形机器人、虚拟现实、数字人、全息视频传输、医疗、工业自动化等领域。"}]', 'negotiable', NULL, NULL, '宋展', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 15:53:43+08', '2025-10-29 15:53:43+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (78, 2, 162, '中国科学院深圳先进技术研究院', '全息白光双模成像显微镜', 13, '聚焦生命科学与临床医学微观观测需求，突破传统显微镜透镜结构局限，通过无透镜全息与白光成像双模融合，实现高效精准观测。其操作门槛低、无需复杂校准，兼容多种载玻片与培养皿，搭载智能软件支持自动聚焦与数据分析，轻量化设计节省空间，实验室原理样机已验证功能，满足细胞动态追踪、病理切片观测等不同场景需求', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "无透镜全息成像：摆脱透镜束缚，实现大视野与纳米级分辨率兼具的观测；\n优化白光成像：高色彩还原度明场成像，清晰呈现样品自然形态与色彩；\n双模一键切换：快速切换成像模式，灵活适配不同观测需求。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "可应用领域", "content": "生命科学研究（细胞动态追踪、细胞形态观察）、临床医学（病理学切片观测、临床样本微观检测）、生物医学教学等领域。"}]', 'negotiable', NULL, NULL, '秦文健', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:43:22+08', '2025-10-29 19:43:22+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (149, 2, 162, '中国科学院深圳先进技术研究院', '废旧塑料资源化利用技术', 14, '基于当前废弃塑料带来的”白色污染”和资源错配问题，通过绿色能源驱动的光热-光电一体化新型回收提值方式，实现了废旧聚酯类塑料向乙醇酸、电子级乳酸酯等高值产品的绿色转化。构筑的光热-光电耦合体系为解决塑料废弃物的绿色增值回收提供了新的方向，侨联废旧塑料赋能与绿色制造，为低碳社会的建设提供新的路径。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "新体系：光热-光电一体化；\n高增值：聚酯类塑料废弃物转化为电子级乳酸酯、乙醇酸等；\n普适性：开发规模化催化体系应用实现废旧塑料绿色解聚。"}, {"title": "技术成熟度", "content": "已通过溶剂热解聚法，结合电催化技术实现了聚对苯二甲酸乙二醇酯(PET)以及聚乳酸(PLA)的升级回收，得到乙醇酸和电子级乳酸酯等一系列高附加值精细化学品。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "再生塑料制品、 能源回收、化学原料回收、工业添加剂、液体燃料等领域。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:11:33+08', '2025-04-15 14:11:33+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (211, 2, 162, '中国科学院深圳先进技术研究院', '先进电子封装围堰&填充胶', 14, '围堰&填充胶（Dam&Fill）是应用于封装器件的液体阻隔材料，先由围堰胶（Dam）在元器件周围形成阻隔区域，再用填充胶（Fill）填满区域内空间。与塑封工艺相比，用Dam&Fill胶水进行包封的优势是灵活、方便、设备投入少，容易实现一个模块中不同先进封装方式混合使用，它是一种低成本、高效、灵活的新型封装方式。自主研发的Dam&Fill材料，可应用于PCB板封装、FCBGA Lidless芯片保护提高可靠性, Dam胶具备优异保型能力的胶水，Fill胶粘度低且具备良好流动性且易流平，能够保护元器件免受湿气侵入。产品同时具有优良的低温特性和耐候性，优异的电绝缘性及稳性定，此外，对大多数金属、塑料有较好的粘接力。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "封装可靠性高，量产工艺稳定；自主研发，可定制化程度高"}, {"title": "技术成熟度", "content": "产品已完成中试放大及验证。"}, {"title": "项目支持", "content": "材料院自主部署项目\n深圳市技术攻关项目"}, {"title": "可应用领域", "content": "Dam & Fill 广泛应用于半导体封装，如wire bonding包封、智能卡芯片封装、TP屏贴合、OLED封装等工艺。"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:09:26+08', '2025-04-14 17:09:26+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (91, 2, 162, '中国科学院深圳先进技术研究院', 'AI+医疗器械辅助审评大模型', 9, '承接国家药监局局“人工智能一号工程”及北京市药品监督管理局“揭榜挂帅”任务，作为牵头单位与广东、江苏等多省市药监局协同，构建了围绕医疗器械注册申报的审评大模型，利用真实注册申报材料及专家审评数据，结合审评指导原则、标准、法律法规等领域知识，实现从注册申报材料识别到发补通知书自动生成的全流程审评辅助系统，同时支持对领域相关知识的交互式问答。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "医疗器械知识库：包含所有第二类医疗器械相关的法律法规、标准规范、指导原则。\n智能辅助审评：基于大模型与智能体技术，实现辅助审评系统与审评审批系统进行深度融合。"}, {"title": "技术成熟度", "content": "已在药品监督管理局上线运行"}, {"title": "可应用领域", "content": "多品类医疗器械注册申报"}]', 'negotiable', NULL, NULL, '李烨', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 15:48:54+08', '2025-10-29 15:48:54+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (116, 2, 162, '中国科学院深圳先进技术研究院', '材料创制大模型', 14, '材料创制MARS大模型整合了材料科学领域的多源数据资源，全面覆盖材料从设计、制备到应用的全生命周期信息，基于200万条高质量训练数据，采用"知识注入-能力强化"的两阶段训练策略，可高效实现材料结构可逆设计、物性预测、以及制备方案规划。MARS大模型成功应用于电池材料、气凝胶、有机硅、微胶囊4类共13种材料新产品的开发，成功获批深圳市材料人工智能中小试基地。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "慢思考长推理能力：实现复杂材料问题的深度分析，显著提升推理准确性\n\"性质-结构-合成\"多维预测：实现从使用性能到合成路径的端到端智能推导"}, {"title": "技术成熟度", "content": "MARS-R1已应用于13种新材料的开发\n模型持续升级中"}, {"title": "项目支持", "content": "深圳市材料人工智能中小试基地\nSIAT-WIAT人工智能材料创制联合实验室"}, {"title": "可应用领域", "content": "企业新材料开发智能体\n企业AI专家系统"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '13971313505', 'xf.yu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-05-27 22:02:25+08', '2025-05-27 22:02:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (121, 2, 162, '中国科学院深圳先进技术研究院', '仿生机器鱼在海洋探索和开发上的应用', 9, '团队开发的机器鱼集仿生学、机器人学、自动控制及人工智能技术于一体，由新型中枢神经发生器（CPG）控制，具备较强的抗浪干扰和稳定巡航能力，可实现全航速的减摇控制，因此可用作水下仿生机动平台，根据需求搭载各种专用传感器和光学设备，执行用户指定的水下任务，满足海洋探索和开发的应用需求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "尾鳍采用国际首创的新型可调幅正弦机构来驱动，左右两侧胸鳍均具有扑翼和扭转两个自由度，可实现全航速的减摇控制，抗浪干扰和稳定巡航能力强。"}, {"title": "技术成熟度", "content": "已成功开发了身长约为0.5~5.1米的多款机器鱼样机，这些样机均经过湖试或海试，其中身长5.1米的大型仿生机器鱼已成功通过多次海试，在真实和严苛的海洋环境中验证了其实战能力。"}, {"title": "项目支持", "content": "中国科学院重点部署项目\n广东省自然科学基金项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "可用作水下仿生机动平台，根据需求搭载各种专用传感器和光学设备，执行各项水下任务，在海洋探索和开发上具有巨大潜力。"}]', 'negotiable', NULL, NULL, '左启阳', NULL, '18927467138', 'qy.zuo@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 04:00:21+08', '2025-06-18 04:00:21+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (32, 2, 162, '中国科学院深圳先进技术研究院', '一种多功能双光子显微成像系统', 15, '专利号：ZL202110929297.X', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有的双光子显微成像技术无法同时实现结构成像、细胞调控和钙成像的同步功能，尤其是在神经科学研究中对神经钙信号的观测和光刺激的同时无法进行结构成像。"}, {"title": "技术功效与成熟度", "content": "该专利采用创新的光学与成像技术，能够实现对大脑及神经系统结构的高分辨率观察和功能动态监测，助力脑科学研究及相关疾病诊断。其技术功效包括活体生物组织的结构成像、细胞的光遗传学调控、以及生理活动成像三种功能的融合和同步。目前，该技术在实验室条件下已通过多轮测试验证，技术成果稳定，符合产业化应用条件，成熟度较高。同时，该专利具备较强的拓展性，可适配不同研究场景，具备广泛应用潜力。"}, {"title": "应用场景及市场规模", "content": "该专利主要应用于脑科学和神经生物学领域，适用于大脑组织结构与功能的高分辨影像分析，尤其在脑疾病研究、新药研发、神经科学基础研究等方面具有重要价值。随着神经系统疾病（如阿尔茨海默病、帕金森病等）患者的持续增加，全球脑疾病相关市场规模逐年扩大。未来，精准医疗和脑疾病防治的需求将推动该领域的进一步发展，为该专利的应用市场带来广阔的前景。"}, {"title": "技术手段", "content": "设计了一种多功能双光子显微成像系统，结合点扫描和线扫描成像功能，通过多个激发光源、光电调制器、扩束装置和扫描装置，构成光刺激、点扫描和线扫描成像模块，利用信号控制/采集设备实现不同模块的单独运行或同步运行，能够在介观尺度上对细胞进行光遗传调控和结构、功能信息的量化观测。"}]', 'negotiable', NULL, NULL, '李宝强团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:52:02+08', '2025-12-09 18:52:02+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (57, 2, 162, '中国科学院深圳先进技术研究院', '一种水性丙烯酸树脂复合改性气凝胶隔热防火涂层及其制备方法', 14, '专利号 ：ZL202310242502.4', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本专利涂层兼具优异附着力（达5A级）、耐水性、隔热性与阻燃性，耐火时间显著优于传统涂料。通过“底漆+面漆”双层结构设计及气凝胶封闭改性技术，解决了气凝胶易碎、与树脂相容性差等难题。工艺路线清晰，已通过多组实施例验证，具备中试及产业化条件，技术成熟度高。"}, {"title": "技术问题", "content": "现有水性丙烯酸树脂涂料在高温下燃烧且耐水性差，且硅树脂气凝胶的脆性和孔洞结构易破碎，导致隔热性能下降，难以直接应用于树脂涂料中。"}, {"title": "技术手段", "content": "采用水性环氧树脂作为增粘底漆，并通过溶剂析出法引入P-C-N源协同阻燃剂和低沸点含氟阻燃剂，结合有机硅树脂封闭改性防火气凝胶，形成复合改性气凝胶隔热防火涂层，避免溶剂浸润损害气凝胶结构，提高孔洞结构支撑和阻燃效果。"}, {"title": "应用场景及市场规模", "content": "该技术适用于建筑外墙、钢结构、隧道、轨道交通、船舶及新能源设施等对防火隔热性能要求高的场景。随着国家对建筑防火安全标准提升及“双碳”政策推进，高性能防火涂料市场快速增长，预计2025年国内防火涂料市场规模将超300亿元，气凝胶复合防火涂层作为高端细分领域，年复合增长率超25%。"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:44:13+08', '2025-12-09 17:44:13+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (41, 2, 162, '中国科学院深圳先进技术研究院', '副溶血弧菌噬菌体及包含该噬菌体的杀菌组合物', 16, '专利号：ZL201710954572.7', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "现有技术在控制水产养殖中弧菌病的方法主要依赖化学抗生素，导致抗生素滥用引发耐药菌问题，且单一噬菌体疗法存在宿主菌易产生抗性的缺陷，难以有效控制弧菌病。"}, {"title": "技术手段", "content": "开发了一种专一性裂解弧菌的副溶血弧菌噬菌体VpaSw-2，并结合其他弧菌噬菌体构建杀菌组合物，通过噬菌体鸡尾酒疗法扩大宿主谱范围，降低抗性产生，实现快速高效的弧菌控制。"}, {"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 25%，细分场景需求持续释放。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:19:04+08', '2025-12-09 18:19:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (117, 2, 162, '中国科学院深圳先进技术研究院', '生物合成复合香料', 16, '本项目依托前沿基因编辑技术，成功开发出全球一流的“酵母基香料生物合成平台”。通过精准改造酿酒酵母基因组，定向引入并优化香料合成通路，使菌株在发酵过程中高效积累关键香气物质——香叶醇。与传统化工合成工艺相比，该技术生产的香叶醇发酵液香味更为丰富立体，兼具玫瑰的清甜与柑橘的清新尾调，且无刺激性溶剂残留，完美契合高端香水、家居香薰及个人护理产品对天然感、层次感与安全性的核心需求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "本项目以基因编辑技术改造的酿酒酵母为核心，生产的香叶醇发酵液兼具天然层次感与工业化量产潜力——其香气柔和饱满，完美规避传统化工原料的“单一化工感”，可显著提升香水、香薰等产品的嗅觉差异化体验；同时，依托微生物发酵技术，生产过程无需依赖高污染化学合成或稀缺植物资源，符合全球ESG战略与绿色法规要求，助力企业塑造低碳品牌形象；在成本端，发酵工艺原料利用率高、周期短，量产成本较植物提取更低，且不受气候与产地限制，供应链稳定性强。"}, {"title": "技术成熟度", "content": "团队提供从菌株定制、工艺优化到知识产权支持的全链条服务，合作企业可优先获得独家香型开发权，抢占高端绿色香料市场蓝海。"}, {"title": "可应用领域", "content": "作为基底香料，本产品可广泛应用于香水前调定制、香薰精油复配及洗护产品调香，助力客户打造“天然科技”概念的高附加值新品。"}]', 'negotiable', NULL, NULL, '于涛', NULL, NULL, 'tao.yu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 04:08:14+08', '2025-06-18 04:08:14+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (125, 2, 162, '中国科学院深圳先进技术研究院', 'FCBGA封装用AD胶研发及产业化', 14, 'AD胶是一种用于倒装芯片球形栅格阵列封装的先进封装材料，主要用于固定和连接芯片与基板之间的位置，同时提高热传导，降低封装器件的过热问题。AD胶使用过程中无需底漆，能与多种常见基材，如金属、陶瓷、环氧压层板，形成良好的粘接。', NULL, '02_lab', NULL, NULL, '[{"title": "产品特点", "content": "单组分：使用前无需额外混合操作；\n流动性好：填充后能够自动流平；\n高粘接强度：有效提供异质界面粘接力，高至7.5MPa；\n导热：能够有效将热量导出；\n多功能热固化。"}, {"title": "技术成熟度", "content": "能够实现芯片封装中的异质界面的连接与固定。"}, {"title": "项目支持", "content": "深圳先进电子材料国际创新研究院自主部署项目"}, {"title": "可应用领域", "content": "芯片、器件封装用粘接与导热领域。"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:05:40+08', '2025-04-14 17:05:40+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (141, 2, 162, '中国科学院深圳先进技术研究院', '基于数据驱动的光伏发电协同调度优化', 9, '光伏发电受季节、昼夜、阴晴等复杂环境因素影响，存在着数据精度低、调度并网难、预警效果差、产能波动大四大核心问题。本项目利用人工智能技术，融合能源流、信息流、价值流，重点突破复杂环境下光伏发电中柔性化、智能化调度问题，实现光伏产业中的产能优化以及消纳提升。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "建立多节点协同的多层次、跨时空、自组织智能感知新模型，构建面向复杂环境的设备柔性化、智能化信息接入新体系，\n揭示多模态时变信息驱动、均衡需求与供给的智能调度新机理。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "科技部重点研发计划"}, {"title": "可应用领域", "content": "光伏发电调度优化"}]', 'negotiable', NULL, NULL, '张涌', NULL, NULL, 'zhangyong@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:27:18+08', '2025-04-15 14:27:18+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (20, 2, 162, '中国科学院深圳先进技术研究院', '水凝胶、制备方法及其应用', 13, '专利号：ZL202211380642.X', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有水凝胶材料在柔性储能装置中无法同时实现粘与非粘特性，无法满足柔性化学电池和柔性传感器的需求。"}, {"title": "技术功效与成熟度", "content": "本发明开发一种互穿网络结构体系水凝胶的制备方法，并通过采用不同的化学交联方式，使其实现粘与非粘特性共存的特点，制备柔弹性及特定区域可粘可不粘的水凝胶，用于柔性化学电池及传感器领域。"}, {"title": "应用场景及市场规模", "content": "当前制备的水凝胶材料要么粘性，要么非粘性，同一水凝胶材料实现粘与非粘特性共存很难实现。因此，开发一种粘与非粘特性可控的水凝胶材料，并可同时用于储能和传感装置，有利于将二者器件结合与集成设计。"}, {"title": "技术手段", "content": "通过合成水凝胶前驱体混合物水溶液，包括明胶、聚乙二醇二丙烯酸脂、粘性长链高分子和光引发剂，低温冷凝形成粘性固态水凝胶，并通过紫外光照射形成非粘特性水凝胶，实现粘与非粘特性的共存。"}]', 'negotiable', NULL, NULL, '孙洪岩团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-10 19:39:57+08', '2025-12-10 19:39:57+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (42, 2, 162, '中国科学院深圳先进技术研究院', '杀鲑气单胞菌噬菌体、包含其的杀菌组合物及其应用', 16, '专利号：ZL201710250594.5', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 28%，细分场景需求持续释放。"}, {"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "现有抗生素滥用导致大西洋杀鲑气单胞菌耐药性问题严重，单一噬菌体疗法在应用过程中存在宿主谱范围窄、剂量高和抗性快速发展的缺点，难以有效控制水产养殖中疖疮病及溃肠病。"}, {"title": "技术手段", "content": "开发了一种广谱耐药大西洋杀鲑气单胞菌噬菌体鸡尾酒，通过构建混合噬菌体鸡尾酒，结合特定指标筛选最佳组成，实现对杀鲑气单胞菌、沙门氏杆菌、弧菌及大肠杆菌的高效裂解，弥补单一噬菌体疗法的不足。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:15:19+08', '2025-12-09 18:15:19+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (79, 2, 162, '中国科学院深圳先进技术研究院', '膜式氧合器及其应用', 13, '膜式氧合器是体外生命支持系统的核心部件。国创中心围绕国家重大战略需求，依托深圳市重大科技专项等项目，突破了多项膜式氧合器核心材料及制造工艺的关键技术，实现核心聚甲基戊烯（PMP）膜丝自主量产，性能达到国际水平，建立了从膜丝连续化制备、无损编织到氧合器封装的全流程国产化体系。团队自研膜式氧合器气体交换效率高，氧合性能优异且稳定，可广泛应用于ECMO、二氧化碳清除、器官灌注、生物反应器等领域。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "建立了从膜丝连续化制备、无损编织到氧合器封装的全流程国产化体系"}, {"title": "技术成熟度", "content": "膜式氧合器成品已完成体循设备样机验证。"}, {"title": "项目支持", "content": "深圳市科技重大专项\n深圳市工信局制造业创新中心专项资金扶持计划"}, {"title": "可应用领域", "content": "体外膜肺氧合（ECMO）、体外二氧化碳清除（ECCO2R）、器官灌注保护、生物反应器等"}]', 'negotiable', NULL, NULL, '贾伟', NULL, '18515161107', 'wei.jia@nmed.org.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:41:20+08', '2025-10-29 19:41:20+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (113, 2, 162, '中国科学院深圳先进技术研究院', '多重呼吸道细菌便携化检测平台', 3, '围绕呼吸道细菌感染的精准诊断需求，结合CRISPR/Cas12a与等温扩增技术的优势，开发了一种名为LOC-CRISPR的新型诊断技术。该技术通过“双样本进、十结果出”的检测模式，实现了对SARS-CoV-2及其变异株（BA.1、BA.2和BA.5）、H1N1、H3N2、IVB以及HRSV的精准识别。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "检出限：1000 拷贝/毫升；\n成本：量产后< 100 rmb;\n多重能力：单样本十重或双样本5重；\n检测耗时：60 min\n集成度：片上提取、扩增、识别"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "实验室原理样机组件"}, {"title": "可应用领域", "content": "传染性病原体快速检测"}]', 'negotiable', NULL, NULL, '杨慧', NULL, NULL, 'hui.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 17:24:33+08', '2025-07-16 17:24:33+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (88, 2, 162, '中国科学院深圳先进技术研究院', '海面弱小目标识别', 9, '本项目研发了基于深度学习的港区船只与水下小目标识别算法，通过卷积神经网络和注意力机制实现特征提取与目标检测。算法采用轻量化设计理念，显著降低模型参数量和计算复杂度，确保能够在无人机及嵌入式平台上稳定运行。特别优化了旋转特征对齐与多尺度融合模块，有效提升检测精度。算法已成功部署于无人机平台，实现复杂海域中多类型目标的高效识别与实时监测。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "检测精度：高于95%；\n高鲁棒性：满足三级海况、极端雾天和夜间等低视觉条件下的使用要求；\n实时性与低功耗：算法端侧部署处理速度达28-30FPS,功耗低至8W。"}, {"title": "技术成熟度", "content": "项目已完成实验室原理样机及关键算法组件的研发，并在实验环境中通过验证测试。当前，系统正处于实地验证阶段，相关算法与设备正在港区典型场景中进行性能测试与优化。"}, {"title": "可应用领域", "content": "港口安全监管、海上执法巡查、渔政执法、近海搜救、水下巡检及无人化港区监控等领域。"}, {"title": "项目支持", "content": "科技部重点研发项目\n深圳市基础研究项目"}]', 'negotiable', NULL, NULL, '周翊民', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 16:03:36+08', '2025-10-29 16:03:36+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (158, 2, 162, '中国科学院深圳先进技术研究院', '仅需一滴指尖血的疾病诊断和传染病免疫防护评估技术', 13, '我们开发了一种能快速、精准、定量检测微量样本中传染病免疫防护水平的小型化微流控化学发光免疫分析系统。实现了通过一滴（1-10μL）指尖血及干血斑，精准定量检测其中病原特异性抗体水平、病原中和能力及T细胞免疫响应水平。潜在应用场景包括社区卫生服务、社会面传染病监测和偏远地区疾病诊断。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "便携：全系统总质量约5kg，可单人携带。\n灵敏：探测灵敏度约1 pg/mL级别\n微量：样本仅需一滴指尖血"}, {"title": "技术成熟度", "content": "已搭建实验室原理样机组件，完成了基于临床样本的性能测试。"}, {"title": "项目支持", "content": "深圳市基础研究项目\n深圳先进院自主部署项目"}, {"title": "可应用领域", "content": "社区卫生服务、传染病控制和偏远地区疾病诊断。\n可用于野战卫生服务。"}]', 'negotiable', NULL, NULL, '谭骁天', NULL, '15810328603', 'xt.tan@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:41:08+08', '2025-04-15 13:41:08+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (10, 2, 162, '中国科学院深圳先进技术研究院', 'MR LIVE imaging: whole-body dynamic imaging', 13, 'We have co-developed a dynamic magnetic resonance imaging technology, MR LIVE Imaging, in collaboration with Shanghai United Imaging Healthcare. This innovation enables MR structural imaging to evolve from the traditional "static photography" paradigm to a "dynamic videography" mode, delivering a more realistic representation of human physiological states. It is applicable to all regions of the human body, particularly motion-sensitive areas such as the gastrointestinal tract and joints. Furthermore, it supports integrated motion function assessment to enable in-depth analysis of organ functional status.', NULL, '02_lab', NULL, NULL, '[{"title": "Technical Innovations", "content": "Fast: Multi-frame imaging within static scan time.\nHigh resolution: Superior spatial resolution to static sequences."}, {"title": "Technology Readiness", "content": "Algorithm prototype development has been completed, and performance validation has been conducted on healthy volunteers. Large-scale clinical sample testing is currently in progress."}, {"title": "Project Support", "content": "Key Program of the National Natural Science Foundation of China (NSFC)"}, {"title": "Application Fields", "content": "Disease diagnosis and organ functional analysis."}]', 'negotiable', NULL, NULL, 'Dr. Liang Dong', NULL, NULL, 'dong.liang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2026-05-18 19:13:47+08', '2026-05-18 19:13:47+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (122, 2, 162, '中国科学院深圳先进技术研究院', '钙钛矿基多结光伏', 14, '为实现钙钛矿效率和稳定性的双重突破，开发了系列新型钙钛矿基多结光伏器件结构。其中，基于光稳定的全钙钛矿四结太阳能电池，效率和稳定性均超过传统的钙钛矿两结叠层器件。为满足空天光伏、建筑光伏一体化应用等需求，开发了柔性钙钛矿基多结太阳能电池，实现了柔性器件效率和稳定性的突破。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高光电转换效率：刚性大于30%；\n良好的稳定性：1000小时持续光照下，保持初始效率的80%以上。"}, {"title": "技术成熟度", "content": "实验室器件阶段，正申请相关专利。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市基础研究重点项目"}, {"title": "可应用领域", "content": "建筑光伏一体化、空天光伏等。"}]', 'negotiable', NULL, NULL, '王在伟', NULL, '18825279335', 'zw.wang3@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-06-18 03:58:46+08', '2025-06-18 03:58:46+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (15, 2, 162, '中国科学院深圳先进技术研究院', '全自动旋转式菌落挑取系统专利组合', 9, '该组合包含如下专利：
自动菌落挑选仪及挑选方法          菌落挑取仪     
菌落自动挑选装置                           自动菌落挑选仪
自动菌落挑选仪                                精确定位自动回复装置及细菌菌落挑取仪', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "克隆挑取广泛应用于农业、医药、生物、轻化工等行业，与人工相比，克隆挑取仪在挑取效率和精度上均得到了显著提升。目前该类设备主要依靠进口，价格昂贵，开发具有自主知识产权的菌落挑取设备将有巨大的应用前景。"}, {"title": "技术问题", "content": "菌落挑取过程中，挑取效率低、挑针消毒不彻底、定位调节、菌落识别等问题。"}, {"title": "技术手段", "content": "创新结构设计，采用多针转盘式结构以及挑针自动复位机构，提高工作效率，实现挑针的清洗消毒和位置调节等。结合视觉优化算法，提高菌落识别和定位精度。"}, {"title": "技术功效与成熟度", "content": "基于相关技术研制了实验室样机。克隆挑取仪样机已多次迭代更新，提高性能，正进行应用推广。"}]', 'negotiable', NULL, NULL, '何凯、朱伟等', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-23 10:48:34+08', '2025-12-23 10:48:34+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (203, 2, 162, '中国科学院深圳先进技术研究院', '大型亚毫米波射电望远镜校准促动系统', 9, '针对大型亚毫米波射电望远镜面板微米级形变误差控制要求，研发高承载、高精度、大行程、小体积、重量轻的促动机构及通讯、控制网络系统。通过布置在望远镜背架与面板之间的多套促动器联合工作，对望远镜面板重力下的微小变形进行修正，提升望远镜的有效口径。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "1）定位精度优于 10微米\n2）位移分辨率优于1微米\n3）行程-5mm-5mm\n4）轴向负载>=120N, 侧向负载>=40N\n5）尺寸 25x25x100mm3\n6）重量小于500g\n7）温度范围-30---+30 ℃。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "中国科学院青年创新促进会"}, {"title": "可应用领域", "content": "射电望远镜、雷达面板调整，精密加工等领域。"}]', 'negotiable', NULL, NULL, '孙天夫', NULL, '13828858818', 'tf.sun@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:35:07+08', '2025-04-14 17:35:07+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (223, 2, 162, '中国科学院深圳先进技术研究院', '新型治疗自身免疫性疾病药物Neuritin融合蛋白的开发和应用', 3, '调节性T细胞（Treg）是一类T细胞免疫抑制亚群，在维持免疫系统的稳态发挥重要的作用。潘璠教授团队研究首次发现，Neuritin是一种关键的免疫耐受分子，可以促进Treg的分化和增强其功能维持体内免疫平衡。潘璠教授团队已成功制备了一种新型Neuritin融合蛋白用于治疗自身免疫性疾病。该融合蛋白通过促进Treg细胞的活化和增殖，对小鼠的结直肠炎、银屑病和类风湿性关节炎模型等自身免疫性疾病中均有显著疗效。该融合蛋白具有明确的靶向性、低毒性的优势，是一种原创性的新型融合蛋白药物，为自身免疫性疾病的提供新的治疗策略与方向。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "Neuritin作为一种新发现的免疫抑制分子，在治疗自身免疫性疾病的过程中不是单一的抑制炎症反应的发生而是通过调节机体内免疫平衡，恢复免疫系统的稳态。"}, {"title": "技术成熟度", "content": "在实验室已纯化出Neuritin融合蛋白，并验证在结直肠炎，银屑病，类风湿性关节炎等小鼠自身免疫性疾病模型中存在良好治疗效果。"}, {"title": "项目支持", "content": "深圳市医学研究专项"}, {"title": "可应用领域", "content": "调节机体免疫平衡，治疗自身免疫性疾病。"}]', 'negotiable', NULL, NULL, '潘璠', NULL, '13530288076', 'fan.pan@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 15:54:47+08', '2025-04-14 15:54:47+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (81, 2, 162, '中国科学院深圳先进技术研究院', '刚柔耦合自适应抓持器', 13, '刚柔耦合自适应抓持器为非结构化环境作业而设计，在现代农业场景中验证了其综合性能。该抓持器有效兼顾了抓取的柔顺性、输出力与操作安全性；既能实现稳定可靠的抓持，又能有效保护作业对象不受损伤。现场测试表明，该产品对不同品种苹果均能实现高效、无损采摘，展现出优异的适应性。该技术还可拓展至物流分拣、家庭服务等多个领域，为智能机器人提供了可靠的末端执行解决方案。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "1.刚柔耦合创新设计：\n在提供高抓握力与旋拧力的同时，保护被抓取目标与自身不受破坏。\n2. 自适应特性：\n可抓取柔软、刚性、尖锐物体等。在抓取过程中具有极高的抗扰性或对于异物的兼容性。\n3. 尺寸可定制\n4. 模块化转配"}, {"title": "技术成熟度", "content": "原理样机完成实验室测试、功能测试、疲劳测试\n在实地果园中，进行了多轮功能性测试，证明了不同条件下的采摘效果、抗扰效果及保护效果良好。"}, {"title": "可应用领域", "content": "工业机器人末端抓持器、农业水果采摘等领域。"}]', 'negotiable', NULL, NULL, '杨扬', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:33:48+08', '2025-10-29 19:33:48+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (66, 2, 162, '中国科学院深圳先进技术研究院', '钙钛矿基多结光伏', 14, '为了实现钙钛矿效率和稳定性的双重突破，我们开发了系列新型钙钛矿基多结光伏器件结构。其中，基于光稳定的全钙钛矿四结太阳能电池，效率和稳定性均超过传统的钙钛矿两结叠层器件。为了满足空天光伏、建筑光伏一体化应用等，开发了柔性钙钛矿基多结太阳能电池，实现了柔性器件效率和稳定性的突破。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高光电转换效率：刚性大于30%；\n良好的稳定性：1000小时持续光照下，保持初始效率的80%以上；"}, {"title": "技术成熟度", "content": "实验室器件阶段，申请相关专利。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市基础研究重点项目"}, {"title": "可应用领域", "content": "建筑光伏一体化、物联网光伏、空天光伏等。"}]', 'negotiable', NULL, NULL, '王在伟', NULL, NULL, 'zw.wang3@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 18:01:35+08', '2025-10-30 18:01:35+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (62, 2, 162, '中国科学院深圳先进技术研究院', '高选择性兼高通量膜材料与器件', 14, '选择性传质膜材料（如：纳滤膜、反渗透膜、离子交换膜等）是关键的基础化工装备，是影响国民经济与社会民生的关键材料，功能不可替代。深圳先进技术研究院低维功能膜团队聚焦离子交换膜、纳滤膜的研究，原创二维垂直均孔纳米通道膜技术，开发出系列高性能膜材料，并应用于液流电池、燃料电池、煤工业水处理、家用水处理等领域。', NULL, '02_lab', NULL, NULL, '[{"title": "技术成熟度", "content": "膜样片制备、小试制造及膜组件小试设计阶段。"}, {"title": "技术创新点", "content": "高通量：水通量高于5倍商用反渗透膜，高于3倍商用纳滤膜；\n高选择性\n低成本：自研低成本制膜产线，满足家用及工业净水膜、能源膜使用需求；\n一体化：原理性突破膜传质体系，系统化解决多场景下分离需求。"}, {"title": "可应用领域", "content": "高通量家用净水及设备；煤炭、化工污水净水产线、海水淡化产线、海水制氢产线、盐湖提锂、液流电池。"}, {"title": "项目支持", "content": "国家重点研发计划-颠覆性技术专项\n国家自然科学基金面上项目、青年项目\n深圳市科技重大专项(可持续发展专项)\n深圳先进技术研究院攻坚（重点项目）\n广东省自然科学基金面上项目"}]', 'negotiable', NULL, NULL, '中国科学院深圳先进技术研究院低维功能膜团队', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 18:16:31+08', '2025-10-30 18:16:31+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (177, 2, 162, '中国科学院深圳先进技术研究院', '新型无机二维液晶及其智能变色应用', 14, '围绕低碳生产及应用，结合无机低维材料体系优势，从新材料制备及物性提升方面入手，实现了多款环保低功耗无机二维液晶的可控合成及其新奇应用开发。新型二维无机液晶响应灵敏度高且具有极大的电光克尔系数（高出传统液晶数个量级），可在超低场驱动下展现丰富生动的干涉色彩，突破了传统二色性染料液晶仅能实现黑态、亮态及灰阶状态的调节。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低能耗：低至 6 V/mm 的电场；\n低成本与无毒性：适合大面积应用；\n高适应性：双重热响应点确保白天采光、正午遮光及夜晚隐私保护；\n高灵活性：热响应临界点可根据当地气候和纬度进行独立调控（±5℃）。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "光学显示、宽波段光通信、透射式深紫外光调制、光记忆存储、节能建筑玻璃幕墙、汽车全景天窗、智能调光玻璃等光学应用。"}]', 'negotiable', NULL, NULL, '丁宝福', NULL, '18818538834', 'bf.ding@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:51:12+08', '2025-04-15 10:51:12+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (216, 2, 162, '中国科学院深圳先进技术研究院', '新型锂电池用负极粘接剂', 14, '粘接剂在保持电极结构稳定，促进锂离子传导，提高锂电池能量密度与循环寿命等方面扮演重要角色。从高分子结构设计和聚合工艺调控两方面入手开发出一系列富含极性官能团且具有高分子量的多元共聚水溶性粘结剂，产品具有优异粘接性能，可有效抑制电芯膨胀，提高锂电池循环寿命。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高分子量且分子量分布窄，具有优异的粘接性能；强分子间作用力，电解液溶胀低（＜10wt%），可有效抑制电芯膨胀；富含极性官能团促进锂离子传导，降低锂电池内阻；良好的结构稳定性，高循环寿命。"}, {"title": "技术成熟度", "content": "完成实验室样品合成与软包电芯评测"}, {"title": "可应用领域", "content": "石墨负极、硅基负极等负极材料体系粘接"}]', 'negotiable', NULL, NULL, '边式', NULL, NULL, 'shi.bian@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:02:20+08', '2025-04-14 17:02:20+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (172, 2, 162, '中国科学院深圳先进技术研究院', '世界首台“摄像”磁共振', 13, '首创LIVE Imaging技术，实现从“静态拍照”到“动态摄像”的根本性跨越，开启磁共振全身LIVE摄像时代。与龙头企业联影医疗合作研发世界首台摄像磁共振系统uMR UItra已获NMPA、美国FDA及欧洲CE三大认证，全球上市。
Pioneering LIVE Imaging technology achieves a fundamental leap from "static photography" to "dynamic videography," inaugurating the era of whole-body LIVE MRI. Developed in collaboration with industry leader United Imaging Healthcare, the world''s first videographic MRI system, uMR Ultra, has obtained NMPA, U.S. FDA, and European CE certifications and is now commercially available worldwide.', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点Technical Innovations", "content": "快速：静态扫描时间内可获得多帧图像。\n高分辨：可实现比静态扫描更高的空间分辨率\nFast: Multi-frame imaging within static scan time.\nHigh resolution: Superior spatial resolution to static sequences."}, {"title": "项目支持Project Support", "content": "国家自然科学基金重点项目\nKey Program of the National Natural Science Foundation of China"}, {"title": "可应用领域Application Fields", "content": "疾病诊断、器官功能分析\nDisease diagnosis and organ functional analysis"}, {"title": "产业合作 Industrial Cooperation", "content": "上海联影医疗科技股份有限公司\n电话： +86 (21) 67076888  \n传真： +86 (21) 67076889\nShanghai United Imaging Healthcare Co., Ltd.\nTel:  +86 (21) 67076888  \nFix:  +86 (21) 67076889"}]', 'negotiable', NULL, NULL, '梁栋Dong Liang', NULL, NULL, 'dong.liang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:59:08+08', '2025-04-15 10:59:08+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (18, 2, 162, '中国科学院深圳先进技术研究院', '高性能硫化铋基热电材料及其全链条制备技术与专用装备专利组合', 14, '该组合包含如下专利：
一种n型碲化铋热电材料及其制备方法                                   一种碲化铋热电材料及其制备方法
一种碲化铋基热电材料的制备方法与挤压模具                    一种碲化铋基热电材料的制备方法与挤压模具
一种多功能晶体生长装置                                                            一种p型镁银锑热电材料及其制备方法和应用
晶体定向方法、装置及晶体加工方法', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "应用于5G光通讯、数据中心光模块、医疗PCR、车载冰箱、车载芯片、电池热管理、红外探测等众多小型化、无振动、高精度控温等场景，市场年复增长率>20%，预计到2030年总体规模达>500亿。"}, {"title": "技术问题", "content": "分级碲化铋材料核心技术均已攻克，能够提供定制产品，新型低温热电材料量产技术的放量能力与稳定性有待提升"}, {"title": "技术手段", "content": "采用诱导剂促进高纯原料大批量合成，进行设备升级，并利用液相辅助生长，提升性能稳定性。"}, {"title": "技术功效与成熟度", "content": "提供宽温域高性能分级热电材料，完成材料中试工艺，技术成熟度达到7-9级"}]', 'negotiable', NULL, NULL, '热电智能热管理团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-23 10:22:32+08', '2025-12-23 10:22:32+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (127, 2, 162, '中国科学院深圳先进技术研究院', '高性能、低成本质子交换膜电解槽阳极催化剂的研发', 14, '针对可再生能源驱动的电解水制氢对低能耗、宽功率波动的需求，深度开发低成本质子交换膜(PEM) 电解槽阳极催化剂层的技术创新，提供了在酸性环境中具有长期稳定性的高效催化剂。通过构建具有动态电子转移的自适应活性位点、晶格水辅助的改性氧交换机制、贵金属-非贵金属界面电子调控、阴离子配位调制等策略，成功解决了阳极催化剂活性和稳定性之间的平衡问题，实现了PEM水电解性能的大幅提升。器件测试性能已达到中国氢能专项的项目指标要求。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高活性：研发的催化剂在三电极测试中过电势较低(186 mV@10 mA cm-2)，远超商业IrO2；\n高稳定性：稳定性达到创纪录的1.9 × 107 noxygen nIr-1；\n作用机制清晰：多种高端表征技术明确OER反应机制；\n工业实用性：在0.3 mgIr cm-2低Ir负载量下，PEM电解槽在2.0 A cm-2电流密度下实现1.76 V的电池电压(达到中国氢能专项的项目指标要求2.0 A cm-2, 1.8 V)。"}, {"title": "技术成熟度", "content": "低于1.86 V时PEM电解槽获得3.0 A cm-2的电流密度，接近美国能源部2030年关于PEM电解槽的指标要求。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "与风能、太阳能等可再生发电技术结合来实现“绿氢”制备。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:16:02+08', '2025-04-15 14:16:02+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (58, 2, 162, '中国科学院深圳先进技术研究院', '一种超疏水超疏油改性液及其制备方法、包含其的涂层', 14, '专利号：ZL202310283801.2', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有超疏水材料在户外应用中耐候性差，容易因油污、机械摩擦和风沙侵蚀丧失超疏水性，且耐冲刷性不足，限制了其大规模应用。"}, {"title": "技术手段", "content": "采用超疏水超疏油改性液，包括微纳米粉体、纳米纤维、疏水改性剂、疏油改性剂、溶剂、碱溶液和柔性树脂，通过特定的混合和加热反应步骤制备涂层，形成具有粒径梯度的微观粗糙结构，提高涂层的耐磨、耐冲刷和户外耐候性。"}, {"title": "技术功效与成熟度", "content": "本专利技术制备的涂层兼具超疏水（水接触角>160°，滚动角<2°）与超疏油（泵油接触角>150°，滚动角<4°）性能，并具备优异的耐磨性（1000次摩擦不失效）、耐冲刷性及户外3年耐老化能力。工艺流程清晰，原料常见，已通过多组实施例验证，技术成熟度高，具备产业化条件。"}, {"title": "应用场景及市场规模", "content": "该技术适用于户外高耐候性防护涂层领域，如建筑外墙、桥梁、船舶、光伏面板、输电设备、汽车及轨道交通等。随着绿色建材与智能表面材料需求增长，全球超疏水涂层市场规模预计2025年将超百亿美元，中国年增速超20%。"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-11-27 14:14:04+08', '2025-11-27 14:14:04+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (104, 2, 162, '中国科学院深圳先进技术研究院', '2D/3D柔性传感技术系统及解决方案', 3, '2D/3D 柔性传感技术系统及解决方案是融合先进工艺技术与智能算法的创新成果。该系统以柔性可延展材料为基底，通过微纳加工技术集成压阻、电容等传感单元，可精准捕捉 2D 平面及 3D 空间内的压力、应变、温度等物理信号。2D 技术适用于可穿戴设备表面压力监测、电子皮肤触觉感知；3D 技术则突破维度限制，可用人体自然腔道介入医疗器械，并在机器人灵巧操作、医疗康复肢体运动捕捉、虚拟现实交互等领域实现多维信息采集。搭配自主研发的数据处理算法与云端平台，能提供从硬件部署、信号解析到智能决策的全链条解决方案，为智能制造、医疗健康、人机交互等行业带来高效、精准的感知革新。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "自主研发的3D曝光系统\n自主研发柔弹性传感工艺。"}, {"title": "项目支持", "content": "广州省“仿生触觉海外青年”创新创业项目"}, {"title": "技术成熟度", "content": "部分产品样机，部分完成量产"}, {"title": "可应用领域", "content": "消费电子，工业制造，人形机器人，医疗可穿戴"}]', 'negotiable', NULL, NULL, '孙滨', NULL, NULL, 'bin.sun@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 18:08:22+08', '2025-07-16 18:08:22+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (126, 2, 162, '中国科学院深圳先进技术研究院', '高性能阴离子交换膜电解水关键材料的研发', 14, '以绿氢的低成本制备为导向，基于阴离子交换膜(AEM)电解水的技术优势，开发出高性能低维非贵金属催化材料、高效有序膜电极结构及膜电极原位表征技术，实现了高性能、低成本、长寿命AEM电解池的研发应用。新型高性能AEM电解池具有高电流密度、高产品纯度、快速响应速率等优势，可在纯水工况下利用非贵金属催化剂高效驱动电解水制绿氢。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "非贵金属材料催化剂；\n高工作电流密度 > 1 A/cm2；\n纯水工况，绿氢纯度高；\n宽工况、宽功率工作范围，适应风、光等波动性可再生能源。"}, {"title": "技术成熟度", "content": "催化剂实现规模化制备；\n原型机组装成功，可在实验室模拟工业应用，工况下进行性能测试。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "电解水绿氢制备；\n间歇性可再生能源转换与存储。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:17:17+08', '2025-04-15 14:17:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (155, 2, 162, '中国科学院深圳先进技术研究院', '跨尺度多模态超声介入成像系统', 13, '针对胰腺癌发病位置特殊，缺乏有效抵近探查设备的临床痛点，在国家重大仪器研制项目和中国科学院仪器研制项目的支持下，创新性开发跨尺度多模态超声介入成像系统，实现了高频超声成像、高分辨率OCT成像和特异性荧光成像的有效融合，提供了一种多层次观测消化道肿瘤演进进程以及可视化分析微血供形态与代谢信息的新方法', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高频超声40MHz，81.5%带宽\n光学、荧光成像分辨率小于10μm\nOCT-荧光一体化光学球透镜的三模态成像微导管（直径＜0.6mm）\n三模态成像帧率 34 帧/s"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。\n部分技术指标获第三方检测认定。"}, {"title": "项目支持", "content": "国家自然科学基金（优秀结题）\n中国科学院科研仪器研制专项\n深圳市科技研发支持"}, {"title": "可应用领域", "content": "微创介入手术，癌症的精准诊断，疾病早筛，生物医学成像。"}]', 'negotiable', NULL, NULL, '马腾', NULL, NULL, 'teng.ma@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:46:16+08', '2025-04-15 13:46:16+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (63, 2, 162, '中国科学院深圳先进技术研究院', '复合场涂布技术及电致/热致变色玻璃', 14, '围绕低碳生产及应用，基于低能耗复合场原理开发了薄膜涂布的全新技术。解决了功能薄膜的宏量放大、均一涂布、多界面适配、材料普适的传统难题，实现纳米无机薄膜的大面积均一制备和电致变色玻璃应用。开发双温度热响应变色玻璃，具有低成本、易制备、光调节能力强和循环稳定性高等优势，可根据室外温度自动调节透光率，为建筑节能提供了全新解决方案。', NULL, '02_lab', NULL, NULL, '[{"title": "技术成熟度", "content": "已实现实验室300*300mm电致变色玻璃、热致变色器件的可控制备。"}, {"title": "技术创新点", "content": "低能耗：低至 2v的电压驱动；\n低成本：适合大面积应用；\n可控性：通过电场及刮刀的调节可实现微区涂布、渐变涂布、多层涂布等丰富功能器件制备；"}, {"title": "可应用领域", "content": "节能建筑玻璃幕墙、汽车全景天窗、智能调光玻璃、光学显示等光学应用。"}]', 'negotiable', NULL, NULL, '中国科学院深圳先进技术研究院低维功能膜团队', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 18:16:31+08', '2025-10-30 18:16:31+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (27, 2, 162, '中国科学院深圳先进技术研究院', '一种复合结构微瓶透镜的制备方法', 13, '专利号：ZL202210356452.8', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "本发明利用三维调整架的精密机械操控方式，实现依托于微光纤形成的复合结构微瓶透镜的可控制备。目前技术成熟度为实验室概念验证阶段。"}, {"title": "技术问题", "content": "现有复合结构微瓶透镜的制备方法存在光学胶贴剂使用条件严格、微液滴大小和数量难以控制的问题，导致形成的微瓶谐振腔个数和尺寸无法掌控。"}, {"title": "技术手段", "content": "采用两段半锥形微光纤，通过锥形过渡区滑落聚合物微液体，形成液体覆盖膜，并利用精密机械控制法在微光纤锥腰处转移液滴，形成可控的复合结构微瓶透镜，并通过光或热固化使其固化。"}, {"title": "应用场景及市场规模", "content": "光聚焦、光学成像、信号增强等领域，市场规模未知"}]', 'negotiable', NULL, NULL, '杨慧团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:59:25+08', '2025-12-09 18:59:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (146, 2, 162, '中国科学院深圳先进技术研究院', 'CMOS兼容的近红外宽波段探测器及成像芯片', 14, '近红外探测与成像技术可以获得媲美可见光成像的分辨能力，又兼具有红外成像的微光夜视效果及较强的穿透雾霾、水汽能力，是国土安全防御，新一代夜视单兵装备等核心器件，同时在机器视觉、个人智能终端中的需求越来强烈。我们开发了一种新型优良窄带隙p型半导体材料，实现了CMOS晶圆上硅基单片异质集成、低成本、高分辨率近红外阵列成像芯片。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高分辨率：640*512；\n宽谱响应：300-1600 nm；\n暗电流：≤500 nA/cm2\n峰值量子效率≥60%@1310 nm\n响应时间：~3 ns\n硅基单片异质集成"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "国防安防、个人智能终端、生物医学、智能驾驶、光通信、具身智能等应用。"}]', 'negotiable', NULL, NULL, '杨春雷', NULL, NULL, 'cl.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:18:38+08', '2025-04-15 14:18:38+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (160, 2, 162, '中国科学院深圳先进技术研究院', '基于微流控的单细胞柔性流式分选', 13, '我们开发了一种基于微流控芯片技术的单细胞分选系统，该系统有如下几个特性：1、柔性分选，所分选出来的细胞无损伤，可以再培养；2、抛弃型低成本芯片，分选完全在芯片上发生，仪器无需维护；3、多通道、多标记分选，判据灵活可选；该技术已经有多项专利，目前合作方已经着手进行产业化布局。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "便携：全系统总质量约10kg，鞋盒大小，可单人携带；\n柔性：细胞保持活性，可再培养；\n微量：样本仅需几万枚细胞，比传统少两个数量级"}, {"title": "技术成熟度", "content": "已搭建两代实验室原理样机，完成了基于实验室细胞系样本的性能测试。"}, {"title": "项目支持", "content": "基于微流控技术的细胞分选仪器及配套芯片技术开发项目（横向项目）"}, {"title": "可应用领域", "content": "单细胞分析、分选；\n稀有细胞富集。"}]', 'negotiable', NULL, NULL, '门涌帆', NULL, NULL, 'yf.men@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:37:59+08', '2025-04-15 13:37:59+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (87, 2, 162, '中国科学院深圳先进技术研究院', '海洋潜水外骨骼系统', 9, '海洋作业如石油平台维护、管道安装与检查、水下救援和船体清洁等需要潜水员在水下长时间工作。长时间的潜水活动会导致潜水员的代谢成本大幅增加，增加减压病等疾病风险。团队依据潜水员水下多模态动作特征，研制了系列潜水助力外骨骼系统，能够协助潜水员完成包括交替打腿、蛙泳腿以及水下行走三类腿部动作，以及长时抬臂动作，大幅降低水下耗气速率达29.77%，为水下作业效率与安全性带来提升。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "新型套索传动驱动器：支持关节双向助力，不阻碍正常动作；\n水下动态密封技术：支持最大水深150m防水，满足主要任务深度潜水需求；\n人体意图感知方法：支持交替打腿、蛙泳腿和水下行走助力，精准预测助力动作相位。"}, {"title": "技术成熟度", "content": "7级-环境级：在实际环境中的系统样机试验"}, {"title": "项目支持", "content": "国家自然科学基金重点项目\n科技部重点研发项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "海洋工程（石油、风电）\n水库船坞服务（切割、清理）\n救援组织（潜水协会、搜救中心）"}]', 'negotiable', NULL, NULL, '陈春杰', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 16:05:58+08', '2025-10-29 16:05:58+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (86, 2, 162, '中国科学院深圳先进技术研究院', '水下机器人', 9, '本团队结合路径规划领域前沿研究成果，经过适应于水下环境的移植与优化，开发了水下机器人自主避障与路径规划技术。提出了一种基于水下场景先验的水下图像增强卷积神经网络模型。所提出的模型不估计水下成像模型的参数，而是直接重建清晰的潜在水下图像，利用水下场景合成水下图像训练数据。此外，基于轻量级的网络结构和有效的训练数据，模型可以很容易地扩展到水下视频，进行逐帧增强。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "负载能力强：可搭载水下作业机械手进行动作执行、耐压深度可达350m；\n预留软硬件接口：兼容主流传感器；\n驱动：螺旋驱动、可360o无全向移动；\n防水设计：整体开放、局部密封；\n本体配置：轻量化设计、模块化设计、抗冲击性和耐腐蚀性；"}, {"title": "可应用领域", "content": "海水检测、\n内陆咸水湖及近海巡检、\n淡水下坝体检测；"}, {"title": "技术成熟度", "content": "产品级"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发项目\n深圳市基础研究项目"}]', 'negotiable', NULL, NULL, '周翊民', NULL, NULL, 'ym.zhou@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 16:08:34+08', '2025-10-29 16:08:34+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (187, 2, 162, '中国科学院深圳先进技术研究院', '新型超薄酶层电化学传感器及其应用', 3, '酶基电化学电极是当前临床与基础生命科学研究中针对电化学惰性物质（如葡萄糖、乳酸、谷氨酸等）进行检测分析的重要工具。围绕传统酶基电化学电极制作周期长、成本高、空间分辨率受限、响应慢等问题，利用创新的快速电控原位镀膜工艺，仅需2~3分钟即可实现纳米级厚度的酶液成膜，用酶成本仅为传统工艺的1/10~1/5。通过该方法制得的新型酶基电化学电极具有空间分辨率高、响应快、成本低且易于量产的特点，适合在体与离体的组织与细胞层级的实时检测应用。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低成本：用酶量仅为传统的1/10~1/5。\n制作周期短：操作简易、时间短，易于大规模量产。\n超薄酶层：厚度在纳米至亚微米级别可控，不影响电化学电极的空间分辨率、对底物的响应迅速。"}, {"title": "技术成熟度", "content": "已在多种实验室记录环境下完成应用测试。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省基础与应用基础研究基金自然科学基金"}, {"title": "可应用领域", "content": "在临床与基础研究中的，在体与离体条件下的电化学惰性物质的实时检测。"}]', 'negotiable', NULL, NULL, '申雪峰', NULL, '15120047628', 'xf.shen@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:22:39+08', '2025-04-15 10:22:39+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (71, 2, 162, '中国科学院深圳先进技术研究院', '主从式血管介入机器人', 13, '围绕“辐射、疲劳、不直观”等临床痛点，基于持续性数字剪影血管造影（DSA）、血管介入内成像、脏器血管的导管/导丝/球囊介入等技术和材料，研制主从式血管介入机器人，开发内容包括：医学影像人工智能计算与手术规划、混合智能驱动与导航、感驱控一体化、诊疗一体化等技术。已完成13例动物实验，转让核心技术专利4项。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "血管拓扑结构自动分析；介入路径视觉导航；分布式实时系统建模；介入可视化导航"}, {"title": "项目支持", "content": "国家863科技计划\n国家自然科学基金面上\n深圳市工程实验室、重点项目等"}, {"title": "产业合作", "content": "2021年，临影医疗科技（深圳）有限公司\n2025年，与珠海市微创介入医学中心共建\n电话：0755-86959839   \n邮箱：sj.zhou@siat.ac.cn"}, {"title": "可应用领域", "content": "心脑血管介入临床\n肿瘤介入治疗"}]', 'negotiable', NULL, NULL, '周寿军', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 19:54:22+08', '2025-10-29 19:54:22+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (17, 2, 162, '中国科学院深圳先进技术研究院', '高性能热电制冷器件界面封装与异质集成技术专利组合', 14, '该组合包含如下专利：
一种电解液和碲化铋制冷元件低接触电阻镍基合金阻挡层的制备方法
一种碲化铋基热电元件、碲化铋基热电器件及其制备方法
一种异质半导体材料集成多级制冷器件', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "应用于5G光通讯、数据中心光模块、医疗PCR、车载冰箱、车载芯片、电池热管理、红外探测等众多小型化、无振动、高精度控温等场景，市场年复增长率>20%，预计到2030年总体规模达>500亿。"}, {"title": "技术问题", "content": "下一代异质器件材料膨胀系数存在差异性，降低多级制冷器件服役可靠性，多级器件涉及到多次焊接工艺，需要兼顾异质材料以及焊接工艺的兼容性和可靠性。"}, {"title": "技术手段", "content": "拟开发定制化设计软件，并采用自动化三维垂直封装技术以及梯度焊接工艺，提高工艺可靠性。"}, {"title": "技术功效与成熟度", "content": "热电制冷控温技术能够提供便携式、无振动、高精度，及宽温域（150-450K）的高效热管理方案，团队已完成了器件小批量生产，技术成熟度达到8-9级。"}]', 'negotiable', NULL, NULL, '热电智能热管理团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-23 10:38:19+08', '2025-12-23 10:38:19+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (170, 2, 162, '中国科学院深圳先进技术研究院', '结构色智能标签及其冷链可视化监测应用', 13, '针对疫苗、生物医药和离体器官在存储和配送过程中对冷链监测的迫切需求，研发了基于自毁型结构色液体的新型智能标签，可通过标签的颜色变化实时监测、反馈异常温度暴露历史，并且实现了宽的温度监测范围和灵活可调的变色时间，有望用于医药、食品等冷链的可视化监测。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "不可逆颜色变化：避免结果篡改；\n变色时间：从数分钟到数天；\n温度监测范围：-70 ~ 37 ℃；\n可设计为二维码，支持手机扫码查询。"}, {"title": "技术成熟度", "content": "实验原型样品在模拟使用环境下验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n国家重点研发计划\n广东省项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "疫苗、生物医药、离体器官、食品的冷链运输等应用领域。"}]', 'negotiable', NULL, NULL, '杜学敏', NULL, NULL, 'xm.du@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:24:19+08', '2025-04-15 11:24:19+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (90, 2, 162, '中国科学院深圳先进技术研究院', 'AR经颅超声智能实时导航系统', 9, 'AI赋能医疗，科技革新诊疗：团队自主研发的"AR经颅超声智能导航系统"，攻克传统经颅多普勒超声操作复杂、影像可视化不足的行业难题，以四大创新突破开启诊疗新范式——通过AI技术实现头部三维建模，结合头部智能定位算法大幅提升导航精度，并搭载毫秒级头部动态追踪功能，确保实时跟踪头部运动，AR技术让颅内血管显形、操作可视，真正实现"所见即所得"的精准诊疗。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高运行效：配准时间2秒，跟踪速度＞30Hz；\n高导航精度：定位角误差0.03°，定位误差2.6毫米；\n高灵活性：可与TCD检测系统快速集成，可快速扩展成其他神经外科导航系统。"}, {"title": "技术成熟度", "content": "实验室原理样机。"}, {"title": "项目支持", "content": "国家科技重大专项\n国家自然科学基金\n深圳市科技重大专项"}, {"title": "可应用领域", "content": "经颅多普勒超声检测导航、开颅手术导航、神经外科手术导航"}]', 'negotiable', NULL, NULL, '刘畅', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-29 15:51:24+08', '2025-10-29 15:51:24+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (150, 2, 162, '中国科学院深圳先进技术研究院', '先进光纤传感技术及其海洋监测应用', 9, '围绕海洋复杂应用环境和实时监测需求，结合光纤传感技术优势，从光纤传感器海洋应用的适用性和性能提升方面入手，实现海洋原位多参数（地震、地磁、形变、压力、水听等）光纤传感器及其海洋传感舱应用开发。自主研制的国际最优性能光纤超宽频带海底地震仪，满足我国海洋地震监测需求；海洋超低频光纤水声-地声监测仪器，可实现大型潜航器远距离监听；多种高性能海洋光纤传感器，将成为我国海洋地震台网和海底观测网的物理层支撑。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "超低频：地震至360s，水声至0.1Hz；\n低噪声：国际单位的10-9-10-10量级；\n环境适用性：共模噪声抑制能力强；\n湿端无需供电：全光纤传感探头；\n易分布易组网：与特殊结构匹配的复用技术，适用于大规模全方位监测。"}, {"title": "技术成熟度", "content": "实验样机或工程样机且已在海洋中得到应用验证。"}, {"title": "项目支持", "content": "国家重点研发专项\n中国科学院C先导专项\n中国科学院重点部署科研专项\n广东省重点基金项目\n深圳市基础研究重点项目"}, {"title": "可应用领域", "content": "智慧海洋、智慧城市、地铁隧道、特种设备与特殊结构健康监测、油气安全开采等应用领域。"}]', 'negotiable', NULL, NULL, '崔洪亮', NULL, NULL, 'hl.cui@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:09:48+08', '2025-04-15 14:09:48+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (112, 2, 162, '中国科学院深圳先进技术研究院', '多重核酸检测数字微流控平台试剂盒', 3, '细菌感染每年导致数百万人死亡，传统检测方法耗时、灵敏度低、成本高昂，难以满足快速诊断需求。MiND-DMF平台突破传统局限，融合DNA提取、重组酶聚合酶扩增（RPA）和CRISPR检测技术，实现从样本到结果的全自动化检测流程。仅需55分钟，便能在37°C恒温条件下完成从核酸提取到细菌检测的全过程，检测限低至100 CFU/mL，灵敏度远超传统方法。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "检出限：100 拷贝/毫升；\n成本：量产后< 50 rmb;\n多重能力：单样本7重；\n检测耗时：55 min\n集成度：片上提取、扩增、识别\n便携度：40 × 40 × 40 cm"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "实验室原理样机组件"}, {"title": "可应用领域", "content": "通用型多重核酸检测"}]', 'negotiable', NULL, NULL, '杨慧', NULL, NULL, 'hui.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 17:27:38+08', '2025-07-16 17:27:38+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (218, 2, 162, '中国科学院深圳先进技术研究院', '高性能磷酸锰铁锂技术', 14, '磷酸锰铁锂是磷酸铁锂的升级产品，兼具铁锂优点且具备更高的放电平台，磷酸锰铁锂基电池能量密度接近210Wh/kg。该技术采用聚集诱导成核工艺直接以低品质磷酸为原料先制备出电池级磷酸锰铁前驱体再高温嵌锂形成磷酸锰铁锂，全过程不会产生固废，低品质磷酸利用率超过98%，最终产品具有较高的压实密度(＞2.33g/cm3）、较低的比表面积(＜18g/m2)和较高的比容量0.1C >152 mAh g-1，该产品可以广泛应用于高性能的电动汽车。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "加工性能好，压实密度高，比表面积小，具备良好的加工性能；\n倍率性能优异，离子和电子电导率高，长循环性能良好；\n制备工艺简单，工艺成本低，对原料纯度要求低，适合放大。"}, {"title": "技术成熟度", "content": "完成10kg级小试初步验证"}, {"title": "项目支持", "content": "国家自然科学基金\n中科院深圳先进院优秀青年基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "电动汽车，光储电站，家用储能，二轮电动车，家用电动工具，低速电动车。"}]', 'negotiable', NULL, NULL, '贺兴臣', NULL, NULL, 'xc.he@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 16:56:20+08', '2025-04-14 16:56:20+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (190, 2, 162, '中国科学院深圳先进技术研究院', '柔性三维触觉感知交互', 9, '围绕三维触觉感知交互及应用，结合静电场理论及导电-介电异质结构优势，从多模态神经形态器件设计出发，实现一种可拉伸自供能三维遥感触觉器件的可控制备及其在生物医学、触觉交互领域的创新应用。该器件响应灵敏度高且对非接触物体运动具有精确的逻辑感知能力，通过人工-生物混合系统进行性能验证，突破二维接触式传感器的操控及应用限制。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "三维逻辑感知：感知外界物体运动方向、距离、频率，建立精确逻辑关系；\n人工-生物混合系统 ：神经形态器件\n高普适性：基于静电场原理，适用于大多日常环境\n器件成本低：基于高介电聚合物材料"}, {"title": "技术成熟度", "content": "器件及系统在实验环境中充分验证"}, {"title": "项目支持", "content": "科技部国家重点研发计划课题\n国家自然科学基金面上项目\n广东省自然科学基金\n深圳市基础研究（重点）项目"}, {"title": "可应用领域", "content": "触觉电子、神经形态器件、智能机器人、虚拟现实（VR）和增强现实（AR）"}]', 'negotiable', NULL, NULL, '邰艳龙', NULL, '15900698714', 'yl.tai@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:09:15+08', '2025-04-15 10:09:15+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (142, 2, 162, '中国科学院深圳先进技术研究院', '地震数据非迭代高精度LSM成像与CNN波形反演', 13, '针对主流高精度成像(最小二乘偏移LSM、全波形反演FWI)面临的迭代计算成本高昂等核心问题，首创AD-GRT积分变换，构建角道集与地震数据等价转换，非迭代实现高精度LSM数据拟合与深度学习波形反演，搭建一套弹性介质非迭代高精度成像与反演系统。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低耗时：计算成本比常规LSM和FWI降低2~3量级；\n高精度：计算精度优于常规LSM与FWI；\n高适应性：对稀疏数据、低信噪比实际工业场景具有较高的适用性；\n高灵活性：为地震数据成像与解释提供大量常用有效信息。"}, {"title": "技术成熟度", "content": "复杂模型合成数据与实测地震数据完成验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "海底勘探、高精度成像、地下物性反演、岩性解释"}]', 'negotiable', NULL, NULL, '栗学磊', NULL, '18171042017', 'xl.li@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:26:05+08', '2025-04-15 14:26:05+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (202, 2, 162, '中国科学院深圳先进技术研究院', '智能电驱动车辆高安全运动控制新技术', 9, NULL, NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "附着参数的精准识别方法；\n附着稳定一致性判定新方法；\n多样化路面的稳定控制；\n最佳路面附着利用率；\n增强安全、附着利用率和能量回收。"}, {"title": "技术成熟度", "content": "方法原理性验证；\n算法硬件在环验证；\n系统功能实验验证。"}, {"title": "项目支持", "content": "国家重点研发计划子课题\n国家自然科学基金\n广东省自然科学基金\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "新能源车辆；\n智能车、特种车辆；\n移动机器人等。"}]', 'negotiable', NULL, NULL, '徐坤', NULL, NULL, 'kun.xu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:36:42+08', '2025-04-14 17:36:42+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (188, 2, 162, '中国科学院深圳先进技术研究院', '基于跨模态融合的脊柱侧弯大规模智能筛查系统', 9, '青少年大规模脊柱侧弯筛查，提前对脊柱畸形进行干预，可有效降低脊柱畸形致残率、手术率。基于此，我们研发了基于多模态信息特征融合的大规模智能筛查系统，通过深度相机采集青少年一张背部影像，提出基于二维图像和深度信息融合的方法，智能定位人体脊柱位置，构建不对称性指数，实现快速、精准的脊柱侧弯程度评估。该系统目前已经在多家学校、医院临床应用，筛查精度高达96%。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "单人单次筛查时间小于10ms；\n与临床金标准相比，筛查精度大于等于96%\n系统便携、易使用。"}, {"title": "技术成熟度", "content": "实验室原理样机组件在大规模人群中已经完成验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "脊柱侧弯临床筛查\n脊柱侧凸临床筛查"}]', 'negotiable', NULL, NULL, '胡颖', NULL, NULL, 'ying.hu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:12:51+08', '2025-04-15 10:12:51+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (30, 2, 162, '中国科学院深圳先进技术研究院', '一种微流控芯片及基于微流控芯片的核酸提取方法', 13, '专利号：ZL202011438152.1', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "本专利技术主要应用于现场快速诊断、基层医疗筛查、海关检疫、宠物疾病检测等领域。其核心价值在于将复杂的核酸提取过程集成于一张便携芯片上，摆脱了对大型实验室和专业操作人员的依赖。全球即时检测市场正处于高速增长期，预计2025年将超过500亿美元，其中核酸即时检测是增速最快的细分赛道之一，市场前景极为广阔。"}, {"title": "技术功效与成熟度", "content": "本专利通过独特的硅基微流控芯片的设计，实现了细胞裂解、核酸捕获、纯化与洗脱的全流程自动化和一体化。与传统方法相比，技术功效显著：缩短了核酸提取的时间从1-2小时缩短至15分钟内，样本和试剂消耗量降低90%以上，且操作简便，有效避免了交叉污染。"}, {"title": "技术问题", "content": "现有技术在核酸提取过程中存在成本高、耗时长、错误率高以及标准化程度低的问题，尤其在微量样本中的低含量核酸提取效率不高，难以满足临床检测的需求。"}, {"title": "技术手段", "content": "设计一种微流控芯片，采用微柱阵列结构和表面化学处理技术，通过微柱阵列吸附并洗脱核酸分子，实现微量临床样本的高效提取和分离，结合微流控技术和精密机械等模块，实现自动化和标准化的核酸提取流程。"}]', 'negotiable', NULL, NULL, '杨慧', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:54:46+08', '2025-12-09 18:54:46+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (199, 2, 162, '中国科学院深圳先进技术研究院', '高性能智能下肢假肢', 9, '当前已有的主动下肢假肢大都采用传统的机械设计来实现预期的辅助功能，该类设计思路单一，系统稳定性差，功耗高效率低，进而导致该类假肢在满足设计尺寸和重量的要求下很难提供足够的动力，阻碍该类假肢的推广应用。对此，我们提出采用多学科技术融合，利用学科优势互补的智能下肢假肢将大大解决目前动力假肢领域面临的问题和挑战，提高假肢的辅助性能，增强人机交互，同时降低假肢功耗，从而帮助我国在智能膝关节假肢研发方面取得显著成果，实现高性能医疗设备的自主研发。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "利用多技术融合、学科交叉，显著提高假肢驱动性能，改善人机交互，让假肢穿戴者行走更加轻松、自然"}, {"title": "技术成熟度", "content": "7级\n完成实验样机搭建，并进行了人体临床实验验证"}, {"title": "项目支持", "content": "国家自然科学基金\n中科院百人项目\n广东省“”珠江“青拔项目"}, {"title": "可应用领域", "content": "下肢截肢者"}]', 'negotiable', NULL, NULL, '高飞', NULL, '13928417859', 'fei.gao@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:44:37+08', '2025-04-14 17:44:37+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (115, 2, 162, '中国科学院深圳先进技术研究院', '材料中试智能体', 14, '中试是材料创新链条中最困难的一环，工艺流程复杂、变量因素多。团队基于自研材料创制大模型MARS，结合孵化企业中科先进材料科技有限公司大量的中试和应用数据，构建了系列材料中试智能体MARS-Agent。与大模型相比，MARS-Agent能更为流畅的使用工具和数据，并联合不同模型建立更为复杂的工作流，从而精准推荐材料中试工艺参数及工艺流程。团队已成功开发微球、微胶囊、亲水涂层等多个中试智能体，联合孵化企业成功获批首批国家先进功能材料制造业中试平台。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "定制化解决方案：可根据企业具体应用需求，定制化相关材料产品开发智能体。\n数据安全性：融入RAG即时检索技术，无需企业提供私域数据训练模型。"}, {"title": "技术成熟度", "content": "新材料中试验证效率提升50%，成本降低60%。"}, {"title": "项目支持", "content": "国家先进功能材料制造业中试平台\nSIAT-WIAT人工智能材料创制联合实验室"}, {"title": "可应用领域", "content": "帮助企业开发新材料产品"}]', 'negotiable', NULL, NULL, '喻学锋', NULL, '13971313505', 'xf.yu@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-05-27 22:10:28+08', '2025-05-27 22:10:28+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (198, 2, 162, '中国科学院深圳先进技术研究院', '语音三维可视化技术在言语康复中的应用', 9, '言语交流是人类交流的最重要方式。项目从源头数据开始创新，在多项国家级项目的支持下，突破发声器官三维重建、语音质量客观评价的难点问题，建立针对普通话的语音三维可视化技术和语音质量自动检测技术，并成功应用于言语康复领域。该项目利用人工智能和虚拟现实技术，根据发音运动生理数据，实现了可透视显示、真实准确、覆盖完整的汉语普通话发音动态模拟，以及实时准确的发音质量客观评估方法。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "提出了一种全通路的言语生成生理数据的测量平台，为跨学科研究提供科研设备和分析工具。\n发明了基于深度学习的语音质量客观评估与反馈方法。\n发明了基于康复云的汉语可视化语言障碍康复系统"}, {"title": "技术成熟度", "content": "该项目授权发明专利15项、软件著作权3项，申请发明专利13项，PCT专利6项，获得医疗器械许可证，技术在医疗机构实现全链条应用。大幅度提升了国产设备的技术水平与市场竞争力,取得了可观的经济效益，为实现人人享有健康的社会愿景,也为当前国际竞争新形势下的经济产业发展提供推力。"}, {"title": "可应用领域", "content": "项目实现了普适性、低成本、高效率的言语治疗和康复技术创新，大幅度提升了国产产品的竞争力，对\n于我国言语治疗和康复这一新兴产业的发展有重要意义。"}, {"title": "项目支持", "content": "科技部国家重点研发计划专项"}]', 'negotiable', NULL, NULL, '王岚', NULL, NULL, 'lan.wang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:46:12+08', '2025-04-14 17:46:12+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (204, 2, 162, '中国科学院深圳先进技术研究院', '多模态时空数据生成技术及其停车诱导应用', 9, '城市当中的多模态时空数据，可能由于归属权、隐私等问题导致难以采集，也可能由于相关传感器安装成本、线路故障、处理错误等问题导致数据存在不完备情况。这使得以数据为基础的各类智能算法面临更长的训练时间和在实际应用中更大的误差。多模态时空数据生成技术，可以在短时间、低成本的情况下，生成/修复各时间段甚至更多复杂因素下，如天气、社会事件影响下的城市时空数据，满足各类智能算法的设计和训练，也为各类智慧城市应用的稳定性提供了强有力的支撑。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "多条件约束的时空数据生成：支持定向生成复杂因素下，如天气、社会事件影响下的城市时空数据；\n大范围高精度的时空数据生成：考虑异构数据的非对称影响，结合图聚类的网络拆分，实现大范围高精度的数据生成。"}, {"title": "技术成熟度", "content": "相关时空数据生成算法在真实场景中采集的时空数据集上进行了验证，相关成果小规模的在项目示范应用中得到了应用。"}, {"title": "项目支持", "content": "广东省重点领域研发计划（ 2024B0101020004 ） \n深圳市基础研究重点项目（ JCYJ20180507182628567 ）"}, {"title": "可应用领域", "content": "停车诱导系统中缺失数据修复、智能交通场景中交通趋势预测以及缺失交通流数据修复、移动通信仿真场景中通信需求生成等。"}]', 'negotiable', NULL, NULL, '彭磊', NULL, NULL, 'lei.peng@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:31:25+08', '2025-04-14 17:31:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (207, 2, 162, '中国科学院深圳先进技术研究院', '人工噬菌体防治多重耐药菌感染', 16, '世界卫生组织预计到2050年中国有100万人死于多重耐药细菌的感染，造成的经济损失20万亿美元。噬菌体疗法是临床防治多重耐药细菌感染的重要武器。马迎飞教授团队利用合成生物学对噬菌体基因组进行改造获得人工噬菌体。相比天然噬菌体，人工噬菌体具有更强的杀菌效果，可以更加精准靶向特定细菌，并且安全可控，有望突破现有传统噬菌体疗法的瓶颈，实现噬菌体制剂产品大规模临床应用，产生百亿市场规模。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "利用合成生物学策略构建高效、安全的人工噬菌体，在应用层面为治疗临床耐药菌感染和相关疾病提供新思路和新技术。"}, {"title": "技术成熟度", "content": "研究者发起临床试验阶段，开展超过30例噬菌体疗法临床应用，成功清除多例患者多重耐药菌感染。"}, {"title": "项目支持", "content": "国家重点研发计划\n中科院先导\n深圳市医学研究专项"}, {"title": "可应用领域", "content": "生命健康、畜牧养殖、水产养殖"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '13538190201', 'yingfei.ma@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:23:52+08', '2025-04-14 17:23:52+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (7, 2, 162, '中国科学院深圳先进技术研究院', 'Acoustic Tweezers Transfection Technology Provides Revolutionary Tools for Cell Therapy', 13, 'Transfection technology is a key tool for modifying cell functions in cellular immunotherapy. However, the currently mainly relied-on viral transfection method has led to high costs and limited applications in immunotherapy because the construction of viral vectors is monopolized by large foreign companies. In this project, the acoustic tweezers transfection technology was innovatively adopted to successfully achieve efficient and high-throughput transfection of various immune cells such as primary T cells and macrophages, with the transfection efficiency of T cells reaching up to 81.3%. This technology can not only effectively express the functions of new genes but also does not affect the original biological functions of cells. This breakthrough result has been published in a sub - journal of Science (on the cover), which will provide a brand - new tool for the preparation of CAR - T cells and strongly promote the development of the field of cellular immunotherapy.', NULL, '02_lab', NULL, NULL, '[{"title": "Innovation", "content": "High efficiency: The transfection efficiency reaches 81%.\nLow cost: No special transfection reagent is required.\nHigh universality: Suitable for any cell line and primary cells.\nHigh activity: The activity can be maintained at 85%.\nHigh safety: Stem cells can achieve the function of the target gene without affecting the original biological functions of the cells."}, {"title": "Technology readiness level", "content": "The components of the laboratory principle prototype or the experimental boards are verified in the experimental environment."}, {"title": "Project support", "content": "Major Scientific Instrument Development Project of the National Natural Science Foundation of China\nKey Project of Basic Research in Shenzhen"}, {"title": "Application field", "content": "Research and clinical applications in bioengineering, including ultrasonic biomedicine, cell mechanics, biomedical engineering, cell engineering, genetic engineering, tumor therapy, immunotherapy, etc."}]', 'negotiable', NULL, NULL, 'Meng Long', NULL, NULL, 'long.meng@siat.ac.cn', NULL, 'published', NULL, 1, 1, '2026-05-18 19:24:41+08', '2026-05-18 19:24:41+08', '2026-09-09 17:18:51.936771+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (64, 2, 162, '中国科学院深圳先进技术研究院', '智储慧鉴-基于可信AI的储能系统极早期寿命预测与故障诊断', 14, '随着储能系统在新能源电站、数据中心、园区微网等场景的普及，电池系统的可靠性与安全性成为制约行业高质量发展的关键瓶颈。聚焦锂离子电池及其模组的可靠性评估与寿命预测关键技术，构建了一个融合可信AI算法、动态信息熵分析与多源健康数据建模的“智储慧鉴”平台，实现对储能电池系统的极早期健康预测、全寿命可靠性评估与智能运维决策支持。该技术可在仅使用前10%循环数据的情况下，预测电池的生命周期健康轨迹，并对内短路、热失控等关键故障进行早期识别，实现AUROC 88.7%（AI模型“火眼金睛”程度的关键指标）显著降低系统运行风险与维护成本。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "可靠性分级体系构建\n建立电池可靠性评估，覆盖热安全、循环衰减、制造一致性等多维指标，为系统级安全设计提供优化依据。\nCNN-LSTM+动态信息熵算法创新\n提出基于动态信息熵的锂电池寿命预测模型，显著提升了预测结果的可信度与可解释性；在真实运行数据集上实现88.7% AUROC性能指标，处于国际先进水平。\n极早健康和故障预警机制突破\n仅需前10%循环数据即可预测电池生命周期趋势，为电池设计与资产管理提供前置决策支持。\nAI可解释性与模型透明化\n模型具备可追溯的决策路径与因果链分析能力，便于工程师与安全监管机构理解与验证。"}, {"title": "技术成熟度", "content": "基于Python实现的可靠性评估原型系统，已完成数据验证"}, {"title": "项目支持", "content": "国家重点研发计划（NO.2025YFE0108500）；\n 深圳基础研究重点项目(No.JCYJ20230818103416035)"}, {"title": "可应用领域", "content": "储能电站\n电动汽车"}]', 'negotiable', NULL, NULL, '张艳辉', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 18:06:47+08', '2025-10-30 18:06:47+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (222, 2, 162, '中国科学院深圳先进技术研究院', '靶向肿瘤的纳米光敏制剂', 3, '靶向肿瘤的纳米光敏制剂为恶性肿瘤的检测、诊断和治疗提供了全新的技术手段。实时光学成像与动态示踪为疾病的诊断提供可视化，而结合高温（光热治疗PTT）或光毒性物质（光动力治疗PDT）等光学效应，可实现对疾病部位的精确诊断、靶向递送和精准治疗。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高效：实现肿瘤 原位导航、精准定位、激光消融、实时诊疗、预后评估。\n安全：损伤半径精确，避免对正常组织的损伤\n价廉：为进口产品的1/10。\n广谱：广泛覆盖不同癌症类型"}, {"title": "技术成熟度", "content": "GMP基地完成验收\n中试放大生产线完成验收\n质量管理体系正在建立"}, {"title": "项目支持", "content": "2020/2022 国家重点研发计划\n2021 广东省重点研发计划"}, {"title": "可应用领域", "content": "适用症广，浅表、腔道肿瘤以及微创介入肿瘤均适用，对肺癌、胃癌、食管癌、结肠癌、宫颈癌、脑胶质瘤等高发腔道肿瘤和浅表肿瘤的诊疗具有变革意义。"}]', 'negotiable', NULL, NULL, '蔡林涛', NULL, NULL, 'lt.cai@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 16:02:17+08', '2025-04-14 16:02:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (206, 2, 162, '中国科学院深圳先进技术研究院', '抗真菌药物卡泊芬净前体纽莫康定B0高效生物合成', 16, '纽莫康定B0 （PB0）是一种由Glarea lozoyensis合成的六元环脂肽类化合物，是临床一线抗真菌药物卡泊芬净（Cancidas®）的半合成前体。然而，野生型菌株PB0产量较低，导致卡泊芬净生产成本居高不下。为解决此问题，卞光凯研究员团队以多组学分析为指导，通过对多个限速步骤进行过表达，敲除竞争代谢途径，同时对PB0生物合成基因簇的转录调控进行了优化，构建了高效生产PB0的工业菌株。最终，使PB0的摇瓶产量达到了2.63 g/L，相较出发菌株提高了108.7%。该研究构建了高产PB0的丝状真菌工业菌株，为其他PKS-NRPS杂合产物以及丝状真菌的代谢工程改造提供了借鉴和指导。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "通过基因组、转录组、代谢组等多组学分析，结合竞争代谢途径敲除、转录调控因子激活及代谢途径优化等系统代谢工程改造，实现目标分子纽莫康定B0高效合成。"}, {"title": "技术成熟度", "content": "纽莫康定B0在实验室摇瓶发酵产量达到2.63g/L，为目前文献报道最高产量。"}, {"title": "项目支持", "content": "国家重点研发计划绿色生物制造项目"}, {"title": "可应用领域", "content": "可用作抗真菌药物卡泊芬净原料药。"}]', 'negotiable', NULL, NULL, '卞光凯', NULL, '15827268665', 'gk.bian@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:25:29+08', '2025-04-14 17:25:29+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (44, 2, 162, '中国科学院深圳先进技术研究院', '杀鲑气单胞菌噬菌体、包含其的杀菌组合物及其应用', 16, '专利号：ZL201710250233.0', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "多受体组合噬菌体鸡尾酒拓宽宿主谱、提升裂解覆盖率，优化发酵工艺保障量产与效价稳定，加速进化与益生菌联用可协同克服细菌防御及耐药性，标准化体系确保应用可靠性。技术成熟度较高，核心工艺经体外体内验证，已实现规模化生产，适配水产养殖场景，具备产业化落地基础。"}, {"title": "技术问题", "content": "现有抗生素滥用导致大西洋杀鲑气单胞菌耐药性问题严重，单一噬菌体疗法在应用过程中存在宿主谱范围窄、剂量高和抗性快速发展的缺点，难以有效控制水产养殖中疖疮病及溃肠病。"}, {"title": "应用场景及市场规模", "content": "这些专利产品聚焦水产养殖场景，分别靶向防控杀鲑气单胞菌、副溶血弧菌等致病菌，适配鱼虾蟹等养殖环节，契合 “禁抗” 政策与绿色养殖需求。全球水产噬菌体市场规模 2030年预计达 12 亿美元，其中我国占比超 30%，针对弧菌等核心致病菌的产品年增速超 26%，细分场景需求持续释放。"}, {"title": "技术手段", "content": "开发了一种广谱耐药大西洋杀鲑气单胞菌噬菌体鸡尾酒，通过构建混合噬菌体鸡尾酒，结合特定指标筛选最佳组成，实现对杀鲑气单胞菌、沙门氏杆菌、弧菌及大肠杆菌的高效裂解，弥补单一噬菌体疗法的不足。"}]', 'negotiable', NULL, NULL, '马迎飞', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 18:10:17+08', '2025-12-09 18:10:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (217, 2, 162, '中国科学院深圳先进技术研究院', '新型固态电解质及其固态电池应用', 14, '针对电池行业的“安全”痛点，结合高分子与无机填料的各自优势，从复合物制备及物性提升方面切入，实现高分子-氧化物复合固态电解质的制备及其在固态电池中的应用开发。新型高分子-氧化物复合固态电解质可完美适配目前市售的高电压正极与Li金属负极，目前已实现扣电、软包固态电池的长时间运行。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "低能耗：无需苛刻制备环境；\n成本低：原材料已成功商业化，同时\n        电池制备工艺可兼容传统液\n        态电池产线。\n高性能：离子电导率大于10-3 S/cm"}, {"title": "技术成熟度", "content": "完成复合固态电解质配方优化，工艺定型，实现固态扣式电池前200圈0.5C循环性能不输液态电池，同时建造实验室产线制作小软包电池样品"}, {"title": "可应用领域", "content": "3C产品\n电动汽车\n可再生能源接入端"}]', 'negotiable', NULL, NULL, '边式', NULL, NULL, 'shi.bian@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:00:11+08', '2025-04-14 17:00:11+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (14, 2, 162, '中国科学院深圳先进技术研究院', '机器人多传感器融合定位与自主标定系统专利组合', 9, '该组合包含如下专利：
一种机器人的定位方法、系统及应用
激光雷达和深度相机联合标定的标定板、标定方法和系统
机器人标定装置', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "机器人的自主移动，均涉及到系统的标定、定位导航技术。目前，移动机器人已广泛应用于巡检、搬运、物流、医疗等领域，机器人市场持续增长，技术要求也不断提高。"}, {"title": "技术问题", "content": "现有移动机器人联合标定过程繁琐、数据帧时间不同步；机器人定位精度不高等问题。"}, {"title": "技术手段", "content": "提出激光雷达和深度相机的联合标定方法，简化标定过程。在定位方面，利用紧耦合和松耦合结合的方式融合各传感器位姿，提高机器人定位精度。"}, {"title": "技术功效与成熟度", "content": "相关技术已应用于研制的地铁底部智能巡检机器人、墙面作业机器人、路面划线机器人等系统的定位和控制。"}]', 'negotiable', NULL, NULL, '何凯、周伟等', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-23 14:34:05+08', '2025-12-23 14:34:05+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (16, 2, 162, '中国科学院深圳先进技术研究院', '热电能量转换器件的性能测试、智能控制与封装集成技术专利组合', 14, '该组合包含如下专利：
一种热电制冷器件效能测试装置与测试方法                         一种测量薄膜热导率的装置和方法
一种变温异质界面接触电阻率测试装置与测试方法            一种电池热功率的测试装置及测试方法
一种基于瞬态过冷的热电制冷器自适应控温系统和方法
热电薄膜器件及其制作方法、芯片封装结构和电子设备', NULL, '02_lab', NULL, NULL, '[{"title": "应用场景及市场规模", "content": "应用于5G光通讯、数据中心光模块、医疗PCR、车载冰箱、车载芯片、电池热管理、红外探测等众多小型化、无振动、高精度控温等场景，市场年复增长率>20%，预计到2030年总体规模达>500亿。"}, {"title": "技术问题", "content": "核心技术均已攻克"}, {"title": "技术手段", "content": "核心技术均已攻克"}, {"title": "技术功效与成熟度", "content": "评估热电材料与制冷器件性能、提供高效控温方案与一种新型的应用场景，已完成了设备研发小批量生产，技术成熟度达到9-10级。"}]', 'negotiable', NULL, NULL, '热电智能热管理团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 1, '2025-12-23 10:39:55+08', '2025-12-23 10:39:55+08', '2026-09-11 23:14:45.653967+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (21, 2, 162, '中国科学院深圳先进技术研究院', '一种可实现光学成像的鸡蛋清微阵列芯片及其制备方法', 13, '专利号：ZL202111543898.3', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有水凝胶材料在柔性储能装置中无法同时实现粘与非粘特性，无法满足柔性化学电池和柔性传感器的需求。"}, {"title": "技术功效与成熟度", "content": "本申请提供的生物液微球及其制备方法，将该制作方法简单，所获得的生物液微球具有良好的生物相容性。另外，本申请还提供了基于所述生物液微球的光学成像方法。"}, {"title": "应用场景及市场规模", "content": "超分辨成像、信号增强、传感检测等领域，\n市场规模未知"}, {"title": "技术手段", "content": "通过合成水凝胶前驱体混合物水溶液，包括明胶、聚乙二醇二丙烯酸脂、粘性长链高分子和光引发剂，低温冷凝形成粘性固态水凝胶，并通过紫外光照射形成非粘特性水凝胶，实现粘与非粘特性的共存。"}]', 'negotiable', NULL, NULL, '杨慧团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-10 19:37:44+08', '2025-12-10 19:37:44+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (221, 2, 162, '中国科学院深圳先进技术研究院', '微创智能响应材料与支架修复组织损伤', 3, '针对组织损伤的临床需求，结合智能响应生物材料体系，开发了可注射响应性粘附水凝胶及组织修复支架，实现了快速的损伤封闭组织损伤和止血，构建了微创递送的4D打印组织修复支架，建立了可编程手持打印机实现在体原位生物打印。新型微创智能响应材料和支架体系的开发，有助于推进临床组织修复手术的微创化。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "快速固化：5秒固化，\n高粘附强度：30 kPa\n可降解：1-3个月\n体积稳定：<1%的体积变化率\n变形速度：1min内\n手持打印机：可编程、便携"}, {"title": "技术成熟度", "content": "实验室样品，在动物实验中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n国家重点研发项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "止血、脊髓硬脊膜封闭、皮肤大面积损伤、组织缺损等。"}]', 'negotiable', NULL, NULL, '赵晓丽', NULL, NULL, 'zhao.xl@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 16:06:25+08', '2025-04-14 16:06:25+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (136, 2, 162, '中国科学院深圳先进技术研究院', '基于数据驱动的光伏发电协同调度优化', 9, '光伏发电受季节、昼夜、阴晴等复杂环境因素影响，存在着数据精度低、调度并网难、预警效果差、产能波动大四大核心问题。本项目利用人工智能技术，融合能源流、信息流、价值流，重点突破复杂环境下光伏发电中柔性化、智能化调度问题，实现光伏产业中的产能优化以及消纳提升。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "建立多节点协同的多层次、跨时空、自组织智能感知新模型，构建面向复杂环境的设备柔性化、智能化信息接入新体系，\n揭示多模态时变信息驱动、均衡需求与供给的智能调度新机理。"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "科技部重点研发计划"}, {"title": "可应用领域", "content": "光伏发电调度优化"}]', 'negotiable', NULL, NULL, '张涌', NULL, NULL, 'zhangyong@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:27:18+08', '2025-04-15 14:27:18+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (54, 2, 162, '中国科学院深圳先进技术研究院', '一种机器人控制系统及方法', 16, '专利号：ZL202110431428.1', NULL, '02_lab', NULL, NULL, '[{"title": "技术手段", "content": "采用移动终端、服务器和数据库的组合系统，通过前端界面接收操作人员的指令，服务器进行后端服务处理并存储坐标信息，机器人根据接收到的指令进行动作，简化了机器人操作和编程过程，降低了硬件投入成本。"}, {"title": "技术功效与成熟度", "content": "\"技术功效：​\n简化操作，降低编程门槛；支持坐标序列灵活调整；实现多台机器人服务器的统一调度与协同作业。\n技术成熟度：​\n实施方案完备，已获授权并通过实用性审查，支持商用机器人型号，具备直接落地应用条件。\""}, {"title": "技术问题", "content": "现有技术中协作机器人的编程存在浪费人力、对编程人员专业素养要求高、硬件投入较高、不便于更改动作线路且不利于多个协作机器人配合完成复杂任务的问题。"}, {"title": "应用场景及市场规模", "content": "应用场景：本专利技术聚焦生物实验室自动化，如样本处理、药物筛选等高精度操作，通过机器人控制系统实现数据采集、搬运等流程，提升效率。\n市场规模：通过Web化架构省去专用示教器，降低硬件投入成本，瞄准自动化升级需求，市场潜力显著。"}]', 'negotiable', NULL, NULL, '合成大设施团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 17:54:20+08', '2025-12-09 17:54:20+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (215, 2, 162, '中国科学院深圳先进技术研究院', '膨胀微球', 14, '膨胀微球属于热膨胀型微胶囊范畴，凭借其在减重、隔热、隔音以及减粘等方面所展现出的卓越特性，已然成为极为理想的轻质填料与物理发泡剂，在众多领域具有广泛应用。我院独立自主开发膨胀微球技术体系，产品覆盖低、中、高温区，性能达到国际领先水平，已实现小规模量产及下游验证，后续将与企业合作推进技术产业化。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "外观：白度高，微球球形度好；\n耐高温性：120~230℃；\n粒径范围可调：D50：2~50um；\n膨胀倍率可调：体积倍率5~100倍；\n成本低：可实现国产替代；\n膨胀后应用：无粘连、不塌缩，白度高"}, {"title": "技术成熟度", "content": "高温产品系列实验室产品完成下游试机验证，开展中试放大试验"}, {"title": "可应用领域", "content": "电子胶带、涂料印刷、泡沫工业、鞋材工业、工程塑料等领域应用广泛。"}]', 'negotiable', NULL, NULL, '何睿', NULL, NULL, 'rui.he1@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-14 17:03:41+08', '2025-04-14 17:03:41+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (192, 2, 162, '中国科学院深圳先进技术研究院', '智能灵巧上肢假肢', 9, '结合3D打印技术，研发了多款低成本、轻量型、结构简单、外形仿生的智能假肢手，具有以下亮点：1）降低驱动元，将手部复杂关联运动简化；2）缩减配置传递结构所占空间，力求外形贴合手部外形；3）运动中心贴合与关节中心，提高空间分配及力传递效率；4）兼顾便携及使用便利性。
With 3D printing technology, we have developed multiple low-cost, lightweight, simply structured and bionic intelligent prosthetic hands with the following advantages：1）Reduce driving units and simplify complex coupled hand motions；2）Minimize the space of transmission structures for a better bionic hand shape；3）Align motion centers with joints to improve space utilization and force transmission efficiency；4）Balance portability and ease of use.', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点Technical Innovations", "content": "成人假肢手：五指独立控制、个性化适配，能满足不同程度截肢者的肩、肘、腕等多关节运动功能重建需求\n幼儿假肢手：分相位运动再现技术、高维多动作的低维映射方法、互斥运动的联动方法\nAdult prosthetic hand: with independent five-finger control and personalized adaptation, it realizes multi-joint (shoulder, elbow, wrist) function reconstruction for amputees.\nPediatric prosthetic hand: adopted phase-based motion reproduction, high-dimensional motion low-dimensional mapping and exclusive motion linkage."}, {"title": "技术成熟度Technology Readiness", "content": "成人假肢手：已完成若干成人的穿戴抓握实验，效果良好\n幼儿假肢手：已于日本获得厚生劳动省幼儿义肢辅具认定\nAdult prosthetic hand: Multiple wearable grasping tests completed with satisfactory results.\nPediatric prosthetic hand: Certified as pediatric prosthetic assistive device by Japan MHLW."}, {"title": "项目支持Project Support", "content": "成人假肢手：科技部国家重点研发计划“主动健康与老龄化科技应对”重点专项\n幼儿假肢手：科技部中日政府间国际科技创新合作\n中科院深圳先进院-国际联合实验室培育\n深圳市科创局-中日国际科技合作\nAdult prosthetic hand: Supported by National Key R&D Program of China (Active Health and Aging Response).\nPediatric prosthetic hand: Sino-Japanese international science and technology cooperation;\nJoint laboratory incubation, SIAT CAS;\nSino-Japanese R&D cooperation, Shenzhen Science and Technology Bureau."}, {"title": "可应用领域Applicable Fields", "content": "对手部缺失患者进行运动功能代偿重建、日常运动辅助及物品抓取\nFor patients with hand loss: motor function compensation and reconstruction, daily movement assistance, and object grasping."}]', 'negotiable', NULL, NULL, '李光林', NULL, '13923890192', 'gl.li@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 10:05:30+08', '2025-04-15 10:05:30+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (147, 2, 162, '中国科学院深圳先进技术研究院', '高性能阴离子交换膜电解水关键材料的研发', 14, '以绿氢的低成本制备为导向，基于阴离子交换膜(AEM)电解水的技术优势，开发出高性能低维非贵金属催化材料、高效有序膜电极结构及膜电极原位表征技术，实现了高性能、低成本、长寿命AEM电解池的研发应用。新型高性能AEM电解池具有高电流密度、高产品纯度、快速响应速率等优势，可在纯水工况下利用非贵金属催化剂高效驱动电解水制绿氢。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "非贵金属材料催化剂；\n高工作电流密度 > 1 A/cm2；\n纯水工况，绿氢纯度高；\n宽工况、宽功率工作范围，适应风、光等波动性可再生能源。"}, {"title": "技术成熟度", "content": "催化剂实现规模化制备；\n原型机组装成功，可在实验室模拟工业应用，工况下进行性能测试。"}, {"title": "项目支持", "content": "国家自然科学基金\n中国科学院项目"}, {"title": "可应用领域", "content": "电解水绿氢制备；\n间歇性可再生能源转换与存储。"}]', 'negotiable', NULL, NULL, '金桓宇', NULL, NULL, 'hy.jin2@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:17:17+08', '2025-04-15 14:17:17+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (4, 2, 162, '中国科学院深圳先进技术研究院', 'Self-balancing lower limb exoskeleton robot', 9, 'Oriented toward public health, this work enables quadriplegic patients to stand and walk again via a crutch-free, self-balancing lower-limb exoskeleton system. A multi-center-of-rotation, highly compatible mechanism design methodology was proposed, revealing the compliance mechanisms of muscles and ligaments during locomotion, achieving China''s first self-balanced walking accommodating diverse body types. A hybrid compliant control framework integrating human–robot stability constraints was developed, realizing the world''s first self-balancing exoskeleton walking over unstructured terrain without prior terrain information. This technology substantially alleviates caregiving burdens on families, hospitals, and society, and was awarded the First Prize of the 2023 Guangdong Provincial Technological Invention Award.', NULL, '02_lab', NULL, NULL, '[{"title": "Technical Innovations", "content": "Human–robot compatibility: A 12-DOF serial-parallel hybrid, low-axial-deviation joint design accommodating wearers of 155–180 cm in height;\nWalking adaptability: No individualized calibration required; first in China to achieve self-balanced stable walking for multiple users (0–77 kg);\nTerrain adaptability: Without prior terrain information, first internationally to realize crutch-free self-balancing load-bearing walking across five types of unstructured terrain."}, {"title": "Technology Readiness", "content": "Level 7 \nSystem demonstration in real-world environments."}, {"title": "Project Support", "content": "National Natural Science Foundation of China\nNational Key R&D Program of China\nNatural Science Foundation of Guangdong Province\nShenzhen Basic Research Key Project"}, {"title": "Application Domains", "content": "Hemiplegia, paraplegia, and quadriplegic patients;  medical rehabilitation and functional reconstruction; walking assistance and daily nursing care. Applicable to hospitals, rehabilitation centers, and elderly care facilities."}]', 'negotiable', NULL, NULL, 'Xinyu Wu', NULL, NULL, 'xy.wu@siat.ac.cn', NULL, 'published', NULL, 1, 3, '2026-05-18 20:46:40+08', '2026-05-18 20:46:40+08', '2026-09-11 23:14:28.316316+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (24, 2, 162, '中国科学院深圳先进技术研究院', '一种水下接触压及水深监测一体化传感器', 13, '专利号：ZL202111528710.8', NULL, '02_lab', NULL, NULL, '[{"title": "技术功效与成熟度", "content": "通过设计双通道采集的水下接触压信号和水深信号的传感单元，一方面具备对接触压信号（如脉搏波）的准确采集，一方面反馈当前深度信息。技术当前完成实验室样机制备。"}, {"title": "应用场景及市场规模", "content": "水下压力信息感知对于潜水员生命健康如脉搏波等生理信号至关重要，了解潜水员所处深度位置对于潜水安全具有指导意义。集成的水下接触压及水深监测一体化传感结构针对海洋健康、水肺潜水等市场具备应用价值。"}, {"title": "技术问题", "content": "现有水下压力传感器难以同时采集水深信息和接触压信息，且在高水压环境下灵敏度和分辨率降低，难以分辨水压和接触压信号。"}, {"title": "技术手段", "content": "设计了一种水下接触压及水深监测一体化传感器，采用双面胶结构，叉指电极与离子材料相结合，通过印刷导电材料或激光刻蚀制备柔性电路板，离子材料具有交联网络结构和粗糙表面，形成封闭和开放结构以分别监测水压和接触压信号，利用双通道采集方式获取压力变化。"}]', 'negotiable', NULL, NULL, '程玙团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 19:27:50+08', '2025-12-09 19:27:50+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (138, 2, 162, '中国科学院深圳先进技术研究院', 'CMOS兼容的近红外宽波段探测器及成像芯片', 14, '近红外探测与成像技术可以获得媲美可见光成像的分辨能力，又兼具有红外成像的微光夜视效果及较强的穿透雾霾、水汽能力，是国土安全防御，新一代夜视单兵装备等核心器件，同时在机器视觉、个人智能终端中的需求越来强烈。我们开发了一种新型优良窄带隙p型半导体材料，实现了CMOS晶圆上硅基单片异质集成、低成本、高分辨率近红外阵列成像芯片。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "高分辨率：640*512；\n宽谱响应：300-1600 nm；\n暗电流：≤500 nA/cm2\n峰值量子效率≥60%@1310 nm\n响应时间：~3 ns\n硅基单片异质集成"}, {"title": "技术成熟度", "content": "实验室原理样机组件或实验板在实验环境中验证。"}, {"title": "项目支持", "content": "国家自然科学基金\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "可应用领域", "content": "国防安防、个人智能终端、生物医学、智能驾驶、光通信、具身智能等应用。"}]', 'negotiable', NULL, NULL, '杨春雷', NULL, NULL, 'cl.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:18:38+08', '2025-04-15 14:18:38+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (161, 2, 162, '中国科学院深圳先进技术研究院', '医疗级无创血糖监测技术', 13, '针对医用级连续、无创血糖监测需求，提出一种基于物理（射频）和生理信号驱动的无创血糖监测传感器与系统的设计，解决了无创血糖监测中，血糖波动与无创传感信号响应不明确的科学问题。通过智能传感器和人工智能算法，研究探索了无创血糖监测、无创糖尿病早期筛查和糖尿病筛查、无创糖化血红蛋白分段监测等，开发了基于食物识别的糖尿病患者健康管理系统。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "物理驱动\n生理驱动\n人工智能算法"}, {"title": "技术成熟度", "content": "实验室原理样机\n实验室在体实验\n医院小规模测试"}, {"title": "项目支持", "content": "科技部“主动健康和老龄化科技应对”重点研发专项\n科技部“智能传感器”重点研发专项\n国家自然基金面上项目"}, {"title": "可应用领域", "content": "医院、社区、家用血糖连续监测，糖尿病患者健康管理"}]', 'negotiable', NULL, NULL, '聂泽东', NULL, '13926598060', 'zd.nie@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 13:36:15+08', '2025-04-15 13:36:15+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (118, 2, 162, '中国科学院深圳先进技术研究院', '一种合成甘露醇的重组酵母菌株及其构建方法与应用', 16, '甘露醇(Mannitol)，分子式C6H14O6，是一种天然的六碳糖醇。近年来甘露醇市场规模不断增加，主要应用于食品、医疗以及制药等领域。在食品行业，由于具有低升糖指数及低热量值，甘露醇作为甜味剂的食品在糖尿病患者及健身人士中广受欢迎；另外，甘露醇因其非致龋性已在无糖口香糖中应用。临床医疗上，甘露醇注射液可作为利尿剂，也可用于降低颅内压和眼内压。在制药行业，甘露醇因其低吸湿性常作为压片赋形剂。本项目通过构建新型毕赤酵母工程菌，实现了以葡萄糖为原料生产甘露醇，该法绿色、环保、可持续，并且与化学法相比，具有经济竞争力，有很好的产业应用前景。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "采用先进代谢工程与合成生物学技术，基于从头理性设计和系统优化，成功开发出高效合成甘露醇的酵母工程菌。该菌株以葡萄糖无机盐培养基生产甘露醇，目前在 15 L 发酵罐水平，通过分批补料的方式，实现甘露醇产量突破 220 g/L的关键指标，且甘露醇对葡萄糖的转化率在70%左右。相较于化学合成法，该生物制造体系转化率更高，同时兼备环境友好属性与技术创新优势。"}, {"title": "技术成熟度", "content": "在实验室内实现甘露醇的公斤级制备，目前已进入中试发酵测试阶段。"}, {"title": "可应用领域", "content": "甘露醇可用于食品、医疗以及制药等领域。基于高产甘露醇工程菌构建的糖醇生物合成技术平台，可延伸开发多元化糖醇生物合成谱系（包括山梨醇、木糖醇等高附加值多元醇），建立环境友好型糖基化学品绿色生物制造范式。"}]', 'negotiable', NULL, NULL, '于涛', NULL, NULL, 'tao.yu@siat.ac.cn', NULL, 'published', NULL, 1, 1, '2025-06-18 04:06:15+08', '2025-06-18 04:06:15+08', '2026-09-11 16:26:50.734044+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (26, 2, 162, '中国科学院深圳先进技术研究院', '基于微瓶透镜的超分辨成像方法和系统', 13, '专利号：ZL202210356445.8', NULL, '02_lab', NULL, NULL, '[{"title": "技术问题", "content": "现有微粒透镜辅助的超分辨成像技术中，球、柱类型的微粒透镜在光照下形成的紧聚焦光束焦距小、工作距离短，导致成像时容易与样品接触或摩擦，造成扫描成像困难、污染和损伤，操作过程缓慢且不易控制。"}, {"title": "技术功效与成熟度", "content": "本发明利用电介质微瓶透镜，结合常规的光学显微镜，构建基于长焦深和长工作距离微粒透镜辅助的超分辨成像方法和系统，能够对低于衍射极限尺度的样品实现非接触、无损、无污染的成像，有望推动微粒透镜辅助的超分辨成像技术向更贴近实际应用的方向发展。目前技术成熟度为实验室概念验证阶段。"}, {"title": "应用场景", "content": "超分辨成像、信号增强、传感检测等领域"}, {"title": "技术手段", "content": "采用基于微瓶透镜的超分辨成像系统，包括微瓶透镜模块和位置控制模块，微瓶透镜由微光纤和包覆的聚合物液体膜组成，通过3D纳米平移台精细调节微瓶透镜的位置，结合常规光学显微镜实现非接触、无损的超分辨成像。"}]', 'negotiable', NULL, NULL, '杨慧团队', NULL, '18002564875', NULL, NULL, 'published', NULL, 1, 0, '2025-12-09 19:00:39+08', '2025-12-09 19:00:39+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (111, 2, 162, '中国科学院深圳先进技术研究院', 'AI辅助多重核酸检测试剂盒用', 3, '开发了一种基于人工智能（AI）辅助的多重核酸检测试剂盒，通过整合高通量核酸检测技术与AI算法分析，实现对多种病原体核酸的快速、准确、便捷检测。该试剂盒采用RPA等温扩增与CRISPR-Cas系统相结合的技术路径，通过AI图像识别和数据分析，自动判读检测结果，大幅度提升多重病原体检测的灵敏度、特异性及操作便捷性，适用于呼吸道感染、创伤感染、肠道病原体等多类感染性疾病的现场快速筛查与精准诊断。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "检出限：100 拷贝/毫升；\n成本：量产后< 20 rmb;\n多重能力：单样本6重；\n检测耗时：30 min\n便携度：手持（30 × 20× 10 cm）"}, {"title": "项目支持", "content": "国家自然科学基金\n科技部重点研发\n广东省创业科研团队计划项目\n广东省科技规划项目\n深圳市基础研究项目"}, {"title": "技术成熟度", "content": "实验室原理样机组件"}, {"title": "可应用领域", "content": "通用型多重核酸检测"}]', 'negotiable', NULL, NULL, '杨慧', NULL, NULL, 'hui.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-07-16 17:30:29+08', '2025-07-16 17:30:29+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (144, 2, 162, '中国科学院深圳先进技术研究院', '低温传感用多级热电致冷器件', 14, '在红外热成像、气体检测、以及低温量子传感器件对便携式微型化致冷技术提出了越来越迫切的需求；多级热电致冷器件具有微型化、快响应、全静态特性，可以实现低至-100°C的低温，大大提高低温传感器的信噪比和灵敏度。
所开发的3-6级多级致冷器件可以实现140K以上的最大致冷温差，有望推动太赫兹芯片、红外遥感探测的变革性发展。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "级数：3-6级\n致冷温差（@300K）：\n3级：T~105K \n4级：T~127K\n5级：T~138K\n6级：T~146K"}, {"title": "技术成熟度", "content": "器件小批量定制\n技术成熟度：5级"}, {"title": "项目支持", "content": "国家重点研发计划\n国家自然科学基金\n广东省重点领域研发计划项目\n深圳市基础研究项目"}]', 'negotiable', NULL, NULL, '先进电子封装材料团队', NULL, NULL, 'ead.siem@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 14:22:05+08', '2025-04-15 14:22:05+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (168, 2, 162, '中国科学院深圳先进技术研究院', '高清晰高灵敏MRI兼容脑部专用PET成像仪器', 15, 'PET和MRI分别都是脑神经成像的重要工具，同时PET/MRI成像为脑疾病的早期精准诊断、治疗的早期评估和脑科学研究提供一台强大的工具。本项目采用创新的高三维位置分辨率探测器和磁兼容电子学，填补了我国在高端MRI兼容脑部专用PET功能成像仪器研发方面的空白，仪器的空间分辨率和效率都达到国际先进水平。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "采用基于双端读出的高分辨率三维PET探测器，PET成像仪器同时达到整个成像视野均匀高清晰和高灵敏。"}, {"title": "技术成熟度", "content": "2022完成样机，完成自愿者同时PET/MRI成像，仪器性能测试结果2024年在国际期刊发表。"}, {"title": "项目支持", "content": "深圳市孔雀团队\n国家自然科学基金重大科研仪器\n中国科学院仪器研制团队"}, {"title": "可应用领域", "content": "脑疾病早期精准诊断、治疗早期评估和脑科学研究等。"}]', 'negotiable', NULL, NULL, '杨永峰', NULL, '13802279548', 'yf.yang@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-04-15 11:33:24+08', '2025-04-15 11:33:24+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (68, 2, 162, '中国科学院深圳先进技术研究院', '新型海量数据的快速聚类算法及其应用', 9, '围绕海量数据实时、快速处理的需求，创造性地将内核密度估计相关理论引入聚类算法设计，并结合谱图稀疏算法的快速构造方法，提出了国际上首个具有线性时间复杂度的聚类算法。该算法在实现海量数据高速聚类的同时，显著提升了聚类结果的精确度和细致度，实际性能远超国际现有同类算法。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "理论创新：将内核密度估计的相关理论和谱图稀疏算法的快速构造理论引入聚类算法的设计，以突破传统聚类算法高时间复杂度的瓶颈。\n低运行时间：算法的时间复杂度为输入输入的线性函数；这是国际上首个线性时间的海量数据聚类算法。\n高精度图像分割：图像分割的精细程度明显优于包括SK-Learn在内的国际主流非监督学习的图像分割程序库。"}, {"title": "技术成熟度", "content": "算法已经成功融入我们自主研发的谱图算法图书馆(STAG)、以供用户直接应用。"}, {"title": "可应用领域", "content": "海量数据分析、数据压缩与存储、多媒体数据的聚类与分割"}]', 'negotiable', NULL, NULL, '孙贺', NULL, '13554946780', 'wb.li6@siat.ac.cn', NULL, 'published', NULL, 1, 0, '2025-10-30 17:49:13+08', '2025-10-30 17:49:13+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);
INSERT INTO public.achievement VALUES (123, 2, 162, '中国科学院深圳先进技术研究院', '后台新增成果测试-已编辑', 9, '专利作为保护创新成果的重要法律工具，其传统的撰写工作通常由熟悉专利法律和技术领域的专利代理人完成，这一过程耗时费力、效率较低。AutoPatent框架能够一键自动化生成高质量的万字专利文档，大幅提高专利撰写效率，简化专利申请流程，降低成本，促进创新保护。', NULL, '02_lab', NULL, NULL, '[{"title": "技术创新点", "content": "大模型驱动的多智能体协同框架\n优秀的超长文本生成能力\n审查，规划，撰写三大类智能体协作\n迭代提升专利撰写质量"}, {"title": "技术成熟度", "content": "已经通过实验验证，达到行业领先水平"}, {"title": "项目支持", "content": "博士后面上基金\n广东省面上基金\n广东省青年基金"}, {"title": "可应用领域", "content": "知识产权服务领域\n技术保护领域"}]', 'transfer', 20.00, 50.00, '倪仕文', NULL, '15827639393', 'sw.ni@siat.ac.cn', NULL, 'published', NULL, 2, 0, '2025-06-18 03:56:56+08', '2025-06-18 03:56:56+08', '2026-09-08 12:55:18.396866+08', NULL, 2, 'parallel', NULL, NULL, NULL, NULL, 'technology', NULL, NULL);


